globalThis.SOLUTIONS = {"Sum":{"idea":"Add the two supplied numbers directly. No loop or extra data structure is needed","steps":["Add the two supplied numbers directly.","No loop or extra data structure is needed."],"time":"O(1)","space":"O(1)","python":"def sum_two(a, b):\n    return a + b","js":"function sumTwo(a,b) { return a+b; }","cpp":"long long sumTwo(long long a,long long b) { return a+b; }","statement":"Return the sum of the supplied numbers a and b.","example":"a = 4, b = 7 → 11"},"Second Largest":{"idea":"Only decimal digits contribute to the answer. Record which of the ten digits appear, then scan from nine down to zero and return the second distinct digit encountered, or -1 if fewer than two appear.","steps":["Mark every digit that occurs in the input string.","Scan possible digits in descending order.","Return the second encountered digit, or -1 if it does not exist."],"time":"O(n)","space":"O(1)","python":"def second_highest(s):\n    digits = {int(c) for c in s if '0' <= c <= '9'}\n    ordered = sorted(digits, reverse=True)\n    return ordered[1] if len(ordered) >= 2 else -1","js":"function secondHighest(s) {\n  const seen=Array(10).fill(false);\n  for(const c of s)if(c>='0'&&c<='9')seen[Number(c)]=true;\n  let count=0;for(let d=9;d>=0;d--)if(seen[d]&&++count===2)return d;return -1;\n}","cpp":"int secondHighest(string s) {\n  bool seen[10]={};for(char c:s)if(c>='0'&&c<='9')seen[c-'0']=true;\n  int count=0;for(int d=9;d>=0;d--)if(seen[d]&&++count==2)return d;return -1;\n}","statement":"Find the second largest distinct numerical digit in an alphanumeric string. The source sheet labels this row Second Largest; this lesson follows its linked Second Largest Digit in a String problem.","example":"s = \"dfa12321afd\" → 2"},"Palindrome Number":{"idea":"Negative numbers cannot read the same backwards because of the minus sign. Reverse only half of the digits, then compare the halves and discard the middle digit for odd lengths","steps":["Negative numbers cannot read the same backwards because of the minus sign.","Reverse only half of the digits, then compare the halves and discard the middle digit for odd lengths."],"time":"O(log x)","space":"O(1)","python":"def is_palindrome(x):\n    if x < 0 or (x % 10 == 0 and x != 0): return False\n    half = 0\n    while x > half:\n        half = half * 10 + x % 10\n        x //= 10\n    return x == half or x == half // 10","js":"function isPalindrome(x) {\n  if(x<0 || (x%10===0 && x!==0)) return false;\n  let half=0;\n  while(x>half) {half=half*10+x%10;x=Math.floor(x/10);}\n  return x===half || x===Math.floor(half/10);\n}","cpp":"bool isPalindrome(int x) {\n  if(x<0 || (x%10==0 && x!=0)) return false;\n  int half=0;\n  while(x>half) {half=half*10+x%10;x/=10;}\n  return x==half || x==half/10;\n}","statement":"Return whether an integer reads the same from left to right and right to left.","example":"x = 121 → true; x = -121 → false"},"Reverse Integer":{"idea":"Remove the final digit and append it to the reversed number. Preserve the sign and return zero if the reversed value exceeds the signed 32-bit range","steps":["Remove the final digit and append it to the reversed number.","Preserve the sign and return zero if the reversed value exceeds the signed 32-bit range."],"time":"O(log |x|)","space":"O(1)","python":"def reverse_integer(x):\n    sign = -1 if x < 0 else 1\n    x, result = abs(x), 0\n    while x:\n        result = result * 10 + x % 10\n        x //= 10\n    result *= sign\n    return result if -(2**31) <= result < 2**31 else 0","js":"function reverseInteger(x) {\n  const sign=Math.sign(x); x=Math.abs(x);let r=0;\n  while(x) {r=r*10+x%10;x=Math.floor(x/10);}\n  r*=sign;return r>=-(2**31)&&r<2**31?r:0;\n}","cpp":"int reverseInteger(int x) {\n  long long r=0;\n  while(x) {r=r*10+x%10;x/=10;}\n  return r<INT_MIN || r>INT_MAX?0:(int)r;\n}","statement":"Reverse the decimal digits of a signed 32-bit integer; return zero if the result is outside the signed 32-bit range.","example":"x = -120 → -21"},"Count Negative Numbers in an Array":{"idea":"Inspect every element once. Increment the count exactly when the element is less than zero","steps":["Inspect every element once.","Increment the count exactly when the element is less than zero."],"time":"O(n)","space":"O(1)","python":"def count_negatives(nums):\n    return sum(x < 0 for x in nums)","js":"function countNegatives(a) {let n=0;for(const x of a) if(x<0)n++;return n;}","cpp":"int countNegatives(const vector<int>& a) {int n=0;for(int x:a) n+=x<0;return n;}","statement":"Count how many values in an array are strictly less than zero.","example":"nums = [-2, 0, 5, -7] → 2"},"Find Smallest Number in an Array":{"idea":"Start with the first element as the current answer. Compare every remaining element and keep the smaller value; the input must be nonempty","steps":["Start with the first element as the current answer.","Compare every remaining element and keep the smaller value; the input must be nonempty."],"time":"O(n)","space":"O(1)","python":"def find_min(nums):\n    if not nums: raise ValueError(\"empty array\")\n    return min(nums)","js":"function findMin(a) {\n  if(!a.length) throw Error(\"empty array\");\n  let best=a[0]; for(const x of a) best=Math.min(best,x);return best;\n}","cpp":"int findMin(const vector<int>& a) {\n  if(a.empty()) throw invalid_argument(\"empty array\");\n  int best=a[0];for(int x:a) best=min(best,x);return best;\n}","statement":"Return the smallest value in a nonempty array.","example":"nums = [4, -2, 9] → -2"},"Find Largest Number in an Array":{"idea":"Start with the first element as the current answer. Compare every remaining element and keep the larger value; the input must be nonempty","steps":["Start with the first element as the current answer.","Compare every remaining element and keep the larger value; the input must be nonempty."],"time":"O(n)","space":"O(1)","python":"def find_max(nums):\n    if not nums: raise ValueError(\"empty array\")\n    return max(nums)","js":"function findMax(a) {\n  if(!a.length) throw Error(\"empty array\");\n  let best=a[0]; for(const x of a) best=Math.max(best,x);return best;\n}","cpp":"int findMax(const vector<int>& a) {\n  if(a.empty()) throw invalid_argument(\"empty array\");\n  int best=a[0];for(int x:a) best=max(best,x);return best;\n}","statement":"Return the largest value in a nonempty array.","example":"nums = [4, -2, 9] → 9"},"Binary Search":{"idea":"Maintain an inclusive interval in a sorted array. Compare the middle value with the target and discard the half that cannot contain the target","steps":["Maintain an inclusive interval in a sorted array.","Compare the middle value with the target and discard the half that cannot contain the target."],"time":"O(log n)","space":"O(1)","python":"def binary_search(nums, target):\n    lo, hi = 0, len(nums)-1\n    while lo <= hi:\n        mid = lo + (hi-lo)//2\n        if nums[mid] == target: return mid\n        if nums[mid] < target: lo = mid+1\n        else: hi = mid-1\n    return -1","js":"function binarySearch(a,target) {\n  let lo=0,hi=a.length-1;\n  while(lo<=hi) {\n    const m=lo+Math.floor((hi-lo)/2);\n    if(a[m]===target)return m;\n    if(a[m]<target)lo=m+1;else hi=m-1;\n  }return -1;\n}","cpp":"int binarySearch(const vector<int>& a,int target) {\n  int lo=0,hi=(int)a.size()-1;\n  while(lo<=hi) {int m=lo+(hi-lo)/2;\n    if(a[m]==target)return m;\n    if(a[m]<target)lo=m+1;else hi=m-1;\n  }return -1;\n}","statement":"Find the index of target in an ascending sorted array of distinct integers, or return -1 if absent.","example":"nums = [1, 3, 5, 7], target = 5 → 2"},"Merge Sort":{"idea":"Split the array until each piece has at most one element. Merge sorted halves by repeatedly taking the smaller front value","steps":["Split the array until each piece has at most one element.","Merge sorted halves by repeatedly taking the smaller front value."],"time":"O(n log n)","space":"O(n)","python":"def merge_sort(a):\n    if len(a) <= 1: return a[:]\n    m = len(a)//2\n    left, right = merge_sort(a[:m]), merge_sort(a[m:])\n    i = j = 0; out = []\n    while i < len(left) and j < len(right):\n        if left[i] <= right[j]: out.append(left[i]); i += 1\n        else: out.append(right[j]); j += 1\n    return out + left[i:] + right[j:]","js":"function mergeSort(a) {\n  if(a.length<2)return a.slice();\n  const m=Math.floor(a.length/2),l=mergeSort(a.slice(0,m)),r=mergeSort(a.slice(m));\n  let i=0,j=0,out=[];\n  while(i<l.length&&j<r.length)out.push(l[i]<=r[j]?l[i++]:r[j++]);\n  return out.concat(l.slice(i),r.slice(j));\n}","cpp":"vector<int> mergeSort(vector<int> a) {\n  if(a.size()<2)return a;\n  int m=a.size()/2;\n  auto l=mergeSort(vector<int>(a.begin(),a.begin()+m));\n  auto r=mergeSort(vector<int>(a.begin()+m,a.end()));\n  vector<int> out;int i=0,j=0;\n  while(i<(int)l.size()&&j<(int)r.size())out.push_back(l[i]<=r[j]?l[i++]:r[j++]);\n  out.insert(out.end(),l.begin()+i,l.end());out.insert(out.end(),r.begin()+j,r.end());return out;\n}","statement":"Return an ascending sorted copy of an integer array using divide and conquer.","example":"nums = [4, 1, 3, 2] → [1, 2, 3, 4]"},"Power of Two":{"idea":"A positive power of two has exactly one set bit. Clearing the lowest set bit with n AND (n-1) therefore leaves zero","steps":["A positive power of two has exactly one set bit.","Clearing the lowest set bit with n AND (n-1) therefore leaves zero."],"time":"O(1) for fixed-width integers","space":"O(1)","python":"def is_power_of_two(n):\n    return n > 0 and (n & (n - 1)) == 0","js":"function isPowerOfTwo(n) {return Number.isSafeInteger(n)&&n>0&&(BigInt(n)&(BigInt(n)-1n))===0n;}","cpp":"bool isPowerOfTwo(int n) {return n>0 && (n&(n-1))==0;}","statement":"Return whether n is a positive integer equal to two raised to a nonnegative integer power.","example":"n = 16 → true; n = 12 → false"},"Remove Duplicates":{"idea":"The input is sorted, so equal values are adjacent. Write each value that differs from the previous accepted value into the next free prefix position and return the prefix length","steps":["The input is sorted, so equal values are adjacent.","Write each value that differs from the previous accepted value into the next free prefix position and return the prefix length."],"time":"O(n)","space":"O(1)","python":"def remove_duplicates(nums):\n    k = 0\n    for x in nums:\n        if k == 0 or x != nums[k-1]:\n            nums[k] = x; k += 1\n    return k","js":"function removeDuplicates(a) {\n  let k=0;for(const x of a)if(k===0||x!==a[k-1])a[k++]=x;\n  return k;\n}","cpp":"int removeDuplicates(vector<int>& a) {\n  int k=0;for(int x:a)if(k==0||x!=a[k-1])a[k++]=x;return k;\n}","statement":"Remove repeated values from a sorted array in place. Return k such that its first k elements contain the distinct values in order.","example":"nums = [1, 1, 2] → k = 2, prefix = [1, 2]"},"Remove Element":{"idea":"Keep a write index for values that differ from val. Scan once and compact those values into the array prefix; elements after the returned length are irrelevant","steps":["Keep a write index for values that differ from val.","Scan once and compact those values into the array prefix; elements after the returned length are irrelevant."],"time":"O(n)","space":"O(1)","python":"def remove_element(nums, val):\n    k = 0\n    for x in nums:\n        if x != val: nums[k] = x; k += 1\n    return k","js":"function removeElement(a,val) {\n  let k=0;for(const x of a)if(x!==val)a[k++]=x;return k;\n}","cpp":"int removeElement(vector<int>& a,int val) {\n  int k=0;for(int x:a)if(x!=val)a[k++]=x;return k;\n}","statement":"Remove every occurrence of val from an array in place, returning the number of retained values.","example":"nums = [3, 2, 2, 3], val = 3 → k = 2, prefix = [2, 2]"},"Reverse String":{"idea":"Use two indices at opposite ends of the character array. Swap their values and move them inward until they meet","steps":["Use two indices at opposite ends of the character array.","Swap their values and move them inward until they meet."],"time":"O(n)","space":"O(1)","python":"def reverse_string(chars):\n    l, r = 0, len(chars)-1\n    while l < r:\n        chars[l], chars[r] = chars[r], chars[l]\n        l += 1; r -= 1","js":"function reverseString(a) {\n  for(let l=0,r=a.length-1;l<r;l++,r--)[a[l],a[r]]=[a[r],a[l]];\n}","cpp":"void reverseString(vector<char>& a) {\n  for(int l=0,r=(int)a.size()-1;l<r;l++,r--)swap(a[l],a[r]);\n}","statement":"Reverse an array of characters in place.","example":"chars = [\"h\", \"i\"] → [\"i\", \"h\"]"},"Best Time to Buy and Sell Stocks":{"idea":"Keep the cheapest price seen before each selling day. The difference between today and that minimum is the best profit ending today; keep the largest such profit","steps":["Keep the cheapest price seen before each selling day.","The difference between today and that minimum is the best profit ending today; keep the largest such profit."],"time":"O(n)","space":"O(1)","python":"def max_profit(prices):\n    low = float('inf'); best = 0\n    for price in prices:\n        low = min(low, price)\n        best = max(best, price-low)\n    return best","js":"function maxProfit(prices) {\n  let low=Infinity,best=0;\n  for(const p of prices){low=Math.min(low,p);best=Math.max(best,p-low);}return best;\n}","cpp":"int maxProfit(vector<int>& prices) {\n  int low=INT_MAX,best=0;for(int p:prices){low=min(low,p);best=max(best,p-low);}return best;\n}","statement":"Choose one buying day and a later selling day to maximize profit, or return zero if no profitable trade exists.","example":"prices = [7, 1, 5, 3, 6, 4] → 5"},"Merge Sorted Arrays":{"idea":"The first array has room for both sorted sequences. Fill it backwards, taking the larger remaining element, so unread values are never overwritten","steps":["The first array has room for both sorted sequences.","Fill it backwards, taking the larger remaining element, so unread values are never overwritten."],"time":"O(m+n)","space":"O(1)","python":"def merge_sorted(nums1, m, nums2, n):\n    i, j, k = m-1, n-1, m+n-1\n    while j >= 0:\n        if i >= 0 and nums1[i] > nums2[j]:\n            nums1[k] = nums1[i]; i -= 1\n        else: nums1[k] = nums2[j]; j -= 1\n        k -= 1","js":"function mergeSorted(a,m,b,n) {\n  let i=m-1,j=n-1,k=m+n-1;\n  while(j>=0)a[k--]=i>=0&&a[i]>b[j]?a[i--]:b[j--];\n}","cpp":"void mergeSorted(vector<int>& a,int m,vector<int>& b,int n) {\n  int i=m-1,j=n-1,k=m+n-1;\n  while(j>=0)a[k--]=i>=0&&a[i]>b[j]?a[i--]:b[j--];\n}","statement":"Merge sorted nums2 into sorted nums1 in place. nums1 has m initialized values and space for n additional values.","example":"nums1 = [1, 3, 0, 0], m = 2, nums2 = [2, 4], n = 2 → [1, 2, 3, 4]"},"Move Zeros":{"idea":"Compact all nonzero values into the prefix while retaining their relative order. Fill the remaining suffix with zeros","steps":["Compact all nonzero values into the prefix while retaining their relative order.","Fill the remaining suffix with zeros."],"time":"O(n)","space":"O(1)","python":"def move_zeros(nums):\n    k = 0\n    for x in nums:\n        if x != 0: nums[k] = x; k += 1\n    for i in range(k, len(nums)): nums[i] = 0","js":"function moveZeros(a) {\n  let k=0;for(const x of a)if(x!==0)a[k++]=x;\n  while(k<a.length)a[k++]=0;\n}","cpp":"void moveZeros(vector<int>& a) {\n  int k=0;for(int x:a)if(x)a[k++]=x;\n  while(k<(int)a.size())a[k++]=0;\n}","statement":"Move all zeros to the end in place while preserving the relative order of nonzero values.","example":"nums = [0, 1, 0, 3, 12] → [1, 3, 12, 0, 0]"},"Max Consecutive Ones":{"idea":"Track the length of the current run of ones. A zero resets that run; update the maximum after every element","steps":["Track the length of the current run of ones.","A zero resets that run; update the maximum after every element."],"time":"O(n)","space":"O(1)","python":"def max_consecutive_ones(nums):\n    run = best = 0\n    for x in nums:\n        run = run+1 if x == 1 else 0\n        best = max(best, run)\n    return best","js":"function maxConsecutiveOnes(a) {\n  let run=0,best=0;for(const x of a){run=x===1?run+1:0;best=Math.max(best,run);}return best;\n}","cpp":"int maxConsecutiveOnes(vector<int>& a) {\n  int run=0,best=0;for(int x:a){run=x==1?run+1:0;best=max(best,run);}return best;\n}","statement":"Return the longest contiguous run of ones in a binary array.","example":"nums = [1, 1, 0, 1, 1, 1] → 3"},"Missing Number":{"idea":"The input contains distinct values from zero through n with one omitted. XOR every index and every value together with n; equal values cancel, leaving the missing number","steps":["The input contains distinct values from zero through n with one omitted.","XOR every index and every value together with n; equal values cancel, leaving the missing number."],"time":"O(n)","space":"O(1)","python":"def missing_number(nums):\n    ans = len(nums)\n    for i, x in enumerate(nums): ans ^= i ^ x\n    return ans","js":"function missingNumber(a) {\n  let ans=a.length;for(let i=0;i<a.length;i++)ans^=i^a[i];return ans;\n}","cpp":"int missingNumber(vector<int>& a) {\n  int ans=a.size();for(int i=0;i<(int)a.size();i++)ans^=i^a[i];return ans;\n}","statement":"An array of n distinct values is drawn from 0 through n. Return the one value that is missing.","example":"nums = [3, 0, 1] → 2"},"Single Number":{"idea":"Every other value occurs exactly twice. XOR is associative and x XOR x is zero, so XORing the entire array leaves the unique value","steps":["Every other value occurs exactly twice.","XOR is associative and x XOR x is zero, so XORing the entire array leaves the unique value."],"time":"O(n)","space":"O(1)","python":"def single_number(nums):\n    ans = 0\n    for x in nums: ans ^= x\n    return ans","js":"function singleNumber(a) {let ans=0;for(const x of a)ans^=x;return ans;}","cpp":"int singleNumber(vector<int>& a) {int ans=0;for(int x:a)ans^=x;return ans;}","statement":"Every integer in the array occurs exactly twice except one. Return that single value.","example":"nums = [4, 1, 2, 1, 2] → 4"},"Design Linked List":{"idea":"Use a sentinel before the head so insertions and removals share one rule. Walk to the predecessor of an index, then change its next pointer; reject invalid indices","steps":["Use a sentinel before the head so insertions and removals share one rule.","Walk to the predecessor of an index, then change its next pointer; reject invalid indices."],"time":"O(n) indexed operations; O(1) addAtHead","space":"O(n)","python":"class MyLinkedList:\n    class Node:\n        def __init__(self, val=0, nxt=None): self.val, self.next = val, nxt\n    def __init__(self): self.head, self.size = self.Node(), 0\n    def get(self, index):\n        if not 0 <= index < self.size: return -1\n        cur = self.head.next\n        for _ in range(index): cur = cur.next\n        return cur.val\n    def addAtHead(self, val): self.addAtIndex(0, val)\n    def addAtTail(self, val): self.addAtIndex(self.size, val)\n    def addAtIndex(self, index, val):\n        if index > self.size: return\n        index = max(0, index); cur = self.head\n        for _ in range(index): cur = cur.next\n        cur.next = self.Node(val, cur.next); self.size += 1\n    def deleteAtIndex(self, index):\n        if not 0 <= index < self.size: return\n        cur = self.head\n        for _ in range(index): cur = cur.next\n        cur.next = cur.next.next; self.size -= 1","js":"class MyLinkedList {\n  constructor(){this.head={val:0,next:null};this.size=0;}\n  get(i){if(i<0||i>=this.size)return -1;let p=this.head.next;while(i--)p=p.next;return p.val;}\n  addAtHead(v){this.addAtIndex(0,v);}\n  addAtTail(v){this.addAtIndex(this.size,v);}\n  addAtIndex(i,v){if(i>this.size)return;i=Math.max(0,i);let p=this.head;while(i--)p=p.next;p.next={val:v,next:p.next};this.size++;}\n  deleteAtIndex(i){if(i<0||i>=this.size)return;let p=this.head;while(i--)p=p.next;p.next=p.next.next;this.size--;}\n}","cpp":"class MyLinkedList {\n  struct Node {int val;Node* next;Node(int v=0,Node* n=nullptr):val(v),next(n){}};\n  Node* head=new Node();int size=0;\npublic:\n  ~MyLinkedList(){while(head){Node* p=head;head=head->next;delete p;}}\n  int get(int i){if(i<0||i>=size)return -1;Node* p=head->next;while(i--)p=p->next;return p->val;}\n  void addAtHead(int v){addAtIndex(0,v);}\n  void addAtTail(int v){addAtIndex(size,v);}\n  void addAtIndex(int i,int v){if(i>size)return;i=max(0,i);Node* p=head;while(i--)p=p->next;p->next=new Node(v,p->next);size++;}\n  void deleteAtIndex(int i){if(i<0||i>=size)return;Node* p=head;while(i--)p=p->next;Node* q=p->next;p->next=q->next;delete q;size--;}\n};","statement":"Implement get, addAtHead, addAtTail, addAtIndex, and deleteAtIndex for a zero-indexed linked list. Invalid gets return -1; invalid deletions do nothing.","example":"addAtHead(1), addAtTail(3), addAtIndex(1,2), get(1) → 2"},"Middle of Linked List":{"idea":"Move a slow pointer one node and a fast pointer two nodes at a time. When fast reaches the end, slow is at the middle, choosing the second middle for even lengths","steps":["Move a slow pointer one node and a fast pointer two nodes at a time.","When fast reaches the end, slow is at the middle, choosing the second middle for even lengths."],"time":"O(n)","space":"O(1)","python":"def middle_node(head):\n    slow = fast = head\n    while fast and fast.next:\n        slow, fast = slow.next, fast.next.next\n    return slow","js":"function middleNode(head) {\n  let slow=head,fast=head;\n  while(fast&&fast.next){slow=slow.next;fast=fast.next.next;}return slow;\n}","cpp":"ListNode* middleNode(ListNode* head) {\n  auto slow=head,fast=head;while(fast&&fast->next){slow=slow->next;fast=fast->next->next;}return slow;\n}","statement":"Return the middle node of a singly linked list; for even length, return the second middle node.","example":"1 → 2 → 3 → 4 → returned node has value 3"},"Reverse Linked List":{"idea":"Save the next node before changing the current link. Point the current node at the reversed prefix, then advance both pointers","steps":["Save the next node before changing the current link.","Point the current node at the reversed prefix, then advance both pointers."],"time":"O(n)","space":"O(1)","python":"def reverse_list(head):\n    prev = None\n    while head:\n        nxt = head.next\n        head.next = prev\n        prev, head = head, nxt\n    return prev","js":"function reverseList(head) {\n  let prev=null;\n  while(head){const next=head.next;head.next=prev;prev=head;head=next;}return prev;\n}","cpp":"ListNode* reverseList(ListNode* head) {\n  ListNode* prev=nullptr;while(head){auto next=head->next;head->next=prev;prev=head;head=next;}return prev;\n}","statement":"Reverse the links in a singly linked list and return the new head.","example":"1 → 2 → 3 → null becomes 3 → 2 → 1 → null"},"Linked List Cycle":{"idea":"A fast pointer gains one node on a slow pointer each iteration. They must meet inside a cycle; reaching null proves that no cycle exists","steps":["A fast pointer gains one node on a slow pointer each iteration.","They must meet inside a cycle; reaching null proves that no cycle exists."],"time":"O(n)","space":"O(1)","python":"def has_cycle(head):\n    slow = fast = head\n    while fast and fast.next:\n        slow, fast = slow.next, fast.next.next\n        if slow is fast: return True\n    return False","js":"function hasCycle(head) {\n  let slow=head,fast=head;\n  while(fast&&fast.next){slow=slow.next;fast=fast.next.next;if(slow===fast)return true;}return false;\n}","cpp":"bool hasCycle(ListNode* head) {\n  auto slow=head,fast=head;while(fast&&fast->next){slow=slow->next;fast=fast->next->next;if(slow==fast)return true;}return false;\n}","statement":"Determine whether following next pointers in a linked list eventually revisits the same node.","example":"1 → 2 → 3 with 3.next pointing to node 2 → true"},"Palindrome Linked List":{"idea":"Collect the node values in traversal order. Compare values at mirrored positions; this straightforward approach preserves all input links","steps":["Collect the node values in traversal order.","Compare values at mirrored positions; this straightforward approach preserves all input links."],"time":"O(n)","space":"O(n)","python":"def is_palindrome_list(head):\n    values = []\n    while head: values.append(head.val); head = head.next\n    return values == values[::-1]","js":"function isPalindromeList(head) {\n  const a=[];while(head){a.push(head.val);head=head.next;}\n  for(let l=0,r=a.length-1;l<r;l++,r--)if(a[l]!==a[r])return false;return true;\n}","cpp":"bool isPalindromeList(ListNode* head) {\n  vector<int>a;while(head){a.push_back(head->val);head=head->next;}\n  for(int l=0,r=(int)a.size()-1;l<r;l++,r--)if(a[l]!=a[r])return false;return true;\n}","statement":"Return whether the node values in a singly linked list form a palindrome.","example":"1 → 2 → 2 → 1 → true"},"Intersection of two Linked Lists":{"idea":"Switch each pointer to the other list after it reaches null. Both pointers then travel equal total distances and meet at the shared node or at null; compare node identity, not values","steps":["Switch each pointer to the other list after it reaches null.","Both pointers then travel equal total distances and meet at the shared node or at null; compare node identity, not values."],"time":"O(m+n)","space":"O(1)","python":"def get_intersection(a, b):\n    p, q = a, b\n    while p is not q:\n        p = p.next if p else b\n        q = q.next if q else a\n    return p","js":"function getIntersection(a,b) {\n  let p=a,q=b;while(p!==q){p=p?p.next:b;q=q?q.next:a;}return p;\n}","cpp":"ListNode* getIntersection(ListNode* a,ListNode* b) {\n  auto p=a,q=b;while(p!=q){p=p?p->next:b;q=q?q->next:a;}return p;\n}","statement":"Return the first node shared by two acyclic singly linked lists, or null if there is no shared node. Node identity matters.","example":"A = 1 → shared(8 → 9), B = 2 → 3 → shared(8 → 9) → shared node 8"},"Remove Linked List Elements":{"idea":"Place a dummy node before the head. When the next node matches the target, bypass it; otherwise advance the predecessor","steps":["Place a dummy node before the head.","When the next node matches the target, bypass it; otherwise advance the predecessor."],"time":"O(n)","space":"O(1)","python":"def remove_elements(head, val):\n    dummy = ListNode(0, head); p = dummy\n    while p.next:\n        if p.next.val == val: p.next = p.next.next\n        else: p = p.next\n    return dummy.next","js":"function removeElements(head,val) {\n  const dummy={next:head};let p=dummy;\n  while(p.next){if(p.next.val===val)p.next=p.next.next;else p=p.next;}return dummy.next;\n}","cpp":"ListNode* removeElements(ListNode* head,int val) {\n  ListNode dummy(0,head);auto p=&dummy;\n  while(p->next){if(p->next->val==val)p->next=p->next->next;else p=p->next;}return dummy.next;\n}","statement":"Remove every node with value val from a singly linked list and return the new head.","example":"head = 1 → 6 → 2 → 6, val = 6 → 1 → 2"},"Remove nth node from end of List":{"idea":"Advance a fast pointer n nodes ahead of a slow pointer at a dummy head. Move both until fast is at the final node, then bypass the node after slow; n must be valid","steps":["Advance a fast pointer n nodes ahead of a slow pointer at a dummy head.","Move both until fast is at the final node, then bypass the node after slow; n must be valid."],"time":"O(n)","space":"O(1)","python":"def remove_nth_from_end(head, n):\n    dummy = ListNode(0, head); slow = fast = dummy\n    for _ in range(n): fast = fast.next\n    while fast.next: slow, fast = slow.next, fast.next\n    slow.next = slow.next.next\n    return dummy.next","js":"function removeNthFromEnd(head,n) {\n  const dummy={next:head};let slow=dummy,fast=dummy;\n  for(let i=0;i<n;i++)fast=fast.next;\n  while(fast.next){slow=slow.next;fast=fast.next;}slow.next=slow.next.next;return dummy.next;\n}","cpp":"ListNode* removeNthFromEnd(ListNode* head,int n) {\n  ListNode dummy(0,head);auto slow=&dummy,fast=&dummy;\n  while(n--)fast=fast->next;while(fast->next){slow=slow->next;fast=fast->next;}slow->next=slow->next->next;return dummy.next;\n}","statement":"Remove the nth node counted from the end of a linked list; n is between 1 and the list length.","example":"head = 1 → 2 → 3 → 4, n = 2 → 1 → 2 → 4"},"Remove Duplicates from Sorted List":{"idea":"Duplicate values are adjacent in a sorted list. Keep a pointer at the current distinct value and bypass following nodes while they repeat it","steps":["Duplicate values are adjacent in a sorted list.","Keep a pointer at the current distinct value and bypass following nodes while they repeat it."],"time":"O(n)","space":"O(1)","python":"def delete_duplicates(head):\n    p = head\n    while p and p.next:\n        if p.val == p.next.val: p.next = p.next.next\n        else: p = p.next\n    return head","js":"function deleteDuplicates(head) {\n  let p=head;while(p&&p.next){if(p.val===p.next.val)p.next=p.next.next;else p=p.next;}return head;\n}","cpp":"ListNode* deleteDuplicates(ListNode* head) {\n  auto p=head;while(p&&p->next){if(p->val==p->next->val)p->next=p->next->next;else p=p->next;}return head;\n}","statement":"Keep one node for each distinct value in a sorted singly linked list.","example":"1 → 1 → 2 → 3 → 3 becomes 1 → 2 → 3"},"Odd Even Linked List":{"idea":"Group nodes by their one-based position, not their value. Build an odd-position chain and an even-position chain in place, then join the odd tail to the saved even head","steps":["Group nodes by their one-based position, not their value.","Build an odd-position chain and an even-position chain in place, then join the odd tail to the saved even head."],"time":"O(n)","space":"O(1)","python":"def odd_even_list(head):\n    if not head: return head\n    odd, even = head, head.next\n    even_head = even\n    while even and even.next:\n        odd.next = even.next; odd = odd.next\n        even.next = odd.next; even = even.next\n    odd.next = even_head\n    return head","js":"function oddEvenList(head) {\n  if(!head)return head;\n  let odd=head,even=head.next;const evenHead=even;\n  while(even&&even.next){odd.next=even.next;odd=odd.next;even.next=odd.next;even=even.next;}\n  odd.next=evenHead;return head;\n}","cpp":"ListNode* oddEvenList(ListNode* head) {\n  if(!head)return head;auto odd=head,even=head->next,evenHead=even;\n  while(even&&even->next){odd->next=even->next;odd=odd->next;even->next=odd->next;even=even->next;}\n  odd->next=evenHead;return head;\n}","statement":"Group nodes at odd one-based positions before nodes at even positions, preserving order inside both groups.","example":"1 → 2 → 3 → 4 → 5 becomes 1 → 3 → 5 → 2 → 4"},"Add Two Numbers":{"idea":"The lists store digits from least significant to most significant. Add corresponding digits and carry, append the remainder modulo ten, then pass the quotient to the next position","steps":["The lists store digits from least significant to most significant.","Add corresponding digits and carry, append the remainder modulo ten, then pass the quotient to the next position."],"time":"O(max(m,n))","space":"O(max(m,n)) output","python":"def add_two_numbers(a, b):\n    dummy = ListNode(); tail = dummy; carry = 0\n    while a or b or carry:\n        total = carry\n        if a: total += a.val; a = a.next\n        if b: total += b.val; b = b.next\n        carry, digit = divmod(total, 10)\n        tail.next = ListNode(digit); tail = tail.next\n    return dummy.next","js":"function addTwoNumbers(a,b) {\n  const dummy={next:null};let tail=dummy,carry=0;\n  while(a||b||carry){let total=carry;if(a){total+=a.val;a=a.next;}if(b){total+=b.val;b=b.next;}\n    carry=Math.floor(total/10);tail.next={val:total%10,next:null};tail=tail.next;}return dummy.next;\n}","cpp":"ListNode* addTwoNumbers(ListNode* a,ListNode* b) {\n  ListNode dummy;auto tail=&dummy;int carry=0;\n  while(a||b||carry){int sum=carry;if(a){sum+=a->val;a=a->next;}if(b){sum+=b->val;b=b->next;}\n    carry=sum/10;tail->next=new ListNode(sum%10);tail=tail->next;}return dummy.next;\n}","statement":"Two linked lists store nonnegative integers with digits in reverse order. Return a new list representing their sum in reverse digit order.","example":"[2,4,3] + [5,6,4] represents 342 + 465 → [7,0,8]"},"Merge Two Sorted Lists":{"idea":"Use a dummy head and append the smaller current node from either list. Once one list is empty, attach the other suffix directly","steps":["Use a dummy head and append the smaller current node from either list.","Once one list is empty, attach the other suffix directly."],"time":"O(m+n)","space":"O(1)","python":"def merge_two_lists(a, b):\n    dummy = ListNode(); tail = dummy\n    while a and b:\n        if a.val <= b.val: tail.next = a; a = a.next\n        else: tail.next = b; b = b.next\n        tail = tail.next\n    tail.next = a or b\n    return dummy.next","js":"function mergeTwoLists(a,b) {\n  const dummy={next:null};let tail=dummy;\n  while(a&&b){if(a.val<=b.val){tail.next=a;a=a.next;}else{tail.next=b;b=b.next;}tail=tail.next;}\n  tail.next=a||b;return dummy.next;\n}","cpp":"ListNode* mergeTwoLists(ListNode* a,ListNode* b) {\n  ListNode dummy;auto tail=&dummy;\n  while(a&&b){if(a->val<=b->val){tail->next=a;a=a->next;}else{tail->next=b;b=b->next;}tail=tail->next;}\n  tail->next=a?a:b;return dummy.next;\n}","statement":"Merge two ascending sorted singly linked lists by relinking their nodes.","example":"[1,3,5] and [2,4] → [1,2,3,4,5]"},"Rotate List":{"idea":"Find the length and reduce k modulo that length. Temporarily connect the tail to the head, walk to the new tail at length minus k minus one, then break the circle","steps":["Find the length and reduce k modulo that length.","Temporarily connect the tail to the head, walk to the new tail at length minus k minus one, then break the circle."],"time":"O(n)","space":"O(1)","python":"def rotate_right(head, k):\n    if not head or not head.next: return head\n    tail, n = head, 1\n    while tail.next: tail = tail.next; n += 1\n    k %= n\n    if k == 0: return head\n    tail.next = head; tail = head\n    for _ in range(n-k-1): tail = tail.next\n    head = tail.next; tail.next = None\n    return head","js":"function rotateRight(head,k) {\n  if(!head||!head.next)return head;let tail=head,n=1;\n  while(tail.next){tail=tail.next;n++;}k%=n;if(!k)return head;\n  tail.next=head;tail=head;for(let i=0;i<n-k-1;i++)tail=tail.next;\n  head=tail.next;tail.next=null;return head;\n}","cpp":"ListNode* rotateRight(ListNode* head,int k) {\n  if(!head||!head->next)return head;auto tail=head;int n=1;\n  while(tail->next){tail=tail->next;n++;}k%=n;if(!k)return head;\n  tail->next=head;tail=head;for(int i=0;i<n-k-1;i++)tail=tail->next;\n  head=tail->next;tail->next=nullptr;return head;\n}","statement":"Rotate a singly linked list right by k positions, with k nonnegative.","example":"head = [1,2,3,4,5], k = 2 → [4,5,1,2,3]"},"Swap Nodes in Pairs":{"idea":"A dummy head gives access to the link before every pair. For nodes a and b, connect the predecessor to b, b to a, and a to the next pair; leave an unpaired final node unchanged","steps":["A dummy head gives access to the link before every pair.","For nodes a and b, connect the predecessor to b, b to a, and a to the next pair; leave an unpaired final node unchanged."],"time":"O(n)","space":"O(1)","python":"def swap_pairs(head):\n    dummy = ListNode(0, head); p = dummy\n    while p.next and p.next.next:\n        a, b = p.next, p.next.next\n        a.next = b.next; b.next = a; p.next = b\n        p = a\n    return dummy.next","js":"function swapPairs(head) {\n  const dummy={next:head};let p=dummy;\n  while(p.next&&p.next.next){const a=p.next,b=a.next;a.next=b.next;b.next=a;p.next=b;p=a;}\n  return dummy.next;\n}","cpp":"ListNode* swapPairs(ListNode* head) {\n  ListNode dummy(0,head);auto p=&dummy;\n  while(p->next&&p->next->next){auto a=p->next,b=a->next;a->next=b->next;b->next=a;p->next=b;p=a;}\n  return dummy.next;\n}","statement":"Swap each adjacent pair of nodes by changing links; leave an unpaired final node unchanged.","example":"[1,2,3,4,5] → [2,1,4,3,5]"},"Length of Last Word":{"idea":"Scan backward past trailing spaces, then count characters until the next space.","steps":["Start at the final character and skip trailing spaces.","Count backward until a space or the start of the string.","Return that count, including zero for an empty/all-space string."],"time":"O(n)","space":"O(1)","cpp":"int lengthOfLastWord(string s) {\n    int i=(int)s.size()-1, n=0;\n    while(i>=0 && s[i]==' ') --i;\n    while(i>=0 && s[i]!=' ') { ++n; --i; }\n    return n;\n}","js":"function lengthOfLastWord(s) {\n  let i=s.length-1, n=0;\n  while(i>=0 && s[i]===' ') i--;\n  while(i>=0 && s[i]!==' ') { n++; i--; }\n  return n;\n}","python":"def lengthOfLastWord(s):\n    i, count = len(s)-1, 0\n    while i >= 0 and s[i] == ' ': i -= 1\n    while i >= 0 and s[i] != ' ':\n        count += 1\n        i -= 1\n    return count","statement":"Given a string containing words and spaces, return the length of its last word. A word is a maximal sequence of non-space characters.","example":"Input: s = \"Hello World  \" → Output: 5"},"Find Words Containing Character":{"idea":"Test each word for the target character and collect its index.","steps":["Enumerate words together with their original indices.","Search each word for x and retain matching indices.","Return indices in original order."],"time":"O(total characters)","space":"O(k) output","cpp":"vector<int> findWordsContaining(vector<string>& words, char x) {\n    vector<int> ans;\n    for(int i=0;i<(int)words.size();++i)\n        if(words[i].find(x)!=string::npos) ans.push_back(i);\n    return ans;\n}","js":"function findWordsContaining(words, x) {\n  return words.flatMap((w,i)=>w.includes(x) ? [i] : []);\n}","python":"def findWordsContaining(words, x):\n    return [i for i, word in enumerate(words) if x in word]","statement":"Given an array of words and a character x, return the indices of all words containing x.","example":"Input: words = [\"leet\", \"code\"], x = \"e\" → Output: [0, 1]"},"Jewels and Stones":{"idea":"Store the jewel characters in a set, then count stones that belong to it.","steps":["Build a set of distinct jewel characters.","Check each stone for set membership.","Sum the successful checks; repeated stones each count."],"time":"O(j+s)","space":"O(j)","cpp":"int numJewelsInStones(string jewels, string stones) {\n    unordered_set<char> j(jewels.begin(),jewels.end());\n    int ans=0;\n    for(char c:stones) ans+=j.count(c);\n    return ans;\n}","js":"function numJewelsInStones(jewels, stones) {\n  const set=new Set(jewels);\n  return [...stones].reduce((n,c)=>n+Number(set.has(c)),0);\n}","python":"def numJewelsInStones(jewels, stones):\n    jewel_set = set(jewels)\n    return sum(c in jewel_set for c in stones)","statement":"Each character in jewels identifies a jewel type. Count how many characters in stones are jewels; uppercase and lowercase letters are distinct.","example":"Input: jewels = \"aA\", stones = \"aAAbbbb\" → Output: 3"},"Find Most Frequent Vowel and Consonant":{"idea":"Count lowercase letter frequencies, find the largest vowel count and consonant count separately, and add them.","steps":["Count occurrences of every lowercase letter.","Find the maximum frequency among vowels and among consonants.","Add the two maxima; a missing category contributes zero."],"time":"O(n)","space":"O(1)","cpp":"int maxFreqSum(string s) {\n    int f[26]={},v=0,c=0;\n    for(char ch:s) ++f[ch-'a'];\n    string vowels=\"aeiou\";\n    for(int i=0;i<26;++i)\n        if(vowels.find(char('a'+i))!=string::npos) v=max(v,f[i]);\n        else c=max(c,f[i]);\n    return v+c;\n}","js":"function maxFreqSum(s) {\n  const f=new Map(); for(const c of s) f.set(c,(f.get(c)||0)+1);\n  let v=0,k=0;\n  for(const [c,n] of f) {\n    if('aeiou'.includes(c)) v=Math.max(v,n); else k=Math.max(k,n);\n  }\n  return v+k;\n}","python":"def maxFreqSum(s):\n    from collections import Counter\n    f = Counter(s)\n    return max((f[c] for c in 'aeiou'), default=0) + max((n for c,n in f.items() if c not in 'aeiou'), default=0)","statement":"For a lowercase string, add the highest frequency of any vowel to the highest frequency of any consonant. A missing category contributes zero.","example":"Input: s = \"successes\" → Output: 6 (e occurs 2 times and s occurs 4 times)"},"Split a String in Balanced Strings":{"idea":"Treat L as +1 and R as -1. Every return to zero closes the earliest balanced piece, maximizing the number of pieces.","steps":["Initialize balance and answer to zero.","Add one for L and subtract one for R.","Whenever balance reaches zero, close a piece and increase the answer."],"time":"O(n)","space":"O(1)","cpp":"int balancedStringSplit(string s) {\n    int balance=0,ans=0;\n    for(char c:s) { balance+=c=='L'?1:-1; if(!balance) ++ans; }\n    return ans;\n}","js":"function balancedStringSplit(s) {\n  let balance=0,ans=0;\n  for(const c of s) { balance+=c==='L'?1:-1; if(balance===0) ans++; }\n  return ans;\n}","python":"def balancedStringSplit(s):\n    balance = ans = 0\n    for c in s:\n        balance += 1 if c == 'L' else -1\n        ans += balance == 0\n    return ans","statement":"Given a balanced string made of L and R, split it into the maximum number of nonempty substrings, each with equal numbers of L and R.","example":"Input: s = \"RLRRLLRLRL\" → Output: 4"},"Reverse String II":{"idea":"In every block of 2k characters, reverse its first k characters, or all remaining characters if fewer than k remain.","steps":["Walk block starts in increments of 2k.","Reverse characters from the block start through min(start+k,n)-1.","Leave the second half of each block unchanged."],"time":"O(n)","space":"O(n) for immutable strings","cpp":"string reverseStr(string s, int k) {\n    for(int i=0;i<(int)s.size();i+=2*k)\n        reverse(s.begin()+i,s.begin()+min(i+k,(int)s.size()));\n    return s;\n}","js":"function reverseStr(s,k) {\n  const a=s.split('');\n  for(let i=0;i<a.length;i+=2*k)\n    for(let l=i,r=Math.min(i+k,a.length)-1;l<r;l++,r--)\n      [a[l],a[r]]=[a[r],a[l]];\n  return a.join('');\n}","python":"def reverseStr(s, k):\n    a = list(s)\n    for i in range(0, len(a), 2*k): a[i:i+k] = reversed(a[i:i+k])\n    return ''.join(a)","statement":"Given a string and positive integer k, reverse the first k characters in every block of 2k characters. If fewer than k remain, reverse all remaining characters.","example":"Input: s = \"abcdefg\", k = 2 → Output: \"bacdfeg\""},"Valid Palindrome":{"idea":"Move two pointers inward, skipping non-alphanumeric characters. Compare the remaining characters without case differences. This implementation assumes ASCII input.","steps":["Place pointers at both ends.","Skip ASCII punctuation and spaces, then compare lowercase letters/digits.","Reject a mismatch; otherwise move inward until the pointers meet."],"time":"O(n)","space":"O(1)","cpp":"bool isPalindrome(string s) {\n    int l=0,r=(int)s.size()-1;\n    while(l<r) {\n        while(l<r && !isalnum((unsigned char)s[l])) ++l;\n        while(l<r && !isalnum((unsigned char)s[r])) --r;\n        if(tolower((unsigned char)s[l++])!=tolower((unsigned char)s[r--])) return false;\n    }\n    return true;\n}","js":"function isPalindrome(s) {\n  let l=0,r=s.length-1;\n  const valid=c=>/[a-z0-9]/i.test(c);\n  while(l<r) {\n    while(l<r && !valid(s[l])) l++;\n    while(l<r && !valid(s[r])) r--;\n    if(s[l++].toLowerCase()!==s[r--].toLowerCase()) return false;\n  }\n  return true;\n}","python":"def isPalindrome(s):\n    l, r = 0, len(s)-1\n    valid = lambda c: c.isascii() and c.isalnum()\n    while l < r:\n        while l < r and not valid(s[l]): l += 1\n        while l < r and not valid(s[r]): r -= 1\n        if s[l].lower() != s[r].lower(): return False\n        l += 1\n        r -= 1\n    return True","statement":"Return whether the string reads the same forward and backward after ignoring non-alphanumeric ASCII characters and letter case.","example":"Input: s = \"A man, a plan, a canal: Panama\" → Output: true"},"Largest Odd Number in a String":{"idea":"The largest odd substring is the prefix ending at the rightmost odd digit; extending left preserves oddness and increases the value.","steps":["Scan digit positions from right to left.","At the first odd digit, return the prefix ending there.","Return an empty string if every digit is even."],"time":"O(n)","space":"O(n) output","cpp":"string largestOddNumber(string num) {\n    for(int i=(int)num.size()-1;i>=0;--i)\n        if((num[i]-'0')%2) return num.substr(0,i+1);\n    return \"\";\n}","js":"function largestOddNumber(num) {\n  for(let i=num.length-1;i>=0;i--) if(Number(num[i])%2) return num.slice(0,i+1);\n  return '';\n}","python":"def largestOddNumber(num):\n    for i in range(len(num)-1, -1, -1):\n        if int(num[i]) % 2: return num[:i+1]\n    return '' ","statement":"Given a string of decimal digits, return its numerically largest nonempty odd-valued substring, or an empty string if none exists.","example":"Input: num = \"3542\" → Output: \"35\""},"Longest Common Prefix":{"idea":"Compare every string with the first string and shrink the candidate prefix length at the first mismatch.","steps":["Use the first string length as the initial bound.","Compare each subsequent word against the first until a mismatch.","Shrink the bound and return the first string sliced to it."],"time":"O(total characters)","space":"O(p) output","cpp":"string longestCommonPrefix(vector<string>& a) {\n    if(a.empty()) return \"\";\n    int n=a[0].size();\n    for(int i=1;i<(int)a.size();++i) {\n        int j=0; while(j<n && j<(int)a[i].size() && a[0][j]==a[i][j]) ++j;\n        n=j;\n    }\n    return a[0].substr(0,n);\n}","js":"function longestCommonPrefix(a) {\n  if(!a.length) return '';\n  let n=a[0].length;\n  for(const s of a) { let j=0; while(j<n && j<s.length && s[j]===a[0][j]) j++; n=j; }\n  return a[0].slice(0,n);\n}","python":"def longestCommonPrefix(a):\n    if not a: return ''\n    n = len(a[0])\n    for s in a[1:]:\n        j = 0\n        while j < n and j < len(s) and s[j] == a[0][j]: j += 1\n        n = j\n    return a[0][:n]","statement":"Return the longest prefix shared by every string in an array. Return an empty string when no common prefix exists.","example":"Input: words = [\"flower\", \"flow\", \"flight\"] → Output: \"fl\""},"Valid Anagram":{"idea":"Two strings are anagrams exactly when their character frequency maps are equal.","steps":["Check character multiplicities, rather than character order.","Increment counts for s and decrement for t.","Accept only if no unmatched count remains."],"time":"O(n+m)","space":"O(alphabet)","cpp":"bool isAnagram(string s, string t) {\n    if(s.size()!=t.size()) return false;\n    int f[256]={};\n    for(unsigned char c:s) ++f[c];\n    for(unsigned char c:t) if(--f[c]<0) return false;\n    return true;\n}","js":"function isAnagram(s,t) {\n  const f=new Map();\n  for(const c of s) f.set(c,(f.get(c)||0)+1);\n  for(const c of t) { if(!f.get(c)) return false; f.set(c,f.get(c)-1); }\n  return [...f.values()].every(n=>n===0);\n}","python":"def isAnagram(s, t):\n    from collections import Counter\n    return Counter(s) == Counter(t)","statement":"Return whether t is a rearrangement of all characters in s, with exactly the same character multiplicities.","example":"Input: s = \"anagram\", t = \"nagaram\" → Output: true"},"Isomorphic Strings":{"idea":"Maintain mappings in both directions. A character must always map to the same partner, and two source characters cannot share one target.","steps":["Track source-to-target and target-to-source consistency.","For each position, reject a mapping that conflicts with an earlier position.","Record the pair and accept after all positions agree."],"time":"O(n)","space":"O(alphabet)","cpp":"bool isIsomorphic(string s, string t) {\n    if(s.size()!=t.size()) return false;\n    int a[256]={},b[256]={};\n    for(int i=0;i<(int)s.size();++i) {\n        unsigned char x=s[i],y=t[i];\n        if(a[x]!=b[y]) return false;\n        a[x]=b[y]=i+1;\n    }\n    return true;\n}","js":"function isIsomorphic(s,t) {\n  if(s.length!==t.length) return false;\n  const a=new Map(),b=new Map();\n  for(let i=0;i<s.length;i++) {\n    if(a.get(s[i])!==b.get(t[i])) return false;\n    a.set(s[i],i); b.set(t[i],i);\n  }\n  return true;\n}","python":"def isIsomorphic(s, t):\n    if len(s) != len(t): return False\n    a, b = {}, {}\n    for x, y in zip(s,t):\n        if x in a and a[x] != y: return False\n        if y in b and b[y] != x: return False\n        a[x], b[y] = y, x\n    return True","statement":"Return whether characters in s can be replaced consistently to form t. Each source character maps to exactly one target character, and distinct source characters must have distinct targets.","example":"Input: s = \"egg\", t = \"add\" → Output: true"},"Group Anagrams":{"idea":"Sort the characters of each word to create a canonical key. Words with the same key belong in the same group.","steps":["Sort the characters in each word to get its signature.","Append the original word to the bucket for that signature.","Return all buckets; bucket order does not matter."],"time":"O(sum(k log k))","space":"O(total characters)","cpp":"vector<vector<string>> groupAnagrams(vector<string>& words) {\n    unordered_map<string,vector<string>> groups;\n    for(auto s:words) { string k=s; sort(k.begin(),k.end()); groups[k].push_back(s); }\n    vector<vector<string>> ans;\n    for(auto &p:groups) ans.push_back(p.second);\n    return ans;\n}","js":"function groupAnagrams(words) {\n  const groups=new Map();\n  for(const s of words) { const k=[...s].sort().join(''); if(!groups.has(k)) groups.set(k,[]); groups.get(k).push(s); }\n  return [...groups.values()];\n}","python":"def groupAnagrams(words):\n    from collections import defaultdict\n    groups = defaultdict(list)\n    for s in words: groups[''.join(sorted(s))].append(s)\n    return list(groups.values())","statement":"Group an array of strings so that words containing exactly the same characters and multiplicities appear together. Group order may vary.","example":"Input: words = [\"eat\", \"tea\", \"tan\", \"ate\"] → Output: [[\"eat\", \"tea\", \"ate\"], [\"tan\"]]"},"Minimum Add to Make Parentheses Valid":{"idea":"Track unmatched opening parentheses. An unmatched closing parenthesis requires an inserted opening one; remaining openings require closing ones.","steps":["Count unmatched opening parentheses.","Consume an opening for every close, or add one if none exists.","Add the remaining unmatched openings to the insertion count."],"time":"O(n)","space":"O(1)","cpp":"int minAddToMakeValid(string s) {\n    int open=0,add=0;\n    for(char c:s) { if(c=='(') ++open; else if(open) --open; else ++add; }\n    return open+add;\n}","js":"function minAddToMakeValid(s) {\n  let open=0,add=0;\n  for(const c of s) { if(c==='(') open++; else if(open) open--; else add++; }\n  return open+add;\n}","python":"def minAddToMakeValid(s):\n    opened = added = 0\n    for c in s:\n        if c == '(': opened += 1\n        elif opened: opened -= 1\n        else: added += 1\n    return opened + added","statement":"Given a string containing only opening and closing parentheses, return the minimum number of parentheses to insert to make it valid.","example":"Input: s = \"()))((\" → Output: 4"},"Reverse Words in a String":{"idea":"Split on whitespace, reverse the word order, and join with a single space. Leading, trailing, and repeated spaces disappear.","steps":["Read nonempty words separated by whitespace.","Reverse the list of words.","Join with one space, discarding leading/trailing spaces."],"time":"O(n)","space":"O(n)","cpp":"string reverseWords(string s) {\n    istringstream in(s); vector<string> words; string w,ans;\n    while(in>>w) words.push_back(w);\n    for(int i=(int)words.size()-1;i>=0;--i) { if(!ans.empty()) ans+=' '; ans+=words[i]; }\n    return ans;\n}","js":"function reverseWords(s) {\n  return s.trim().split(/\\s+/).reverse().join(' ');\n}","python":"def reverseWords(s):\n    return ' '.join(reversed(s.split()))","statement":"Reverse the order of words in a string. Return words separated by a single space, with no leading or trailing spaces.","example":"Input: s = \"  hello   world  \" → Output: \"world hello\""},"Sum of Beauty of All Substrings":{"idea":"Fix each substring start and extend its end while updating 26 counts. Beauty is the largest count minus the smallest positive count.","steps":["Choose each possible starting index.","Extend the end and update one of 26 frequency counts.","Add maximum frequency minus the minimum positive frequency for each substring."],"time":"O(26 n²)","space":"O(26)","cpp":"int beautySum(string s) {\n    int ans=0;\n    for(int i=0;i<(int)s.size();++i) {\n        int f[26]={};\n        for(int j=i;j<(int)s.size();++j) {\n            ++f[s[j]-'a']; int lo=INT_MAX,hi=0;\n            for(int n:f) if(n) { lo=min(lo,n); hi=max(hi,n); }\n            ans+=hi-lo;\n        }\n    }\n    return ans;\n}","js":"function beautySum(s) {\n  let ans=0;\n  for(let i=0;i<s.length;i++) {\n    const f=Array(26).fill(0);\n    for(let j=i;j<s.length;j++) { f[s.charCodeAt(j)-97]++; const a=f.filter(n=>n>0); ans+=Math.max(...a)-Math.min(...a); }\n  }\n  return ans;\n}","python":"def beautySum(s):\n    ans = 0\n    for i in range(len(s)):\n        f = [0]*26\n        for j in range(i,len(s)):\n            f[ord(s[j])-97] += 1\n            nonzero = [n for n in f if n]\n            ans += max(nonzero)-min(nonzero)\n    return ans","statement":"For every nonempty substring of a lowercase string, define beauty as its largest character frequency minus its smallest positive character frequency. Return the sum of all beauties.","example":"Input: s = \"aabcb\" → Output: 5"},"Decode String":{"idea":"Push the current prefix and repeat count at an opening bracket. On a closing bracket, repeat the inner text and attach it to the saved prefix.","steps":["Accumulate multidigit repeat counts.","On [, save the outer prefix/count and start an empty inner string.","On ], repeat the inner string and append it to the saved prefix."],"time":"O(n × decoded length) conservative bound","space":"O(decoded length + nesting)","cpp":"string decodeString(string s) {\n    vector<pair<string,int>> st; string cur; int n=0;\n    for(char c:s) {\n        if(isdigit(c)) n=n*10+c-'0';\n        else if(c=='[') { st.push_back({cur,n}); cur=\"\"; n=0; }\n        else if(c==']') { string pre=st.back().first; int k=st.back().second; st.pop_back(); string part=cur; cur=pre; while(k--) cur+=part; }\n        else cur+=c;\n    }\n    return cur;\n}","js":"function decodeString(s) {\n  const stack=[]; let cur='',n=0;\n  for(const c of s) {\n    if(/\\d/.test(c)) n=n*10+Number(c);\n    else if(c==='[') { stack.push([cur,n]); cur=''; n=0; }\n    else if(c===']') { const [pre,k]=stack.pop(); cur=pre+cur.repeat(k); }\n    else cur+=c;\n  }\n  return cur;\n}","python":"def decodeString(s):\n    stack, cur, n = [], '', 0\n    for c in s:\n        if c.isdigit(): n = n*10 + int(c)\n        elif c == '[':\n            stack.append((cur,n))\n            cur, n = '', 0\n        elif c == ']':\n            pre,k = stack.pop()\n            cur = pre + cur*k\n        else: cur += c\n    return cur","statement":"Decode a valid encoded string where k[part] means part repeated k times. Bracketed expressions can nest, and repeat counts can have multiple digits.","example":"Input: s = \"3[a2[c]]\" → Output: \"accaccacc\""},"Count and Say":{"idea":"Starting at 1, repeatedly describe each maximal run by writing its length followed by its digit.","steps":["Start with the string 1.","Group adjacent equal digits and emit count followed by digit.","Repeat n-1 transformations and return the resulting string."],"time":"O(total generated characters)","space":"O(length of final term)","cpp":"string countAndSay(int n) {\n    string s=\"1\";\n    while(--n) { string t; for(int i=0;i<(int)s.size();) { int j=i; while(j<(int)s.size() && s[j]==s[i]) ++j; t+=to_string(j-i)+s[i]; i=j; } s=t; }\n    return s;\n}","js":"function countAndSay(n) {\n  let s='1';\n  while(--n) { const parts=[]; for(let i=0;i<s.length;) { let j=i; while(j<s.length && s[j]===s[i]) j++; parts.push(String(j-i)+s[i]); i=j; } s=parts.join(''); }\n  return s;\n}","python":"def countAndSay(n):\n    from itertools import groupby\n    s = '1'\n    for _ in range(n-1): s = ''.join(str(len(list(g)))+c for c,g in groupby(s))\n    return s","statement":"The first term is \"1\". Each next term describes consecutive equal-digit runs in the previous term by writing each run length followed by its digit. Return term n, for n ≥ 1.","example":"Input: n = 4 → Output: \"1211\" (1 → 11 → 21 → 1211)"},"Reorganize String":{"idea":"Always place the most frequent available letter while holding the previous letter out for one turn. If the largest count exceeds ceil(n/2), no arrangement exists. Lowercase letters are assumed.","steps":["Reject if any lowercase letter appears more than ceil(n/2) times.","Repeatedly choose the most frequent letter different from the last one used.","Decrease its frequency and append it until every letter is placed."],"time":"O(26 n)","space":"O(n)","cpp":"string reorganizeString(string s) {\n    int f[26]={}; for(char c:s) ++f[c-'a'];\n    if(*max_element(f,f+26)>((int)s.size()+1)/2) return \"\";\n    string ans; int prev=-1;\n    for(int k=0;k<(int)s.size();++k) {\n        int best=-1; for(int i=0;i<26;++i) if(i!=prev && f[i] && (best<0 || f[i]>f[best])) best=i;\n        if(best<0) return \"\";\n        ans+=char('a'+best); --f[best]; prev=best;\n    }\n    return ans;\n}","js":"function reorganizeString(s) {\n  const f=Array(26).fill(0); for(const c of s) f[c.charCodeAt(0)-97]++;\n  if(Math.max(...f)>Math.ceil(s.length/2)) return '';\n  const ans=[]; let prev=-1;\n  for(let k=0;k<s.length;k++) {\n    let best=-1;\n    for(let i=0;i<26;i++) if(i!==prev && f[i]>0 && (best<0 || f[i]>f[best])) best=i;\n    if(best<0) return '';\n    ans.push(String.fromCharCode(97+best)); f[best]--; prev=best;\n  }\n  return ans.join('');\n}","python":"def reorganizeString(s):\n    from collections import Counter\n    f = Counter(s)\n    if max(f.values(), default=0) > (len(s)+1)//2: return ''\n    ans, prev = [], None\n    for _ in s:\n        c = max((c for c in f if c != prev and f[c]), key=f.get, default=None)\n        if c is None: return ''\n        ans.append(c)\n        f[c] -= 1\n        prev = c\n    return ''.join(ans)","statement":"Rearrange a lowercase string so no adjacent characters are equal. Return any valid arrangement, or an empty string if impossible.","example":"Input: s = \"aab\" → Output: \"aba\""},"Repeated String Match":{"idea":"Repeat a until it is at least as long as b. Check that string and one extra repetition: any match starts within one copy of a.","steps":["Repeat a ceil(length(b)/length(a)) times.","Test whether b occurs; if not, test one additional copy of a.","Return the successful repeat count or -1."],"time":"O((|a|+|b|) × |b|) worst-case search","space":"O(|a|+|b|)","cpp":"int repeatedStringMatch(string a, string b) {\n    if(b.empty()) return 0; if(a.empty()) return -1;\n    string s; int k=0;\n    while(s.size()<b.size()) { s+=a; ++k; }\n    if(s.find(b)!=string::npos) return k;\n    s+=a; return s.find(b)!=string::npos?k+1:-1;\n}","js":"function repeatedStringMatch(a,b) {\n  if(!b.length) return 0; if(!a.length) return -1;\n  const k=Math.ceil(b.length/a.length),s=a.repeat(k);\n  if(s.includes(b)) return k;\n  return (s+a).includes(b)?k+1:-1;\n}","python":"def repeatedStringMatch(a,b):\n    if not b: return 0\n    if not a: return -1\n    k = (len(b)+len(a)-1)//len(a)\n    s = a*k\n    if b in s: return k\n    return k+1 if b in s+a else -1","statement":"Return the minimum number of repetitions of a needed so b appears as a contiguous substring. Return -1 if this is impossible.","example":"Input: a = \"abcd\", b = \"cdabcdab\" → Output: 3"},"Implement Stack":{"idea":"Use a dynamic array: append and remove at the end. These operations preserve last-in-first-out order.","steps":["Append new values at the end of the backing array.","Read or remove the final element for top/pop.","Use array emptiness for empty; call top/pop only on a nonempty stack."],"time":"O(1) amortized per operation","space":"O(n)","cpp":"class MyStack {\n    vector<int> a;\npublic:\n    void push(int x) { a.push_back(x); }\n    int pop() { int x=a.back(); a.pop_back(); return x; }\n    int top() { return a.back(); }\n    bool empty() { return a.empty(); }\n};","js":"class MyStack {\n  constructor() { this.a=[]; }\n  push(x) { this.a.push(x); }\n  pop() { return this.a.pop(); }\n  top() { return this.a[this.a.length-1]; }\n  empty() { return this.a.length===0; }\n}","python":"class MyStack:\n    def __init__(self): self.a = []\n    def push(self,x): self.a.append(x)\n    def pop(self): return self.a.pop()\n    def top(self): return self.a[-1]\n    def empty(self): return not self.a","statement":"Implement a last-in-first-out stack with push(x), pop(), top(), and empty(). Calls to pop and top are made only when the stack is nonempty.","example":"Operations: push(2), push(1), pop(), top() → Results: 1, 2"},"Implement Queue using Stacks":{"idea":"Keep incoming and outgoing stacks. Transfer incoming items only when outgoing is empty, so every item moves at most once.","steps":["Push new items onto the incoming stack.","When the outgoing stack is empty, transfer all incoming items to it.","Read/pop outgoing for the oldest item; check both stacks for emptiness."],"time":"O(1) amortized; O(n) worst-case pop/peek","space":"O(n)","cpp":"class MyQueue {\n    stack<int> in,out;\n    void transfer() { if(out.empty()) while(!in.empty()) { out.push(in.top()); in.pop(); } }\npublic:\n    void push(int x) { in.push(x); }\n    int pop() { transfer(); int x=out.top(); out.pop(); return x; }\n    int peek() { transfer(); return out.top(); }\n    bool empty() { return in.empty() && out.empty(); }\n};","js":"class MyQueue {\n  constructor() { this.input=[]; this.output=[]; }\n  transfer() { if(!this.output.length) while(this.input.length) this.output.push(this.input.pop()); }\n  push(x) { this.input.push(x); }\n  pop() { this.transfer(); return this.output.pop(); }\n  peek() { this.transfer(); return this.output[this.output.length-1]; }\n  empty() { return !this.input.length && !this.output.length; }\n}","python":"class MyQueue:\n    def __init__(self): self.input, self.output = [], []\n    def transfer(self):\n        if not self.output:\n            while self.input: self.output.append(self.input.pop())\n    def push(self,x): self.input.append(x)\n    def pop(self):\n        self.transfer()\n        return self.output.pop()\n    def peek(self):\n        self.transfer()\n        return self.output[-1]\n    def empty(self): return not self.input and not self.output","statement":"Implement a first-in-first-out queue using two stacks. Support push(x), pop(), peek(), and empty(); pop and peek are called only when nonempty.","example":"Operations: push(2), push(1), peek(), pop(), pop() → Results: 2, 2, 1"},"Valid Parentheses":{"idea":"Push opening brackets. Every closing bracket must match the latest unmatched opening bracket; the stack must be empty at the end.","steps":["Push every opening bracket.","A closing bracket must match the top opening bracket, then pop it.","Reject a mismatch or an empty stack; finally require no unmatched openings."],"time":"O(n)","space":"O(n)","cpp":"bool isValid(string s) {\n    stack<char> st; unordered_map<char,char> match={{')','('},{']','['},{'}','{'}};\n    for(char c:s) {\n        if(c=='(' || c=='[' || c=='{') st.push(c);\n        else { if(st.empty() || st.top()!=match[c]) return false; st.pop(); }\n    }\n    return st.empty();\n}","js":"function isValid(s) {\n  const stack=[], pairs={')':'(',']':'[','}':'{'};\n  for(const c of s) {\n    if('([{'.includes(c)) stack.push(c);\n    else if(!stack.length || stack.pop()!==pairs[c]) return false;\n  }\n  return stack.length===0;\n}","python":"def isValid(s):\n    stack, pairs = [], {')':'(', ']':'[', '}':'{'}\n    for c in s:\n        if c in '([{': stack.append(c)\n        elif not stack or stack.pop() != pairs.get(c): return False\n    return not stack","statement":"Given a string containing (), [], and {}, return whether every closing bracket matches the most recent unmatched opening bracket and all brackets are matched.","example":"Input: s = \"([{}])\" → Output: true; s = \"([)]\" → Output: false"},"Min Stack":{"idea":"Store each value with the minimum of all values beneath it. Popping restores the previous minimum automatically.","steps":["With every pushed value, store the smaller of it and the current minimum.","Pop removes the value and its saved minimum together.","Read the saved minimum at the top in constant time."],"time":"O(1) per operation","space":"O(n)","cpp":"class MinStack {\n    stack<pair<int,int>> st;\npublic:\n    void push(int x) { st.push({x,st.empty()?x:min(x,st.top().second)}); }\n    void pop() { st.pop(); }\n    int top() { return st.top().first; }\n    int getMin() { return st.top().second; }\n};","js":"class MinStack {\n  constructor() { this.st=[]; }\n  push(x) { this.st.push([x,this.st.length?Math.min(x,this.getMin()):x]); }\n  pop() { this.st.pop(); }\n  top() { return this.st[this.st.length-1][0]; }\n  getMin() { return this.st[this.st.length-1][1]; }\n}","python":"class MinStack:\n    def __init__(self): self.st = []\n    def push(self,x): self.st.append((x,min(x,self.getMin()) if self.st else x))\n    def pop(self): self.st.pop()\n    def top(self): return self.st[-1][0]\n    def getMin(self): return self.st[-1][1]","statement":"Implement a stack with push(x), pop(), top(), and getMin(), with every operation taking constant time. Read and removal operations are called only when nonempty.","example":"Operations: push(2), push(1), getMin(), pop(), getMin() → Results: 1, 2"},"Remove Outermost Parentheses":{"idea":"Track nesting depth. Keep an opening bracket only when already inside a primitive, and a closing bracket only when still inside afterward.","steps":["Maintain the current nesting depth.","Keep an opening only if its old depth is positive.","Keep a closing only if its new depth is positive."],"time":"O(n)","space":"O(n) output","cpp":"string removeOuterParentheses(string s) {\n    string ans; int depth=0;\n    for(char c:s) {\n        if(c=='(') { if(depth>0) ans+=c; ++depth; }\n        else { --depth; if(depth>0) ans+=c; }\n    }\n    return ans;\n}","js":"function removeOuterParentheses(s) {\n  const ans=[]; let depth=0;\n  for(const c of s) {\n    if(c==='(') { if(depth>0) ans.push(c); depth++; }\n    else { depth--; if(depth>0) ans.push(c); }\n  }\n  return ans.join('');\n}","python":"def removeOuterParentheses(s):\n    ans, depth = [], 0\n    for c in s:\n        if c == '(':\n            if depth: ans.append(c)\n            depth += 1\n        else:\n            depth -= 1\n            if depth: ans.append(c)\n    return ''.join(ans)","statement":"Split a valid parentheses string into primitive valid parts, then remove the first and last parenthesis from each part. Return the concatenation.","example":"Input: s = \"(()())(())\" → Output: \"()()()\""},"Evaluate Reverse Polish Notation":{"idea":"Push numbers. For an operator, pop the right operand and then the left operand, compute, and push the result. Division truncates toward zero.","steps":["Push numeric tokens.","For an operator, pop right operand b, then left operand a, and push a operator b.","Truncate division toward zero; the final stack item is the answer."],"time":"O(n)","space":"O(n)","cpp":"int evalRPN(vector<string>& tokens) {\n    stack<long long> st;\n    for(string t:tokens) {\n        if(t!=\"+\" && t!=\"-\" && t!=\"*\" && t!=\"/\") st.push(stoll(t));\n        else { long long b=st.top(); st.pop(); long long a=st.top(); st.pop();\n            st.push(t==\"+\"?a+b:t==\"-\"?a-b:t==\"*\"?a*b:a/b); }\n    }\n    return (int)st.top();\n}","js":"function evalRPN(tokens) {\n  const st=[];\n  for(const t of tokens) {\n    if(!['+','-','*','/'].includes(t)) st.push(Number(t));\n    else { const b=st.pop(),a=st.pop(); st.push(t==='+'?a+b:t==='-'?a-b:t==='*'?a*b:Math.trunc(a/b)); }\n  }\n  return st[0];\n}","python":"def evalRPN(tokens):\n    st = []\n    for t in tokens:\n        if t not in ('+','-','*','/'): st.append(int(t))\n        else:\n            b, a = st.pop(), st.pop()\n            if t == '+': st.append(a+b)\n            elif t == '-': st.append(a-b)\n            elif t == '*': st.append(a*b)\n            else: st.append((abs(a)//abs(b)) * (-1 if (a<0) != (b<0) else 1))\n    return st[0]","statement":"Evaluate a valid postfix expression containing integer tokens and +, -, *, /. Integer division truncates toward zero.","example":"Input: tokens = [\"4\", \"13\", \"5\", \"/\", \"+\"] → Output: 6"},"Next Greater Element":{"idea":"Scan nums2 with a decreasing stack. A larger number resolves the next greater value for every smaller pending number, then answer queries from nums1. nums2 has distinct values.","steps":["Keep a decreasing stack while scanning nums2.","A larger value becomes the answer for every smaller value popped.","Look up each nums1 value; use -1 when no greater value exists."],"time":"O(n+m)","space":"O(n)","cpp":"vector<int> nextGreaterElement(vector<int>& nums1, vector<int>& nums2) {\n    unordered_map<int,int> next; stack<int> st;\n    for(int x:nums2) { while(!st.empty() && st.top()<x) { next[st.top()]=x; st.pop(); } st.push(x); }\n    vector<int> ans; for(int x:nums1) ans.push_back(next.count(x)?next[x]:-1);\n    return ans;\n}","js":"function nextGreaterElement(nums1,nums2) {\n  const next=new Map(), st=[];\n  for(const x of nums2) { while(st.length && st[st.length-1]<x) next.set(st.pop(),x); st.push(x); }\n  return nums1.map(x=>next.get(x)??-1);\n}","python":"def nextGreaterElement(nums1,nums2):\n    nxt, st = {}, []\n    for x in nums2:\n        while st and st[-1] < x: nxt[st.pop()] = x\n        st.append(x)\n    return [nxt.get(x,-1) for x in nums1]","statement":"For each value in nums1, find the first larger value to its right in nums2. nums1 is a subset of nums2 and nums2 has distinct values. Use -1 if no greater value exists.","example":"Input: nums1 = [4, 1, 2], nums2 = [1, 3, 4, 2] → Output: [-1, 3, -1]"},"Daily Temperatures":{"idea":"Keep indices of days with unresolved, decreasing temperatures. A warmer day resolves them; subtract indices to find each waiting time.","steps":["Keep indices whose warmer day is not known yet.","For each warmer temperature, pop all cooler pending days.","Store current index minus popped index; leave unresolved answers at zero."],"time":"O(n)","space":"O(n)","cpp":"vector<int> dailyTemperatures(vector<int>& t) {\n    vector<int> ans(t.size()); stack<int> st;\n    for(int i=0;i<(int)t.size();++i) { while(!st.empty() && t[st.top()]<t[i]) { int j=st.top(); st.pop(); ans[j]=i-j; } st.push(i); }\n    return ans;\n}","js":"function dailyTemperatures(t) {\n  const ans=Array(t.length).fill(0),st=[];\n  for(let i=0;i<t.length;i++) { while(st.length && t[st[st.length-1]]<t[i]) { const j=st.pop(); ans[j]=i-j; } st.push(i); }\n  return ans;\n}","python":"def dailyTemperatures(t):\n    ans, st = [0]*len(t), []\n    for i,x in enumerate(t):\n        while st and t[st[-1]] < x:\n            j = st.pop()\n            ans[j] = i-j\n        st.append(i)\n    return ans","statement":"For each daily temperature, return how many days must pass until a strictly warmer day. Use zero when no warmer future day exists.","example":"Input: temperatures = [73, 74, 75, 71, 69, 72, 76, 73] → Output: [1, 1, 4, 2, 1, 1, 0, 0]"},"Next Greater Element - II":{"idea":"Scan the circular array twice. Push indices only on the first pass; the second pass resolves values that wrap around the end.","steps":["Initialize answers to -1 and scan 2n positions using modulo n.","Resolve smaller pending indices whenever a larger value appears.","Push indices only in the first pass so no index is duplicated."],"time":"O(n)","space":"O(n)","cpp":"vector<int> nextGreaterElements(vector<int>& a) {\n    int n=a.size(); vector<int> ans(n,-1); stack<int> st;\n    for(int i=0;i<2*n;++i) { while(!st.empty() && a[st.top()]<a[i%n]) { ans[st.top()]=a[i%n]; st.pop(); } if(i<n) st.push(i); }\n    return ans;\n}","js":"function nextGreaterElements(a) {\n  const n=a.length,ans=Array(n).fill(-1),st=[];\n  for(let i=0;i<2*n;i++) { while(st.length && a[st[st.length-1]]<a[i%n]) ans[st.pop()]=a[i%n]; if(i<n) st.push(i); }\n  return ans;\n}","python":"def nextGreaterElements(a):\n    n, st = len(a), []\n    ans = [-1]*n\n    for i in range(2*n):\n        while st and a[st[-1]] < a[i%n]: ans[st.pop()] = a[i%n]\n        if i < n: st.append(i)\n    return ans","statement":"For each element of a circular array, find the first strictly greater value encountered while moving forward, wrapping at the end. Use -1 when no such value exists.","example":"Input: nums = [1, 2, 1] → Output: [2, -1, 2]"},"Rotting Oranges":{"idea":"Run breadth-first search from every initially rotten orange simultaneously. Each queue layer is one minute; if fresh oranges remain after the queue empties, return -1.","steps":["Enqueue all rotten cells and count fresh cells.","Process one breadth-first layer per minute, infecting adjacent fresh cells once.","Return elapsed minutes when fresh reaches zero, or -1 if the queue empties first."],"time":"O(rows × columns)","space":"O(rows × columns)","cpp":"int orangesRotting(vector<vector<int>>& g) {\n    if(g.empty() || g[0].empty()) return 0;\n    int m=g.size(),n=g[0].size(),fresh=0,time=0; queue<pair<int,int>> q;\n    for(int i=0;i<m;++i) for(int j=0;j<n;++j) { if(g[i][j]==2) q.push({i,j}); if(g[i][j]==1) ++fresh; }\n    int d[5]={1,0,-1,0,1};\n    while(fresh && !q.empty()) {\n        int size=q.size(); ++time;\n        while(size--) { int r=q.front().first,c=q.front().second; q.pop();\n            for(int k=0;k<4;++k) { int x=r+d[k],y=c+d[k+1];\n                if(x>=0 && x<m && y>=0 && y<n && g[x][y]==1) { g[x][y]=2; --fresh; q.push({x,y}); } }\n        }\n    }\n    return fresh?-1:time;\n}","js":"function orangesRotting(g) {\n  if(!g.length || !g[0].length) return 0;\n  const m=g.length,n=g[0].length,q=[]; let fresh=0,time=0,head=0;\n  for(let i=0;i<m;i++) for(let j=0;j<n;j++) { if(g[i][j]===2) q.push([i,j]); if(g[i][j]===1) fresh++; }\n  while(fresh && head<q.length) {\n    const end=q.length; time++;\n    while(head<end) {\n      const [r,c]=q[head++];\n      for(const [dr,dc] of [[1,0],[-1,0],[0,1],[0,-1]]) {\n        const x=r+dr,y=c+dc;\n        if(x>=0 && x<m && y>=0 && y<n && g[x][y]===1) { g[x][y]=2; fresh--; q.push([x,y]); }\n      }\n    }\n  }\n  return fresh?-1:time;\n}","python":"def orangesRotting(g):\n    from collections import deque\n    if not g or not g[0]: return 0\n    m,n = len(g),len(g[0])\n    q = deque((i,j) for i in range(m) for j in range(n) if g[i][j] == 2)\n    fresh = sum(c == 1 for row in g for c in row)\n    time = 0\n    while fresh and q:\n        time += 1\n        for _ in range(len(q)):\n            r,c = q.popleft()\n            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):\n                x,y = r+dr,c+dc\n                if 0 <= x < m and 0 <= y < n and g[x][y] == 1:\n                    g[x][y] = 2\n                    fresh -= 1\n                    q.append((x,y))\n    return -1 if fresh else time","statement":"In a grid, 0 is empty, 1 is a fresh orange, and 2 is rotten. Every minute, rotten oranges infect adjacent fresh oranges horizontally or vertically. Return minutes until all are rotten, or -1 if impossible.","example":"Input: grid = [[2,1,1],[1,1,0],[0,1,1]] → Output: 4"},"Square Root of X":{"idea":"Binary-search the largest integer whose square does not exceed x. Compare mid with x divided by mid to avoid multiplying large integers","steps":["Binary-search the largest integer whose square does not exceed x.","Compare mid with x divided by mid to avoid multiplying large integers."],"time":"O(log x)","space":"O(1)","python":"def integer_sqrt(x):\n    lo, hi, ans = 1, x, 0\n    while lo <= hi:\n        mid = (lo+hi)//2\n        if mid <= x//mid: ans, lo = mid, mid+1\n        else: hi = mid-1\n    return ans","js":"function integerSqrt(x) {\n  let lo=1,hi=x,ans=0;\n  while(lo<=hi){const m=lo+Math.floor((hi-lo)/2);if(m<=Math.floor(x/m)){ans=m;lo=m+1;}else hi=m-1;}return ans;\n}","cpp":"int integerSqrt(int x) {\n  int lo=1,hi=x,ans=0;\n  while(lo<=hi){int m=lo+(hi-lo)/2;if(m<=x/m){ans=m;lo=m+1;}else hi=m-1;}return ans;\n}","statement":"For nonnegative integer x, return the floor of its square root.","example":"x = 8 → 2"},"Guess Higher or Lower":{"idea":"Use the supplied guess API, which returns -1 when the guess is too high and 1 when too low. Each API result removes half the remaining range","steps":["Use the supplied guess API, which returns -1 when the guess is too high and 1 when too low.","Each API result removes half the remaining range."],"time":"O(log n) API calls","space":"O(1)","python":"def guess_number(n, guess):\n    lo, hi = 1, n\n    while lo <= hi:\n        mid = lo+(hi-lo)//2; result = guess(mid)\n        if result == 0: return mid\n        if result < 0: hi = mid-1\n        else: lo = mid+1\n    return -1","js":"function guessNumber(n,guess) {\n  let lo=1,hi=n;\n  while(lo<=hi){const m=lo+Math.floor((hi-lo)/2),r=guess(m);if(r===0)return m;if(r<0)hi=m-1;else lo=m+1;}return -1;\n}","cpp":"int guessNumber(int n,function<int(int)> guess) {\n  int lo=1,hi=n;\n  while(lo<=hi){int m=lo+(hi-lo)/2,r=guess(m);if(!r)return m;if(r<0)hi=m-1;else lo=m+1;}return -1;\n}","statement":"Find a hidden number in 1 through n using guess(mid): -1 means mid is too high, +1 too low, and 0 correct.","example":"n = 10, hidden number = 6 → 6"},"Search in Rotated Sorted Array":{"idea":"With distinct elements, at least one half around mid is sorted. Check whether the target lies within that sorted half, then retain only the half that can contain it","steps":["With distinct elements, at least one half around mid is sorted.","Check whether the target lies within that sorted half, then retain only the half that can contain it."],"time":"O(log n)","space":"O(1)","python":"def search_rotated(a, target):\n    lo, hi = 0, len(a)-1\n    while lo <= hi:\n        mid = (lo+hi)//2\n        if a[mid] == target: return mid\n        if a[lo] <= a[mid]:\n            if a[lo] <= target < a[mid]: hi = mid-1\n            else: lo = mid+1\n        else:\n            if a[mid] < target <= a[hi]: lo = mid+1\n            else: hi = mid-1\n    return -1","js":"function searchRotated(a,t) {\n  let l=0,r=a.length-1;\n  while(l<=r){const m=Math.floor((l+r)/2);if(a[m]===t)return m;\n    if(a[l]<=a[m]){if(a[l]<=t&&t<a[m])r=m-1;else l=m+1;}\n    else{if(a[m]<t&&t<=a[r])l=m+1;else r=m-1;}}return -1;\n}","cpp":"int searchRotated(vector<int>& a,int t) {\n  int l=0,r=(int)a.size()-1;\n  while(l<=r){int m=l+(r-l)/2;if(a[m]==t)return m;\n    if(a[l]<=a[m]){if(a[l]<=t&&t<a[m])r=m-1;else l=m+1;}\n    else{if(a[m]<t&&t<=a[r])l=m+1;else r=m-1;}}return -1;\n}","statement":"Find target in a rotated ascending array of distinct integers, returning its index or -1.","example":"nums = [4,5,6,7,0,1,2], target = 0 → 4"},"First Bad Version":{"idea":"Versions form a monotone sequence: good versions followed by bad ones. Binary-search the first true result of is_bad, keeping mid when it is bad because it may be the first","steps":["Versions form a monotone sequence: good versions followed by bad ones.","Binary-search the first true result of is_bad, keeping mid when it is bad because it may be the first."],"time":"O(log n) API calls","space":"O(1)","python":"def first_bad_version(n, is_bad):\n    lo, hi = 1, n\n    while lo < hi:\n        mid = lo+(hi-lo)//2\n        if is_bad(mid): hi = mid\n        else: lo = mid+1\n    return lo","js":"function firstBadVersion(n,isBad) {\n  let l=1,r=n;while(l<r){const m=l+Math.floor((r-l)/2);if(isBad(m))r=m;else l=m+1;}return l;\n}","cpp":"int firstBadVersion(int n,function<bool(int)> isBad) {\n  int l=1,r=n;while(l<r){int m=l+(r-l)/2;if(isBad(m))r=m;else l=m+1;}return l;\n}","statement":"Versions 1 through n are good until one version becomes bad, after which all are bad. Use is_bad(version) to find the first bad version.","example":"n = 5, first bad = 4 → 4"},"Find Peak Element":{"idea":"Adjacent elements are unequal and values outside the array are treated as negative infinity. An upward slope guarantees a peak to the right; a downward slope guarantees one at or to the left of mid","steps":["Adjacent elements are unequal and values outside the array are treated as negative infinity.","An upward slope guarantees a peak to the right; a downward slope guarantees one at or to the left of mid."],"time":"O(log n)","space":"O(1)","python":"def find_peak(a):\n    if not a: return -1\n    lo, hi = 0, len(a)-1\n    while lo < hi:\n        mid = (lo+hi)//2\n        if a[mid] < a[mid+1]: lo = mid+1\n        else: hi = mid\n    return lo","js":"function findPeak(a) {\n  if(!a.length)return -1;let l=0,r=a.length-1;\n  while(l<r){const m=Math.floor((l+r)/2);if(a[m]<a[m+1])l=m+1;else r=m;}return l;\n}","cpp":"int findPeak(vector<int>& a) {\n  if(a.empty())return -1;int l=0,r=a.size()-1;\n  while(l<r){int m=l+(r-l)/2;if(a[m]<a[m+1])l=m+1;else r=m;}return l;\n}","statement":"Return any index whose value is strictly larger than its neighbors. Adjacent values differ and out-of-range neighbors count as negative infinity.","example":"nums = [1,2,3,1] → 2"},"Find Minimum in Rotated Sorted Array":{"idea":"Compare mid with the final value in a rotated array of distinct values. A larger mid places the minimum strictly to its right; otherwise the minimum is at mid or on its left","steps":["Compare mid with the final value in a rotated array of distinct values.","A larger mid places the minimum strictly to its right; otherwise the minimum is at mid or on its left."],"time":"O(log n)","space":"O(1)","python":"def find_min_rotated(a):\n    lo, hi = 0, len(a)-1\n    while lo < hi:\n        mid = (lo+hi)//2\n        if a[mid] > a[hi]: lo = mid+1\n        else: hi = mid\n    return a[lo]","js":"function findMinRotated(a) {\n  let l=0,r=a.length-1;while(l<r){const m=Math.floor((l+r)/2);if(a[m]>a[r])l=m+1;else r=m;}return a[l];\n}","cpp":"int findMinRotated(vector<int>& a) {\n  int l=0,r=a.size()-1;while(l<r){int m=l+(r-l)/2;if(a[m]>a[r])l=m+1;else r=m;}return a[l];\n}","statement":"Return the smallest value in a nonempty rotated ascending array of distinct integers.","example":"nums = [3,4,5,1,2] → 1"},"Find First & Last Position in Sorted Array":{"idea":"Run a lower-bound search for the first value at least target and an upper-bound search for the first value greater than target. Verify that the lower bound actually points to target","steps":["Run a lower-bound search for the first value at least target and an upper-bound search for the first value greater than target.","Verify that the lower bound actually points to target."],"time":"O(log n)","space":"O(1)","python":"def search_range(a, target):\n    def bound(strict):\n        lo, hi = 0, len(a)\n        while lo < hi:\n            mid = (lo+hi)//2\n            if a[mid] < target or (strict and a[mid] == target): lo = mid+1\n            else: hi = mid\n        return lo\n    first = bound(False)\n    return [first, bound(True)-1] if first < len(a) and a[first] == target else [-1, -1]","js":"function searchRange(a,t) {\n  function bound(strict){let l=0,r=a.length;while(l<r){const m=Math.floor((l+r)/2);if(a[m]<t||(strict&&a[m]===t))l=m+1;else r=m;}return l;}\n  const l=bound(false);return l<a.length&&a[l]===t?[l,bound(true)-1]:[-1,-1];\n}","cpp":"vector<int> searchRange(vector<int>& a,int t) {\n  auto l=lower_bound(a.begin(),a.end(),t),r=upper_bound(a.begin(),a.end(),t);\n  if(l==a.end()||*l!=t)return {-1,-1};return {(int)(l-a.begin()),(int)(r-a.begin())-1};\n}","statement":"Return the first and last indices of target in a sorted array, or [-1,-1] if absent.","example":"nums = [5,7,7,8,8,10], target = 8 → [3,4]"},"Find Peak in a Mountain Array":{"idea":"A mountain increases strictly and then decreases strictly. Compare mid with its right neighbor and follow the slope uphill until the search interval contains only the summit","steps":["A mountain increases strictly and then decreases strictly.","Compare mid with its right neighbor and follow the slope uphill until the search interval contains only the summit."],"time":"O(log n)","space":"O(1)","python":"def peak_index(a):\n    lo, hi = 0, len(a)-1\n    while lo < hi:\n        mid = (lo+hi)//2\n        if a[mid] < a[mid+1]: lo = mid+1\n        else: hi = mid\n    return lo","js":"function peakIndex(a) {\n  let l=0,r=a.length-1;while(l<r){const m=Math.floor((l+r)/2);if(a[m]<a[m+1])l=m+1;else r=m;}return l;\n}","cpp":"int peakIndex(vector<int>& a) {\n  int l=0,r=a.size()-1;while(l<r){int m=l+(r-l)/2;if(a[m]<a[m+1])l=m+1;else r=m;}return l;\n}","statement":"Return the summit index in an array that strictly increases and then strictly decreases.","example":"nums = [0,2,4,3,1] → 2"},"Single Element in a Sorted Array":{"idea":"Before the singleton, pairs start at even indices; after it, pairs start at odd indices. Force mid to be even and test its pair to locate the first broken pairing","steps":["Before the singleton, pairs start at even indices; after it, pairs start at odd indices.","Force mid to be even and test its pair to locate the first broken pairing."],"time":"O(log n)","space":"O(1)","python":"def single_non_duplicate(a):\n    lo, hi = 0, len(a)-1\n    while lo < hi:\n        mid = (lo+hi)//2\n        mid -= mid % 2\n        if a[mid] == a[mid+1]: lo = mid+2\n        else: hi = mid\n    return a[lo]","js":"function singleNonDuplicate(a) {\n  let l=0,r=a.length-1;while(l<r){let m=Math.floor((l+r)/2);m-=m%2;if(a[m]===a[m+1])l=m+2;else r=m;}return a[l];\n}","cpp":"int singleNonDuplicate(vector<int>& a) {\n  int l=0,r=a.size()-1;while(l<r){int m=l+(r-l)/2;m-=m%2;if(a[m]==a[m+1])l=m+2;else r=m;}return a[l];\n}","statement":"In a sorted array, every value appears exactly twice except one. Return that singleton.","example":"nums = [1,1,2,3,3] → 2"},"Find k Closest Elements":{"idea":"The answer is a contiguous window of k values in the sorted array. Binary-search its left boundary by comparing the two values that would be exchanged when shifting the window right; ties favor the smaller values","steps":["The answer is a contiguous window of k values in the sorted array.","Binary-search its left boundary by comparing the two values that would be exchanged when shifting the window right; ties favor the smaller values."],"time":"O(log(n-k)+k)","space":"O(k) output","python":"def find_closest(a, k, x):\n    lo, hi = 0, len(a)-k\n    while lo < hi:\n        mid = (lo+hi)//2\n        if x-a[mid] > a[mid+k]-x: lo = mid+1\n        else: hi = mid\n    return a[lo:lo+k]","js":"function findClosest(a,k,x) {\n  let l=0,r=a.length-k;while(l<r){const m=Math.floor((l+r)/2);if(x-a[m]>a[m+k]-x)l=m+1;else r=m;}return a.slice(l,l+k);\n}","cpp":"vector<int> findClosest(vector<int>& a,int k,int x) {\n  int l=0,r=a.size()-k;while(l<r){int m=l+(r-l)/2;if((long long)x-a[m]>(long long)a[m+k]-x)l=m+1;else r=m;}\n  return vector<int>(a.begin()+l,a.begin()+l+k);\n}","statement":"Return k values closest to x in a sorted array, favoring smaller values on distance ties. Return the answer in ascending order.","example":"arr = [1,2,3,4,5], k = 4, x = 3 → [1,2,3,4]"},"Two Sum":{"idea":"Store each previously visited value with its index. Before inserting the current value, look for target minus that value so the same element is never used twice","steps":["Store each previously visited value with its index.","Before inserting the current value, look for target minus that value so the same element is never used twice."],"time":"O(n) expected","space":"O(n)","python":"def two_sum(nums, target):\n    seen = {}\n    for i, x in enumerate(nums):\n        if target-x in seen: return [seen[target-x], i]\n        seen[x] = i\n    return []","js":"function twoSum(a,t) {\n  const seen=new Map();for(let i=0;i<a.length;i++){if(seen.has(t-a[i]))return [seen.get(t-a[i]),i];seen.set(a[i],i);}return [];\n}","cpp":"vector<int> twoSum(vector<int>& a,int t) {\n  unordered_map<int,int> seen;for(int i=0;i<(int)a.size();i++){if(seen.count(t-a[i]))return {seen[t-a[i]],i};seen[a[i]]=i;}return {};\n}","statement":"Return the zero-based indices of two distinct array elements whose sum equals target. The standard problem guarantees one answer.","example":"nums = [2,7,11,15], target = 9 → [0,1]"},"Two Sum II":{"idea":"Because the input is sorted, start at both ends. If their sum is too small, advance the left pointer; if too large, retreat the right pointer; return one-based indices","steps":["Because the input is sorted, start at both ends.","If their sum is too small, advance the left pointer; if too large, retreat the right pointer; return one-based indices."],"time":"O(n)","space":"O(1)","python":"def two_sum_sorted(a, target):\n    l, r = 0, len(a)-1\n    while l < r:\n        total = a[l]+a[r]\n        if total == target: return [l+1, r+1]\n        if total < target: l += 1\n        else: r -= 1\n    return []","js":"function twoSumSorted(a,t) {\n  let l=0,r=a.length-1;while(l<r){const s=a[l]+a[r];if(s===t)return [l+1,r+1];if(s<t)l++;else r--;}return [];\n}","cpp":"vector<int> twoSumSorted(vector<int>& a,int t) {\n  int l=0,r=(int)a.size()-1;while(l<r){long long s=(long long)a[l]+a[r];if(s==t)return {l+1,r+1};if(s<t)l++;else r--;}return {};\n}","statement":"In an ascending sorted array, return the one-based indices of two distinct elements whose sum equals target.","example":"numbers = [2,7,11,15], target = 9 → [1,2]"},"Is Subsequence":{"idea":"Advance through the shorter string only when its next character matches the current character in the longer string. All characters must match in order, but need not be adjacent","steps":["Advance through the shorter string only when its next character matches the current character in the longer string.","All characters must match in order, but need not be adjacent."],"time":"O(|t|)","space":"O(1)","python":"def is_subsequence(s, t):\n    i = 0\n    for c in t:\n        if i < len(s) and s[i] == c: i += 1\n    return i == len(s)","js":"function isSubsequence(s,t) {\n  let i=0;for(const c of t)if(i<s.length&&s[i]===c)i++;return i===s.length;\n}","cpp":"bool isSubsequence(string s,string t) {\n  int i=0;for(char c:t)if(i<(int)s.size()&&s[i]==c)i++;return i==(int)s.size();\n}","statement":"Determine whether s can be obtained by deleting zero or more characters from t without reordering the remaining characters.","example":"s = \"abc\", t = \"ahbgdc\" → true"},"Find Index of First Occurrence in String":{"idea":"Build the prefix-function for the needle to remember matched prefixes. When a mismatch occurs, reuse the longest valid suffix rather than restarting the search; this is the KMP algorithm","steps":["Build the prefix-function for the needle to remember matched prefixes.","When a mismatch occurs, reuse the longest valid suffix rather than restarting the search; this is the KMP algorithm."],"time":"O(n+m)","space":"O(m)","python":"def str_str(haystack, needle):\n    if not needle: return 0\n    pi = [0]*len(needle); j = 0\n    for i in range(1, len(needle)):\n        while j and needle[i] != needle[j]: j = pi[j-1]\n        if needle[i] == needle[j]: j += 1\n        pi[i] = j\n    j = 0\n    for i, c in enumerate(haystack):\n        while j and c != needle[j]: j = pi[j-1]\n        if c == needle[j]: j += 1\n        if j == len(needle): return i-j+1\n    return -1","js":"function strStr(h,n) {\n  if(!n.length)return 0;const pi=Array(n.length).fill(0);let j=0;\n  for(let i=1;i<n.length;i++){while(j&&n[i]!==n[j])j=pi[j-1];if(n[i]===n[j])j++;pi[i]=j;}j=0;\n  for(let i=0;i<h.length;i++){while(j&&h[i]!==n[j])j=pi[j-1];if(h[i]===n[j])j++;if(j===n.length)return i-j+1;}return -1;\n}","cpp":"int strStr(string h,string n) {\n  if(n.empty())return 0;vector<int>pi(n.size());int j=0;\n  for(int i=1;i<(int)n.size();i++){while(j&&n[i]!=n[j])j=pi[j-1];if(n[i]==n[j])j++;pi[i]=j;}j=0;\n  for(int i=0;i<(int)h.size();i++){while(j&&h[i]!=n[j])j=pi[j-1];if(h[i]==n[j])j++;if(j==(int)n.size())return i-j+1;}return -1;\n}","statement":"Return the first zero-based starting index of needle in haystack, or -1 when absent. An empty needle matches at index 0.","example":"haystack = \"sadbutsad\", needle = \"sad\" → 0"},"Intersection of Two Linked Lists":{"idea":"Switch each pointer to the other list after it reaches null. Both pointers then travel equal total distances and meet at the shared node or at null; compare node identity, not values","steps":["Switch each pointer to the other list after it reaches null.","Both pointers then travel equal total distances and meet at the shared node or at null; compare node identity, not values."],"time":"O(m+n)","space":"O(1)","python":"def get_intersection(a, b):\n    p, q = a, b\n    while p is not q:\n        p = p.next if p else b\n        q = q.next if q else a\n    return p","js":"function getIntersection(a,b) {\n  let p=a,q=b;while(p!==q){p=p?p.next:b;q=q?q.next:a;}return p;\n}","cpp":"ListNode* getIntersection(ListNode* a,ListNode* b) {\n  auto p=a,q=b;while(p!=q){p=p?p->next:b;q=q?q->next:a;}return p;\n}","statement":"Return the first node shared by two acyclic singly linked lists, comparing node identity rather than values.","example":"A and B share the same tail node 8 → return that node"},"Container with Most Water":{"idea":"The area is the width times the shorter wall. Move the shorter wall inward because retaining it while reducing width cannot improve the current area","steps":["The area is the width times the shorter wall.","Move the shorter wall inward because retaining it while reducing width cannot improve the current area."],"time":"O(n)","space":"O(1)","python":"def max_area(height):\n    l, r, best = 0, len(height)-1, 0\n    while l < r:\n        best = max(best, (r-l)*min(height[l], height[r]))\n        if height[l] < height[r]: l += 1\n        else: r -= 1\n    return best","js":"function maxArea(h) {\n  let l=0,r=h.length-1,best=0;while(l<r){best=Math.max(best,(r-l)*Math.min(h[l],h[r]));if(h[l]<h[r])l++;else r--;}return best;\n}","cpp":"int maxArea(vector<int>& h) {\n  int l=0,r=(int)h.size()-1,best=0;while(l<r){best=max(best,(r-l)*min(h[l],h[r]));if(h[l]<h[r])l++;else r--;}return best;\n}","statement":"Choose two vertical lines from the nonnegative height array to hold the maximum area of water between them.","example":"height = [1,8,6,2,5,4,8,3,7] → 49"},"Three Sum":{"idea":"Sort the values and fix one value at a time. Use two pointers to find its complementary pair, skipping repeated anchors and pair values so each zero-sum triplet appears once","steps":["Sort the values and fix one value at a time.","Use two pointers to find its complementary pair, skipping repeated anchors and pair values so each zero-sum triplet appears once."],"time":"O(n²)","space":"O(n) sorting/copy plus output","python":"def three_sum(nums):\n    a = sorted(nums); out = []\n    for i in range(len(a)-2):\n        if i and a[i] == a[i-1]: continue\n        l, r = i+1, len(a)-1\n        while l < r:\n            total = a[i]+a[l]+a[r]\n            if total < 0: l += 1\n            elif total > 0: r -= 1\n            else:\n                out.append([a[i], a[l], a[r]]); l += 1; r -= 1\n                while l < r and a[l] == a[l-1]: l += 1\n                while l < r and a[r] == a[r+1]: r -= 1\n    return out","js":"function threeSum(nums) {\n  const a=nums.slice().sort((x,y)=>x-y),out=[];\n  for(let i=0;i<a.length-2;i++){if(i&&a[i]===a[i-1])continue;let l=i+1,r=a.length-1;\n    while(l<r){const s=a[i]+a[l]+a[r];if(s<0)l++;else if(s>0)r--;else{out.push([a[i],a[l],a[r]]);l++;r--;while(l<r&&a[l]===a[l-1])l++;while(l<r&&a[r]===a[r+1])r--;}}}return out;\n}","cpp":"vector<vector<int>> threeSum(vector<int> a) {\n  sort(a.begin(),a.end());vector<vector<int>>out;\n  for(int i=0;i+2<(int)a.size();i++){if(i&&a[i]==a[i-1])continue;int l=i+1,r=a.size()-1;\n    while(l<r){long long s=(long long)a[i]+a[l]+a[r];if(s<0)l++;else if(s>0)r--;else{out.push_back({a[i],a[l],a[r]});l++;r--;while(l<r&&a[l]==a[l-1])l++;while(l<r&&a[r]==a[r+1])r--;}}}return out;\n}","statement":"Return all unique value triplets from distinct indices whose sum is zero.","example":"nums = [-1,0,1,2,-1,-4] → [[-1,-1,2],[-1,0,1]]"},"Trapping Rain Water":{"idea":"Track the tallest wall reached from each end. Resolve the side with the lower current boundary because its maximum determines the water level there, regardless of unseen interior walls","steps":["Track the tallest wall reached from each end.","Resolve the side with the lower current boundary because its maximum determines the water level there, regardless of unseen interior walls."],"time":"O(n)","space":"O(1)","python":"def trap(height):\n    l, r = 0, len(height)-1\n    left_max = right_max = water = 0\n    while l <= r:\n        if left_max <= right_max:\n            left_max = max(left_max, height[l]); water += left_max-height[l]; l += 1\n        else:\n            right_max = max(right_max, height[r]); water += right_max-height[r]; r -= 1\n    return water","js":"function trap(h) {\n  let l=0,r=h.length-1,lm=0,rm=0,water=0;\n  while(l<=r){if(lm<=rm){lm=Math.max(lm,h[l]);water+=lm-h[l++];}else{rm=Math.max(rm,h[r]);water+=rm-h[r--];}}return water;\n}","cpp":"int trap(vector<int>& h) {\n  int l=0,r=(int)h.size()-1,lm=0,rm=0,water=0;\n  while(l<=r){if(lm<=rm){lm=max(lm,h[l]);water+=lm-h[l++];}else{rm=max(rm,h[r]);water+=rm-h[r--];}}return water;\n}","statement":"Given nonnegative column heights of unit width, return the total water trapped between them after rain.","example":"height = [0,1,0,2,1,0,1,3,2,1,2,1] → 6"},"Longest Substring Without Repeating Characters":{"idea":"Remember the most recent position of each character. On a repeated character, move the left boundary past its previous occurrence without ever moving left backwards","steps":["Remember the most recent position of each character.","On a repeated character, move the left boundary past its previous occurrence without ever moving left backwards."],"time":"O(n)","space":"O(min(n, alphabet))","python":"def longest_unique(s):\n    last = {}; left = best = 0\n    for right, c in enumerate(s):\n        left = max(left, last.get(c, -1)+1)\n        last[c] = right; best = max(best, right-left+1)\n    return best","js":"function longestUnique(s) {\n  const last=new Map();let l=0,best=0;\n  for(let r=0;r<s.length;r++){l=Math.max(l,(last.get(s[r])??-1)+1);last.set(s[r],r);best=Math.max(best,r-l+1);}return best;\n}","cpp":"int longestUnique(string s) {\n  vector<int>last(256,-1);int l=0,best=0;\n  for(int r=0;r<(int)s.size();r++){unsigned char c=s[r];l=max(l,last[c]+1);last[c]=r;best=max(best,r-l+1);}return best;\n}","statement":"Return the length of the longest contiguous substring with no repeated character.","example":"s = \"abcabcbb\" → 3"},"Longest Repeating Character Replacement":{"idea":"In an uppercase-letter window, all but its most frequent character must change. Shrink while window length minus that frequency exceeds k, then record the longest valid window","steps":["In an uppercase-letter window, all but its most frequent character must change.","Shrink while window length minus that frequency exceeds k, then record the longest valid window."],"time":"O(26n) = O(n)","space":"O(26)","python":"def character_replacement(s, k):\n    counts = {}; left = best = 0\n    for right, c in enumerate(s):\n        counts[c] = counts.get(c, 0)+1\n        while right-left+1-max(counts.values()) > k:\n            counts[s[left]] -= 1; left += 1\n        best = max(best, right-left+1)\n    return best","js":"function characterReplacement(s,k) {\n  const count=Array(26).fill(0);let l=0,best=0;\n  for(let r=0;r<s.length;r++){count[s.charCodeAt(r)-65]++;while(r-l+1-Math.max(...count)>k)count[s.charCodeAt(l++)-65]--;best=Math.max(best,r-l+1);}return best;\n}","cpp":"int characterReplacement(string s,int k) {\n  vector<int>count(26);int l=0,best=0;\n  for(int r=0;r<(int)s.size();r++){count[s[r]-'A']++;while(r-l+1-*max_element(count.begin(),count.end())>k)count[s[l++]-'A']--;best=max(best,r-l+1);}return best;\n}","statement":"Given an uppercase-letter string and k replacements, return the longest substring that can be made entirely one character.","example":"s = \"AABABBA\", k = 1 → 4"},"Permutation in String":{"idea":"A permutation has exactly the same character frequencies as the first string. Slide a window of that fixed length over the second string and compare its 26 lowercase-letter counts","steps":["A permutation has exactly the same character frequencies as the first string.","Slide a window of that fixed length over the second string and compare its 26 lowercase-letter counts."],"time":"O(26n) = O(n)","space":"O(26)","python":"def check_inclusion(s1, s2):\n    if len(s1) > len(s2): return False\n    need, have = [0]*26, [0]*26\n    for c in s1: need[ord(c)-97] += 1\n    for i, c in enumerate(s2):\n        have[ord(c)-97] += 1\n        if i >= len(s1): have[ord(s2[i-len(s1)])-97] -= 1\n        if i+1 >= len(s1) and have == need: return True\n    return not s1","js":"function checkInclusion(a,b) {\n  if(a.length>b.length)return false;if(!a.length)return true;\n  const need=Array(26).fill(0),have=Array(26).fill(0);\n  for(const c of a)need[c.charCodeAt(0)-97]++;\n  for(let i=0;i<b.length;i++){have[b.charCodeAt(i)-97]++;if(i>=a.length)have[b.charCodeAt(i-a.length)-97]--;if(i+1>=a.length&&have.every((v,j)=>v===need[j]))return true;}return false;\n}","cpp":"bool checkInclusion(string a,string b) {\n  if(a.size()>b.size())return false;if(a.empty())return true;vector<int>need(26),have(26);\n  for(char c:a)need[c-'a']++;\n  for(int i=0;i<(int)b.size();i++){have[b[i]-'a']++;if(i>=(int)a.size())have[b[i-a.size()]-'a']--;if(i+1>=(int)a.size()&&have==need)return true;}return false;\n}","statement":"Determine whether the lowercase-letter string s2 contains any contiguous permutation of s1.","example":"s1 = \"ab\", s2 = \"eidbaooo\" → true"},"Sliding Window Maximum":{"idea":"Maintain indices in decreasing order of their values in a deque. Drop expired indices from the front and weaker candidates from the back; the front is the maximum for every complete window","steps":["Maintain indices in decreasing order of their values in a deque.","Drop expired indices from the front and weaker candidates from the back; the front is the maximum for every complete window."],"time":"O(n)","space":"O(k)","python":"from collections import deque\ndef max_sliding_window(nums, k):\n    q = deque(); out = []\n    for i, x in enumerate(nums):\n        while q and q[0] <= i-k: q.popleft()\n        while q and nums[q[-1]] <= x: q.pop()\n        q.append(i)\n        if i >= k-1: out.append(nums[q[0]])\n    return out","js":"function maxSlidingWindow(a,k) {\n  const q=[],out=[];let head=0;\n  for(let i=0;i<a.length;i++){while(head<q.length&&q[head]<=i-k)head++;while(head<q.length&&a[q[q.length-1]]<=a[i])q.pop();q.push(i);if(i>=k-1)out.push(a[q[head]]);\n    if(head>k){q.splice(0,head);head=0;}}\n  return out;\n}","cpp":"vector<int> maxSlidingWindow(vector<int>& a,int k) {\n  deque<int>q;vector<int>out;\n  for(int i=0;i<(int)a.size();i++){while(!q.empty()&&q.front()<=i-k)q.pop_front();while(!q.empty()&&a[q.back()]<=a[i])q.pop_back();q.push_back(i);if(i>=k-1)out.push_back(a[q.front()]);}return out;\n}","statement":"For every contiguous window of k elements in an array, return its maximum; 1 ≤ k ≤ array length.","example":"nums = [1,3,-1,-3,5,3,6,7], k = 3 → [3,3,5,5,6,7]"},"Preorder Traversal":{"idea":"Depth-first traversal visits each node exactly once. Process the node in root, left, right order. A null child ends its recursive branch","steps":["Depth-first traversal visits each node exactly once.","Process the node in root, left, right order.","A null child ends its recursive branch."],"time":"O(n)","space":"O(h) auxiliary, O(n) output","python":"def traversal(root):\n    out = []\n    def visit(node):\n        if node is None: return\n        out.append(node.val)\n        visit(node.left)\n        visit(node.right)\n    visit(root)\n    return out","js":"function traversal(root) {\n  const out = [];\n  function visit(node) {\n    if (!node) return;\n    out.push(node.val);\n    visit(node.left);\n    visit(node.right);\n  }\n  visit(root); return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<int> traversal(TreeNode* root) {\n  vector<int> out;\n  function<void(TreeNode*)> visit = [&](TreeNode* node) {\n    if (!node) return;\n    out.push_back(node->val);\n    visit(node->left);\n    visit(node->right);\n  };\n  visit(root); return out;\n}","statement":"Return the node values in root-left-right order.","example":"root = [1,null,2,3] → [1,2,3]"},"Inorder Traversal":{"idea":"Depth-first traversal visits each node exactly once. Process the node in left, root, right order. A null child ends its recursive branch","steps":["Depth-first traversal visits each node exactly once.","Process the node in left, root, right order.","A null child ends its recursive branch."],"time":"O(n)","space":"O(h) auxiliary, O(n) output","python":"def traversal(root):\n    out = []\n    def visit(node):\n        if node is None: return\n        visit(node.left)\n        out.append(node.val)\n        visit(node.right)\n    visit(root)\n    return out","js":"function traversal(root) {\n  const out = [];\n  function visit(node) {\n    if (!node) return;\n    visit(node.left);\n    out.push(node.val);\n    visit(node.right);\n  }\n  visit(root); return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<int> traversal(TreeNode* root) {\n  vector<int> out;\n  function<void(TreeNode*)> visit = [&](TreeNode* node) {\n    if (!node) return;\n    visit(node->left);\n    out.push_back(node->val);\n    visit(node->right);\n  };\n  visit(root); return out;\n}","statement":"Return the node values in left-root-right order.","example":"root = [1,null,2,3] → [1,3,2]"},"Postorder Traversal":{"idea":"Depth-first traversal visits each node exactly once. Process the node in left, right, root order. A null child ends its recursive branch","steps":["Depth-first traversal visits each node exactly once.","Process the node in left, right, root order.","A null child ends its recursive branch."],"time":"O(n)","space":"O(h) auxiliary, O(n) output","python":"def traversal(root):\n    out = []\n    def visit(node):\n        if node is None: return\n        visit(node.left)\n        visit(node.right)\n        out.append(node.val)\n    visit(root)\n    return out","js":"function traversal(root) {\n  const out = [];\n  function visit(node) {\n    if (!node) return;\n    visit(node.left);\n    visit(node.right);\n    out.push(node.val);\n  }\n  visit(root); return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<int> traversal(TreeNode* root) {\n  vector<int> out;\n  function<void(TreeNode*)> visit = [&](TreeNode* node) {\n    if (!node) return;\n    visit(node->left);\n    visit(node->right);\n    out.push_back(node->val);\n  };\n  visit(root); return out;\n}","statement":"Return the node values in left-right-root order.","example":"root = [1,null,2,3] → [3,2,1]"},"Level Order Traversal":{"idea":"A queue keeps nodes in discovery order. Process the current queue length as one level before adding children. Append each completed level to the answer","steps":["A queue keeps nodes in discovery order.","Process the current queue length as one level before adding children.","Append each completed level to the answer."],"time":"O(n)","space":"O(w)","python":"from collections import deque\ndef levelOrder(root):\n    q = deque([root] if root else [])\n    out = []\n    while q:\n        row = []\n        for _ in range(len(q)):\n            n = q.popleft(); row.append(n.val)\n            if n.left: q.append(n.left)\n            if n.right: q.append(n.right)\n        out.append(row)\n    return out","js":"function levelOrder(root) {\n  let q = root ? [root] : [], out = [];\n  while (q.length) {\n    const next = [], row = [];\n    for (const n of q) {\n      row.push(n.val);\n      if (n.left) next.push(n.left);\n      if (n.right) next.push(n.right);\n    }\n    out.push(row); q = next;\n  }\n  return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<vector<int>> levelOrder(TreeNode* root) {\n  vector<vector<int>> out; queue<TreeNode*> q;\n  if (root) q.push(root);\n  while (!q.empty()) {\n    vector<int> row; int size=q.size();\n    while (size--) {\n      auto n=q.front(); q.pop(); row.push_back(n->val);\n      if (n->left) q.push(n->left);\n      if (n->right) q.push(n->right);\n    }\n    out.push_back(row);\n  }\n  return out;\n}","statement":"Group binary-tree values by their depth, from top to bottom.","example":"root = [3,9,20,null,null,15,7] → [[3],[9,20],[15,7]]"},"Maximum Depth of Binary Tree":{"idea":"A null subtree has height zero. Compute both child heights recursively. The current height is one plus their maximum","steps":["A null subtree has height zero.","Compute both child heights recursively.","The current height is one plus their maximum."],"time":"O(n)","space":"O(h)","python":"def maxDepth(root):\n    if not root: return 0\n    return 1 + max(maxDepth(root.left), maxDepth(root.right))","js":"function maxDepth(root) {\n  return root ? 1 + Math.max(maxDepth(root.left), maxDepth(root.right)) : 0;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint maxDepth(TreeNode* root) {\n  return root ? 1+max(maxDepth(root->left),maxDepth(root->right)) : 0;\n}","statement":"Return the number of nodes on the longest root-to-leaf path.","example":"root = [3,9,20,null,null,15,7] → 3"},"Path Sum":{"idea":"Subtract each visited value from the remaining target. At a leaf, accept only when the remainder is zero. A missing subtree cannot supply a root-to-leaf path","steps":["Subtract each visited value from the remaining target.","At a leaf, accept only when the remainder is zero.","A missing subtree cannot supply a root-to-leaf path."],"time":"O(n)","space":"O(h)","python":"def hasPathSum(root, target):\n    if not root: return False\n    target -= root.val\n    if not root.left and not root.right: return target == 0\n    return hasPathSum(root.left, target) or hasPathSum(root.right, target)","js":"function hasPathSum(root, target) {\n  if (!root) return false;\n  target -= root.val;\n  if (!root.left && !root.right) return target === 0;\n  return hasPathSum(root.left,target) || hasPathSum(root.right,target);\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nbool hasPathSum(TreeNode* root, long long target) {\n  if (!root) return false;\n  target-=root->val;\n  if (!root->left && !root->right) return target==0;\n  return hasPathSum(root->left,target)||hasPathSum(root->right,target);\n}","statement":"Determine whether a root-to-leaf path sums to the target.","example":"root = [1,2,3], target = 3 → true"},"Symmetric Tree":{"idea":"Compare the two subtrees as mirrors. Values must match, and the outer pair and inner pair must each mirror one another. Two null nodes match","steps":["Compare the two subtrees as mirrors.","Values must match, and the outer pair and inner pair must each mirror one another.","Two null nodes match."],"time":"O(n)","space":"O(h)","python":"def isSymmetric(root):\n    def mirror(a, b):\n        if not a or not b: return a is b\n        return a.val == b.val and mirror(a.left,b.right) and mirror(a.right,b.left)\n    return not root or mirror(root.left,root.right)","js":"function isSymmetric(root) {\n  function mirror(a,b) {\n    if (!a || !b) return a === b;\n    return a.val === b.val && mirror(a.left,b.right) && mirror(a.right,b.left);\n  }\n  return !root || mirror(root.left,root.right);\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nbool isSymmetric(TreeNode* root) {\n  function<bool(TreeNode*,TreeNode*)> mirror=[&](TreeNode* a,TreeNode* b) {\n    if (!a||!b) return a==b;\n    return a->val==b->val && mirror(a->left,b->right) && mirror(a->right,b->left);\n  };\n  return !root||mirror(root->left,root->right);\n}","statement":"Determine whether a binary tree is a mirror of itself.","example":"root = [1,2,2,3,4,4,3] → true"},"Invert a Binary Tree":{"idea":"Swap the left and right children of every node. Recursively invert both resulting subtrees. Return the same root after mutation","steps":["Swap the left and right children of every node.","Recursively invert both resulting subtrees.","Return the same root after mutation."],"time":"O(n)","space":"O(h)","python":"def invertTree(root):\n    if root:\n        root.left,root.right = invertTree(root.right),invertTree(root.left)\n    return root","js":"function invertTree(root) {\n  if (root) [root.left,root.right] = [invertTree(root.right),invertTree(root.left)];\n  return root;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nTreeNode* invertTree(TreeNode* root) {\n  if (root) { swap(root->left,root->right); invertTree(root->left); invertTree(root->right); }\n  return root;\n}","statement":"Swap the left and right child at every node and return the root.","example":"root = [4,2,7,1,3,6,9] → [4,7,2,9,6,3,1]"},"Same Tree":{"idea":"Compare nodes at matching positions. Two null nodes match; exactly one null node fails. Otherwise require equal values and matching left and right subtrees","steps":["Compare nodes at matching positions.","Two null nodes match; exactly one null node fails.","Otherwise require equal values and matching left and right subtrees."],"time":"O(min(n,m))","space":"O(h)","python":"def isSameTree(a,b):\n    if not a or not b: return a is b\n    return a.val == b.val and isSameTree(a.left,b.left) and isSameTree(a.right,b.right)","js":"function isSameTree(a,b) {\n  if (!a || !b) return a === b;\n  return a.val === b.val && isSameTree(a.left,b.left) && isSameTree(a.right,b.right);\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nbool isSameTree(TreeNode* a,TreeNode* b) {\n  if (!a||!b) return a==b;\n  return a->val==b->val && isSameTree(a->left,b->left) && isSameTree(a->right,b->right);\n}","statement":"Determine whether two trees have equal structure and equal values.","example":"p = [1,2,3], q = [1,2,3] → true"},"Balanced Binary Tree":{"idea":"Compute heights bottom-up once. Return a failure sentinel when a subtree is unbalanced. Propagate failure whenever child heights differ by more than one","steps":["Compute heights bottom-up once.","Return a failure sentinel when a subtree is unbalanced.","Propagate failure whenever child heights differ by more than one."],"time":"O(n)","space":"O(h)","python":"def isBalanced(root):\n    def height(n):\n        if not n: return 0\n        a,b = height(n.left),height(n.right)\n        if a < 0 or b < 0 or abs(a-b)>1: return -1\n        return 1+max(a,b)\n    return height(root)>=0","js":"function isBalanced(root) {\n  function height(n) {\n    if (!n) return 0;\n    const a=height(n.left), b=height(n.right);\n    return a<0 || b<0 || Math.abs(a-b)>1 ? -1 : 1+Math.max(a,b);\n  }\n  return height(root)>=0;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nbool isBalanced(TreeNode* root) {\n  function<int(TreeNode*)> h=[&](TreeNode* n) {\n    if (!n) return 0;\n    int a=h(n->left),b=h(n->right);\n    return a<0||b<0||abs(a-b)>1 ? -1 : 1+max(a,b);\n  };\n  return h(root)>=0;\n}","statement":"Check whether both child heights differ by at most one at every node.","example":"root = [3,9,20,null,null,15,7] → true"},"Diameter of a Binary Tree":{"idea":"The longest path through a node uses its left height plus its right height. Update a global best while computing heights bottom-up. Measure the diameter in edges","steps":["The longest path through a node uses its left height plus its right height.","Update a global best while computing heights bottom-up.","Measure the diameter in edges."],"time":"O(n)","space":"O(h)","python":"def diameterOfBinaryTree(root):\n    best=0\n    def height(n):\n        nonlocal best\n        if not n: return 0\n        a,b=height(n.left),height(n.right)\n        best=max(best,a+b)\n        return 1+max(a,b)\n    height(root)\n    return best","js":"function diameterOfBinaryTree(root) {\n  let best=0;\n  function height(n) {\n    if (!n) return 0;\n    const a=height(n.left),b=height(n.right);\n    best=Math.max(best,a+b); return 1+Math.max(a,b);\n  }\n  height(root); return best;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint diameterOfBinaryTree(TreeNode* root) {\n  int best=0;\n  function<int(TreeNode*)> h=[&](TreeNode* n) {\n    if (!n) return 0;\n    int a=h(n->left),b=h(n->right); best=max(best,a+b);\n    return 1+max(a,b);\n  };\n  h(root); return best;\n}","statement":"Return the largest number of edges on any path between two nodes.","example":"root = [1,2,3,4,5] → 3"},"Zigzag Level Order Traversal":{"idea":"Traverse levels with breadth-first search. Reverse the values at every odd-numbered level. Keep child discovery in ordinary left-to-right order","steps":["Traverse levels with breadth-first search.","Reverse the values at every odd-numbered level.","Keep child discovery in ordinary left-to-right order."],"time":"O(n)","space":"O(w)","python":"from collections import deque\ndef zigzagLevelOrder(root):\n    q = deque([root] if root else [])\n    out = []\n    while q:\n        row = []\n        for _ in range(len(q)):\n            n = q.popleft(); row.append(n.val)\n            if n.left: q.append(n.left)\n            if n.right: q.append(n.right)\n        out.append(row if len(out)%2==0 else row[::-1])\n    return out","js":"function zigzagLevelOrder(root) {\n  let q = root ? [root] : [], out = [];\n  while (q.length) {\n    const next = [], row = [];\n    for (const n of q) {\n      row.push(n.val);\n      if (n.left) next.push(n.left);\n      if (n.right) next.push(n.right);\n    }\n    if (out.length%2) row.reverse(); out.push(row); q = next;\n  }\n  return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<vector<int>> zigzagLevelOrder(TreeNode* root) {\n  vector<vector<int>> out; queue<TreeNode*> q;\n  if (root) q.push(root);\n  while (!q.empty()) {\n    vector<int> row; int size=q.size();\n    while (size--) {\n      auto n=q.front(); q.pop(); row.push_back(n->val);\n      if (n->left) q.push(n->left);\n      if (n->right) q.push(n->right);\n    }\n    if (out.size()%2) reverse(row.begin(),row.end());\n    out.push_back(row);\n  }\n  return out;\n}","statement":"Group values by level, alternating left-to-right and right-to-left.","example":"root = [3,9,20,null,null,15,7] → [[3],[20,9],[15,7]]"},"Subtree of another Tree":{"idea":"At each node, test whether the entire candidate tree matches there. If it does not, continue searching the left and right subtrees. An empty candidate is always a subtree","steps":["At each node, test whether the entire candidate tree matches there.","If it does not, continue searching the left and right subtrees.","An empty candidate is always a subtree."],"time":"O(nm)","space":"O(hn+hm)","python":"def isSameTree(a,b):\n    if not a or not b: return a is b\n    return a.val == b.val and isSameTree(a.left,b.left) and isSameTree(a.right,b.right)\ndef isSubtree(root, sub):\n    if not sub: return True\n    if not root: return False\n    return isSameTree(root,sub) or isSubtree(root.left,sub) or isSubtree(root.right,sub)","js":"function isSameTree(a,b) {\n  if (!a || !b) return a === b;\n  return a.val === b.val && isSameTree(a.left,b.left) && isSameTree(a.right,b.right);\n}\nfunction isSubtree(root,sub) {\n  if (!sub) return true;\n  if (!root) return false;\n  return isSameTree(root,sub)||isSubtree(root.left,sub)||isSubtree(root.right,sub);\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nbool isSameTree(TreeNode* a,TreeNode* b) {\n  if (!a||!b) return a==b;\n  return a->val==b->val && isSameTree(a->left,b->left) && isSameTree(a->right,b->right);\n}\nbool isSubtree(TreeNode* root,TreeNode* sub) {\n  if (!sub) return true;\n  if (!root) return false;\n  return isSameTree(root,sub)||isSubtree(root->left,sub)||isSubtree(root->right,sub);\n}","statement":"Check whether one tree exactly matches a complete subtree of another.","example":"root = [3,4,5,1,2], sub = [4,1,2] → true"},"Lowest Common Ancestor":{"idea":"Search for the two target node identities in both subtrees. If each side finds one, the current node is their common ancestor. Otherwise propagate the nonempty result; assumes both targets exist","steps":["Search for the two target node identities in both subtrees.","If each side finds one, the current node is their common ancestor.","Otherwise propagate the nonempty result; assumes both targets exist."],"time":"O(n)","space":"O(h)","python":"def lowestCommonAncestor(root,p,q):\n    if root is None or root is p or root is q: return root\n    a=lowestCommonAncestor(root.left,p,q)\n    b=lowestCommonAncestor(root.right,p,q)\n    return root if a and b else a or b","js":"function lowestCommonAncestor(root,p,q) {\n  if (!root || root===p || root===q) return root;\n  const a=lowestCommonAncestor(root.left,p,q), b=lowestCommonAncestor(root.right,p,q);\n  return a&&b ? root : a||b;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nTreeNode* lowestCommonAncestor(TreeNode* root,TreeNode* p,TreeNode* q) {\n  if (!root||root==p||root==q) return root;\n  auto a=lowestCommonAncestor(root->left,p,q),b=lowestCommonAncestor(root->right,p,q);\n  return a&&b ? root : a?a:b;\n}","statement":"Return the lowest node whose subtree contains both target node identities. Both targets exist.","example":"root = [3,5,1,6,2,0,8], p = node 5, q = node 1 → node 3"},"Binary Tree Right Side View":{"idea":"Visit the right child before the left child. The first node reached at each depth is visible from the right. Record only when entering a previously unseen depth","steps":["Visit the right child before the left child.","The first node reached at each depth is visible from the right.","Record only when entering a previously unseen depth."],"time":"O(n)","space":"O(h)","python":"def rightSideView(root):\n    out=[]\n    def visit(n,d):\n        if not n: return\n        if d==len(out): out.append(n.val)\n        visit(n.right,d+1); visit(n.left,d+1)\n    visit(root,0)\n    return out","js":"function rightSideView(root) {\n  const out=[];\n  function visit(n,d) {\n    if (!n) return;\n    if (d===out.length) out.push(n.val);\n    visit(n.right,d+1); visit(n.left,d+1);\n  }\n  visit(root,0); return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<int> rightSideView(TreeNode* root) {\n  vector<int> out;\n  function<void(TreeNode*,int)> visit=[&](TreeNode* n,int d) {\n    if (!n) return;\n    if (d==out.size()) out.push_back(n->val);\n    visit(n->right,d+1); visit(n->left,d+1);\n  };\n  visit(root,0); return out;\n}","statement":"Return the values visible when looking at the tree from its right side.","example":"root = [1,2,3,null,5,null,4] → [1,3,4]"},"Count Good Nodes in Binary Tree":{"idea":"Carry the maximum value seen on the root-to-node path. A node is good when its value is at least that maximum. Update the maximum before visiting its children","steps":["Carry the maximum value seen on the root-to-node path.","A node is good when its value is at least that maximum.","Update the maximum before visiting its children."],"time":"O(n)","space":"O(h)","python":"def goodNodes(root):\n    def visit(n,m):\n        if not n: return 0\n        return int(n.val>=m)+visit(n.left,max(m,n.val))+visit(n.right,max(m,n.val))\n    return visit(root,float('-inf'))","js":"function goodNodes(root) {\n  function visit(n,m) {\n    if (!n) return 0;\n    return Number(n.val>=m)+visit(n.left,Math.max(m,n.val))+visit(n.right,Math.max(m,n.val));\n  }\n  return visit(root,-Infinity);\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint goodNodes(TreeNode* root) {\n  function<int(TreeNode*,int)> visit=[&](TreeNode* n,int m) {\n    if (!n) return 0;\n    return int(n->val>=m)+visit(n->left,max(m,n->val))+visit(n->right,max(m,n->val));\n  };\n  return visit(root,INT_MIN);\n}","statement":"Count nodes whose value is at least every value on their root-to-node path.","example":"root = [3,1,4,3,null,1,5] → 4"},"Populating Next Right Pointers in Each Node":{"idea":"Process one level at a time. Link every node to the next node in that level and terminate the last link with null. The queue approach also works for non-perfect trees","steps":["Process one level at a time.","Link every node to the next node in that level and terminate the last link with null.","The queue approach also works for non-perfect trees."],"time":"O(n)","space":"O(w)","python":"def connect(root):\n    level=[root] if root else []\n    while level:\n        nxt=[]\n        for i,n in enumerate(level):\n            n.next=level[i+1] if i+1<len(level) else None\n            if n.left: nxt.append(n.left)\n            if n.right: nxt.append(n.right)\n        level=nxt\n    return root","js":"function connect(root) {\n  let level=root?[root]:[];\n  while (level.length) {\n    const next=[];\n    level.forEach((n,i)=>{\n      n.next=level[i+1]??null;\n      if(n.left) next.push(n.left); if(n.right) next.push(n.right);\n    });\n    level=next;\n  }\n  return root;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nNode* connect(Node* root) {\n  queue<Node*> q; if(root) q.push(root);\n  while(!q.empty()) {\n    int size=q.size(); Node* prev=nullptr;\n    while(size--) {\n      Node* n=q.front(); q.pop(); if(prev) prev->next=n; prev=n;\n      if(n->left) q.push(n->left); if(n->right) q.push(n->right);\n    }\n    prev->next=nullptr;\n  }\n  return root;\n}","statement":"Set every node’s next pointer to its immediate neighbor on the same level, or null.","example":"root = [1,2,3,4,5,6,7] → next chains [1], [2,3], [4,5,6,7]"},"Binary Tree Maximum Path Sum":{"idea":"A parent can extend only one downward branch. Clamp negative child gains to zero, but update the best path using both child gains. Initialize the answer below all node values to handle all-negative trees","steps":["A parent can extend only one downward branch.","Clamp negative child gains to zero, but update the best path using both child gains.","Initialize the answer below all node values to handle all-negative trees."],"time":"O(n)","space":"O(h)","python":"def maxPathSum(root):\n    best=float('-inf')\n    def gain(n):\n        nonlocal best\n        if not n: return 0\n        a,b=max(0,gain(n.left)),max(0,gain(n.right))\n        best=max(best,n.val+a+b)\n        return n.val+max(a,b)\n    gain(root)\n    return best","js":"function maxPathSum(root) {\n  let best=-Infinity;\n  function gain(n) {\n    if(!n) return 0;\n    const a=Math.max(0,gain(n.left)),b=Math.max(0,gain(n.right));\n    best=Math.max(best,n.val+a+b); return n.val+Math.max(a,b);\n  }\n  gain(root); return best;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint maxPathSum(TreeNode* root) {\n  int best=INT_MIN;\n  function<int(TreeNode*)> gain=[&](TreeNode* n) {\n    if(!n) return 0;\n    int a=max(0,gain(n->left)),b=max(0,gain(n->right));\n    best=max(best,n->val+a+b); return n->val+max(a,b);\n  };\n  gain(root); return best;\n}","statement":"Find the largest sum along any nonempty simple path in a binary tree.","example":"root = [-10,9,20,null,null,15,7] → 42"},"Valid Binary Search Tree":{"idea":"Every node must lie strictly inside the bounds inherited from its ancestors. The left subtree lowers the upper bound; the right subtree raises the lower bound. Strict bounds reject duplicate keys","steps":["Every node must lie strictly inside the bounds inherited from its ancestors.","The left subtree lowers the upper bound; the right subtree raises the lower bound.","Strict bounds reject duplicate keys."],"time":"O(n)","space":"O(h)","python":"def isValidBST(root):\n    def check(n,lo,hi):\n        return not n or (lo<n.val<hi and check(n.left,lo,n.val) and check(n.right,n.val,hi))\n    return check(root,float('-inf'),float('inf'))","js":"function isValidBST(root) {\n  function check(n,lo,hi) {\n    return !n || (lo<n.val && n.val<hi && check(n.left,lo,n.val) && check(n.right,n.val,hi));\n  }\n  return check(root,-Infinity,Infinity);\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nbool isValidBST(TreeNode* root) {\n  function<bool(TreeNode*,long long,long long)> check=[&](TreeNode* n,long long lo,long long hi) {\n    return !n||(lo<n->val&&n->val<hi&&check(n->left,lo,n->val)&&check(n->right,n->val,hi));\n  };\n  return check(root,LLONG_MIN,LLONG_MAX);\n}","statement":"Check whether every left key is smaller and every right key larger than all relevant ancestors.","example":"root = [2,1,3] → true"},"Search in a BST":{"idea":"Compare the target with the current key. Move left for a smaller target and right for a larger target. Stop at the matching node or a null pointer","steps":["Compare the target with the current key.","Move left for a smaller target and right for a larger target.","Stop at the matching node or a null pointer."],"time":"O(h)","space":"O(1)","python":"def searchBST(root,val):\n    while root and root.val!=val:\n        root=root.left if val<root.val else root.right\n    return root","js":"function searchBST(root,val) {\n  while(root && root.val!==val) root=val<root.val?root.left:root.right;\n  return root;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nTreeNode* searchBST(TreeNode* root,int val) {\n  while(root&&root->val!=val) root=val<root->val?root->left:root->right;\n  return root;\n}","statement":"Return the BST node containing the target value, or null if absent.","example":"root = [4,2,7,1,3], val = 2 → subtree [2,1,3]"},"Insert into a BST":{"idea":"Follow the BST comparison rule to find an empty child position. Create a new leaf there. Return the existing root; duplicate values are ignored","steps":["Follow the BST comparison rule to find an empty child position.","Create a new leaf there.","Return the existing root; duplicate values are ignored."],"time":"O(h)","space":"O(h)","python":"def insertIntoBST(root,val):\n    if not root: return TreeNode(val)\n    if val<root.val: root.left=insertIntoBST(root.left,val)\n    elif val>root.val: root.right=insertIntoBST(root.right,val)\n    return root","js":"function insertIntoBST(root,val) {\n  if(!root) return new TreeNode(val);\n  if(val<root.val) root.left=insertIntoBST(root.left,val);\n  else if(val>root.val) root.right=insertIntoBST(root.right,val);\n  return root;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nTreeNode* insertIntoBST(TreeNode* root,int val) {\n  if(!root) return new TreeNode(val);\n  if(val<root->val) root->left=insertIntoBST(root->left,val);\n  else if(val>root->val) root->right=insertIntoBST(root->right,val);\n  return root;\n}","statement":"Insert a new distinct key into a BST and return its root.","example":"root = [4,2,7,1,3], val = 5 → [4,2,7,1,3,5]"},"Kth Smallest Element":{"idea":"An inorder traversal of a BST produces ascending keys. Use an explicit stack and decrement k each time a node is removed. The kth removed key is the answer; k must be valid","steps":["An inorder traversal of a BST produces ascending keys.","Use an explicit stack and decrement k each time a node is removed.","The kth removed key is the answer; k must be valid."],"time":"O(h+k)","space":"O(h)","python":"def kthSmallest(root,k):\n    stack=[]\n    while root or stack:\n        while root: stack.append(root); root=root.left\n        root=stack.pop(); k-=1\n        if k==0: return root.val\n        root=root.right\n    raise ValueError('k out of range')","js":"function kthSmallest(root,k) {\n  const stack=[];\n  while(root||stack.length) {\n    while(root) { stack.push(root); root=root.left; }\n    root=stack.pop(); if(--k===0) return root.val;\n    root=root.right;\n  }\n  throw new RangeError('k out of range');\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint kthSmallest(TreeNode* root,int k) {\n  stack<TreeNode*> st;\n  while(root||!st.empty()) {\n    while(root) { st.push(root); root=root->left; }\n    root=st.top(); st.pop(); if(--k==0) return root->val;\n    root=root->right;\n  }\n  throw invalid_argument(\"k out of range\");\n}","statement":"Return the kth smallest key in a BST, using one-based k.","example":"root = [3,1,4,null,2], k = 1 → 1"},"Lowest Common Ancestor of a BST":{"idea":"Use the ordering of both target keys. If both are smaller, go left; if both are larger, go right. The first split point, including either target itself, is the ancestor","steps":["Use the ordering of both target keys.","If both are smaller, go left; if both are larger, go right.","The first split point, including either target itself, is the ancestor."],"time":"O(h)","space":"O(1)","python":"def lowestCommonAncestor(root,p,q):\n    lo,hi=sorted((p.val,q.val))\n    while root:\n        if root.val<lo: root=root.right\n        elif root.val>hi: root=root.left\n        else: return root","js":"function lowestCommonAncestor(root,p,q) {\n  const lo=Math.min(p.val,q.val),hi=Math.max(p.val,q.val);\n  while(root) {\n    if(root.val<lo) root=root.right;\n    else if(root.val>hi) root=root.left;\n    else return root;\n  }\n  return null;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nTreeNode* lowestCommonAncestor(TreeNode* root,TreeNode* p,TreeNode* q) {\n  int lo=min(p->val,q->val),hi=max(p->val,q->val);\n  while(root) {\n    if(root->val<lo) root=root->right;\n    else if(root->val>hi) root=root->left;\n    else return root;\n  }\n  return nullptr;\n}","statement":"Return the lowest BST node whose subtree contains both existing targets.","example":"root = [6,2,8,0,4,7,9], p = node 2, q = node 8 → node 6"},"Kth Largest Element in an Array":{"idea":"Keep a min-heap of at most k elements. Whenever its size exceeds k, remove the smallest. The heap root is then the kth largest value, counting duplicates","steps":["Keep a min-heap of at most k elements.","Whenever its size exceeds k, remove the smallest.","The heap root is then the kth largest value, counting duplicates."],"time":"O(n log k)","space":"O(k)","python":"import heapq\ndef findKthLargest(nums,k):\n    heap=[]\n    for x in nums:\n        heapq.heappush(heap,x)\n        if len(heap)>k: heapq.heappop(heap)\n    return heap[0]","js":"// Min-heap; pass (a,b)=>b-a for a max-heap.\nclass Heap {\n  constructor(cmp=(a,b)=>a-b){this.a=[];this.cmp=cmp;}\n  get size(){return this.a.length;}\n  peek(){return this.a[0];}\n  push(x){const a=this.a;a.push(x);let i=a.length-1;\n    while(i){let p=(i-1)>>1;if(this.cmp(a[p],a[i])<=0)break;[a[p],a[i]]=[a[i],a[p]];i=p;}}\n  pop(){const a=this.a;if(!a.length)return undefined;const out=a[0],x=a.pop();\n    if(a.length){a[0]=x;let i=0;while(true){let j=2*i+1;if(j>=a.length)break;\n      if(j+1<a.length&&this.cmp(a[j+1],a[j])<0)j++;\n      if(this.cmp(a[i],a[j])<=0)break;[a[i],a[j]]=[a[j],a[i]];i=j;}}\n    return out;}\n}\nfunction findKthLargest(nums,k){\n  const h=new Heap();\n  for(const x of nums){h.push(x);if(h.size>k)h.pop();}\n  return h.peek();\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint findKthLargest(vector<int>& nums,int k){\n  priority_queue<int,vector<int>,greater<int>> h;\n  for(int x:nums){h.push(x);if(h.size()>k)h.pop();}\n  return h.top();\n}","statement":"Return the kth largest element, counting duplicate positions separately.","example":"nums = [3,2,1,5,6,4], k = 2 → 5"},"Kth Largest Element in a Stream":{"idea":"Persist a min-heap containing the k largest values seen. Insert each new stream value and trim any excess. Once at least k values exist, the smallest retained value is the answer","steps":["Persist a min-heap containing the k largest values seen.","Insert each new stream value and trim any excess.","Once at least k values exist, the smallest retained value is the answer."],"time":"O(log k) per add","space":"O(k)","python":"import heapq\nclass KthLargest:\n    def __init__(self,k,nums):\n        self.k=k; self.h=[]\n        for x in nums: self.add(x)\n    def add(self,val):\n        heapq.heappush(self.h,val)\n        if len(self.h)>self.k: heapq.heappop(self.h)\n        return self.h[0]","js":"// Min-heap; pass (a,b)=>b-a for a max-heap.\nclass Heap {\n  constructor(cmp=(a,b)=>a-b){this.a=[];this.cmp=cmp;}\n  get size(){return this.a.length;}\n  peek(){return this.a[0];}\n  push(x){const a=this.a;a.push(x);let i=a.length-1;\n    while(i){let p=(i-1)>>1;if(this.cmp(a[p],a[i])<=0)break;[a[p],a[i]]=[a[i],a[p]];i=p;}}\n  pop(){const a=this.a;if(!a.length)return undefined;const out=a[0],x=a.pop();\n    if(a.length){a[0]=x;let i=0;while(true){let j=2*i+1;if(j>=a.length)break;\n      if(j+1<a.length&&this.cmp(a[j+1],a[j])<0)j++;\n      if(this.cmp(a[i],a[j])<=0)break;[a[i],a[j]]=[a[j],a[i]];i=j;}}\n    return out;}\n}\nclass KthLargest {\n  constructor(k,nums){this.k=k;this.h=new Heap();for(const x of nums)this.add(x);}\n  add(val){this.h.push(val);if(this.h.size>this.k)this.h.pop();return this.h.peek();}\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nclass KthLargest {\n  int k; priority_queue<int,vector<int>,greater<int>> h;\npublic:\n  KthLargest(int k,vector<int>& nums):k(k){for(int x:nums)add(x);}\n  int add(int val){h.push(val);if(h.size()>k)h.pop();return h.top();}\n};","statement":"Maintain the kth largest value as new values are added to a stream.","example":"k = 3, nums = [4,5,8,2]; add(3) → 4; add(5) → 5"},"Last Stone Weight":{"idea":"Use a max-heap to remove the two heaviest stones. If their weights differ, insert the difference. Repeat until at most one stone remains","steps":["Use a max-heap to remove the two heaviest stones.","If their weights differ, insert the difference.","Repeat until at most one stone remains."],"time":"O(n log n)","space":"O(n)","python":"import heapq\ndef lastStoneWeight(stones):\n    h=[-x for x in stones]; heapq.heapify(h)\n    while len(h)>1:\n        a,b=-heapq.heappop(h),-heapq.heappop(h)\n        if a!=b: heapq.heappush(h,b-a)\n    return -h[0] if h else 0","js":"// Min-heap; pass (a,b)=>b-a for a max-heap.\nclass Heap {\n  constructor(cmp=(a,b)=>a-b){this.a=[];this.cmp=cmp;}\n  get size(){return this.a.length;}\n  peek(){return this.a[0];}\n  push(x){const a=this.a;a.push(x);let i=a.length-1;\n    while(i){let p=(i-1)>>1;if(this.cmp(a[p],a[i])<=0)break;[a[p],a[i]]=[a[i],a[p]];i=p;}}\n  pop(){const a=this.a;if(!a.length)return undefined;const out=a[0],x=a.pop();\n    if(a.length){a[0]=x;let i=0;while(true){let j=2*i+1;if(j>=a.length)break;\n      if(j+1<a.length&&this.cmp(a[j+1],a[j])<0)j++;\n      if(this.cmp(a[i],a[j])<=0)break;[a[i],a[j]]=[a[j],a[i]];i=j;}}\n    return out;}\n}\nfunction lastStoneWeight(stones){\n  const h=new Heap((a,b)=>b-a);for(const x of stones)h.push(x);\n  while(h.size>1){const a=h.pop(),b=h.pop();if(a!==b)h.push(a-b);}\n  return h.size?h.pop():0;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint lastStoneWeight(vector<int>& stones){\n  priority_queue<int> h(stones.begin(),stones.end());\n  while(h.size()>1){int a=h.top();h.pop();int b=h.top();h.pop();if(a!=b)h.push(a-b);}\n  return h.empty()?0:h.top();\n}","statement":"Repeatedly smash the two heaviest stones; keep their difference if unequal. Return the remaining weight.","example":"stones = [2,7,4,1,8,1] → 1"},"Top K Frequent Elements":{"idea":"Count occurrences in a hash map. Place each value in a bucket indexed by its frequency. Read buckets from largest frequency downward until k values have been collected","steps":["Count occurrences in a hash map.","Place each value in a bucket indexed by its frequency.","Read buckets from largest frequency downward until k values have been collected."],"time":"O(n)","space":"O(n)","python":"from collections import Counter\ndef topKFrequent(nums,k):\n    buckets=[[] for _ in range(len(nums)+1)]\n    for x,c in Counter(nums).items(): buckets[c].append(x)\n    out=[]\n    for b in reversed(buckets):\n        for x in b:\n            out.append(x)\n            if len(out)==k: return out\n    return out","js":"function topKFrequent(nums,k){\n  const count=new Map(),b=Array.from({length:nums.length+1},()=>[]),out=[];\n  for(const x of nums)count.set(x,(count.get(x)||0)+1);\n  for(const [x,c] of count)b[c].push(x);\n  for(let i=b.length-1;i>=0;i--)for(const x of b[i]){out.push(x);if(out.length===k)return out;}\n  return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<int> topKFrequent(vector<int>& nums,int k){\n  unordered_map<int,int> count;for(int x:nums)count[x]++;\n  vector<vector<int>> b(nums.size()+1);for(auto entry:count)b[entry.second].push_back(entry.first);\n  vector<int> out;for(int i=b.size()-1;i>=0;i--)for(int x:b[i]){out.push_back(x);if(out.size()==k)return out;}\n  return out;\n}","statement":"Return the k distinct values with highest occurrence counts, in any order.","example":"nums = [1,1,1,2,2,3], k = 2 → [1,2]"},"Kth Smallest Element in a Sorted Matrix":{"idea":"Treat each sorted row as an individual stream. Initialize a min-heap with the first value of each nonempty row. Remove the smallest k times, advancing only the row from which it came","steps":["Treat each sorted row as an individual stream.","Initialize a min-heap with the first value of each nonempty row.","Remove the smallest k times, advancing only the row from which it came."],"time":"O(r+k log r)","space":"O(r)","python":"import heapq\ndef kthSmallest(matrix,k):\n    h=[(row[0],i,0) for i,row in enumerate(matrix) if row]\n    heapq.heapify(h)\n    for _ in range(k):\n        value,r,c=heapq.heappop(h)\n        if c+1<len(matrix[r]): heapq.heappush(h,(matrix[r][c+1],r,c+1))\n    return value","js":"// Min-heap; pass (a,b)=>b-a for a max-heap.\nclass Heap {\n  constructor(cmp=(a,b)=>a-b){this.a=[];this.cmp=cmp;}\n  get size(){return this.a.length;}\n  peek(){return this.a[0];}\n  push(x){const a=this.a;a.push(x);let i=a.length-1;\n    while(i){let p=(i-1)>>1;if(this.cmp(a[p],a[i])<=0)break;[a[p],a[i]]=[a[i],a[p]];i=p;}}\n  pop(){const a=this.a;if(!a.length)return undefined;const out=a[0],x=a.pop();\n    if(a.length){a[0]=x;let i=0;while(true){let j=2*i+1;if(j>=a.length)break;\n      if(j+1<a.length&&this.cmp(a[j+1],a[j])<0)j++;\n      if(this.cmp(a[i],a[j])<=0)break;[a[i],a[j]]=[a[j],a[i]];i=j;}}\n    return out;}\n}\nfunction kthSmallest(matrix,k){\n  const h=new Heap((a,b)=>a[0]-b[0]);\n  matrix.forEach((row,r)=>{if(row.length)h.push([row[0],r,0]);});\n  let value;\n  while(k--){const [v,r,c]=h.pop();value=v;if(c+1<matrix[r].length)h.push([matrix[r][c+1],r,c+1]);}\n  return value;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint kthSmallest(vector<vector<int>>& a,int k){\n  using T=tuple<int,int,int>;priority_queue<T,vector<T>,greater<T>> h;\n  for(int r=0;r<a.size();r++)if(!a[r].empty())h.emplace(a[r][0],r,0);\n  int value=0;while(k--){auto item=h.top();int v=get<0>(item),r=get<1>(item),c=get<2>(item);h.pop();value=v;if(c+1<a[r].size())h.emplace(a[r][c+1],r,c+1);}\n  return value;\n}","statement":"Return the kth smallest entry in a matrix whose rows and columns are sorted.","example":"matrix = [[1,5,9],[10,11,13],[12,13,15]], k = 8 → 13"},"Subsets - The Power Set":{"idea":"At each index choose whether to include that value. Start with the empty subset and duplicate the current collection with the new value appended. Distinct input values produce every subset exactly once","steps":["At each index choose whether to include that value.","Start with the empty subset and duplicate the current collection with the new value appended.","Distinct input values produce every subset exactly once."],"time":"O(n 2^n)","space":"O(n 2^n) output","python":"def subsets(nums):\n    out=[[]]\n    for x in nums: out += [s+[x] for s in out]\n    return out","js":"function subsets(nums){\n  let out=[[]];for(const x of nums)out=out.concat(out.map(s=>[...s,x]));return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<vector<int>> subsets(vector<int>& nums){\n  vector<vector<int>> out(1);\n  for(int x:nums){int n=out.size();for(int i=0;i<n;i++){auto s=out[i];s.push_back(x);out.push_back(s);}}\n  return out;\n}","statement":"Return every subset of an array of distinct values, including the empty subset.","example":"nums = [1,2] → [[],[1],[2],[1,2]]"},"Combinations":{"idea":"Build increasing selections from 1 through n. After choosing x, continue only with larger values. Prune when too few values remain to reach size k","steps":["Build increasing selections from 1 through n.","After choosing x, continue only with larger values.","Prune when too few values remain to reach size k."],"time":"O(k C(n,k))","space":"O(k) auxiliary plus output","python":"def combine(n,k):\n    out=[]; path=[]\n    def dfs(start):\n        if len(path)==k: out.append(path[:]); return\n        for x in range(start,n-(k-len(path))+2):\n            path.append(x); dfs(x+1); path.pop()\n    dfs(1)\n    return out","js":"function combine(n,k){\n  const out=[],path=[];\n  function dfs(start){\n    if(path.length===k){out.push([...path]);return;}\n    for(let x=start;x<=n-(k-path.length)+1;x++){path.push(x);dfs(x+1);path.pop();}\n  }\n  dfs(1);return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<vector<int>> combine(int n,int k){\n  vector<vector<int>> out;vector<int> path;\n  function<void(int)> dfs=[&](int start){\n    if(path.size()==k){out.push_back(path);return;}\n    for(int x=start;x<=n-(k-(int)path.size())+1;x++){path.push_back(x);dfs(x+1);path.pop_back();}\n  };dfs(1);return out;\n}","statement":"Return all size-k selections from the integers 1 through n.","example":"n = 4, k = 2 → [[1,2],[1,3],[1,4],[2,3],[2,4],[3,4]]"},"Permutations":{"idea":"Choose each unused input position as the next element. Mark it used during recursion and undo the choice afterward. Copy the path when it contains all n values; assumes distinct values","steps":["Choose each unused input position as the next element.","Mark it used during recursion and undo the choice afterward.","Copy the path when it contains all n values; assumes distinct values."],"time":"O(n n!)","space":"O(n) auxiliary plus output","python":"def permute(nums):\n    out=[]; path=[]; used=[False]*len(nums)\n    def dfs():\n        if len(path)==len(nums): out.append(path[:]); return\n        for i,x in enumerate(nums):\n            if used[i]: continue\n            used[i]=True; path.append(x); dfs(); path.pop(); used[i]=False\n    dfs()\n    return out","js":"function permute(nums){\n  const out=[],path=[],used=Array(nums.length).fill(false);\n  function dfs(){\n    if(path.length===nums.length){out.push([...path]);return;}\n    nums.forEach((x,i)=>{if(!used[i]){used[i]=true;path.push(x);dfs();path.pop();used[i]=false;}});\n  }\n  dfs();return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<vector<int>> permute(vector<int>& nums){\n  vector<vector<int>> out;vector<int> path;vector<bool> used(nums.size());\n  function<void()> dfs=[&](){\n    if(path.size()==nums.size()){out.push_back(path);return;}\n    for(int i=0;i<nums.size();i++)if(!used[i]){used[i]=true;path.push_back(nums[i]);dfs();path.pop_back();used[i]=false;}\n  };dfs();return out;\n}","statement":"Return all possible orderings of an array of distinct values.","example":"nums = [1,2] → [[1,2],[2,1]]"},"Subset - II":{"idea":"Sort equal values next to each other. During one recursion level skip equal values after their first occurrence. Record every partial path, including the empty path","steps":["Sort equal values next to each other.","During one recursion level skip equal values after their first occurrence.","Record every partial path, including the empty path."],"time":"O(n 2^n)","space":"O(n) auxiliary plus output","python":"def subsetsWithDup(nums):\n    nums=sorted(nums); out=[]; path=[]\n    def dfs(start):\n        out.append(path[:])\n        for i in range(start,len(nums)):\n            if i>start and nums[i]==nums[i-1]: continue\n            path.append(nums[i]); dfs(i+1); path.pop()\n    dfs(0)\n    return out","js":"function subsetsWithDup(nums){\n  nums=[...nums].sort((a,b)=>a-b);const out=[],path=[];\n  function dfs(start){out.push([...path]);for(let i=start;i<nums.length;i++){\n    if(i>start&&nums[i]===nums[i-1])continue;path.push(nums[i]);dfs(i+1);path.pop();\n  }}dfs(0);return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<vector<int>> subsetsWithDup(vector<int> nums){\n  sort(nums.begin(),nums.end());vector<vector<int>> out;vector<int> path;\n  function<void(int)> dfs=[&](int start){out.push_back(path);for(int i=start;i<nums.size();i++){\n    if(i>start&&nums[i]==nums[i-1])continue;path.push_back(nums[i]);dfs(i+1);path.pop_back();\n  }};dfs(0);return out;\n}","statement":"Return every distinct subset of an array that may contain duplicate values.","example":"nums = [1,2,2] → [[],[1],[1,2],[1,2,2],[2],[2,2]]"},"Combination Sum":{"idea":"Sort the positive candidates and grow a nondecreasing path. Reuse the chosen index so a number may appear repeatedly. Stop a branch when its remaining target becomes negative, and record it when the target reaches zero","steps":["Sort the positive candidates and grow a nondecreasing path.","Reuse the chosen index so a number may appear repeatedly.","Stop a branch when its remaining target becomes negative, and record it when the target reaches zero."],"time":"Exponential in target / minimum candidate","space":"O(target / min candidate) auxiliary plus output","python":"def combinationSum(candidates,target):\n    a=sorted(set(candidates)) if True else sorted(candidates)\n    out=[]; path=[]\n    def dfs(start,left):\n        if left==0: out.append(path[:]); return\n        for i in range(start,len(a)):\n            if a[i]>left: break\n            if not True and i>start and a[i]==a[i-1]: continue\n            path.append(a[i]); dfs(i,left-a[i]); path.pop()\n    dfs(0,target)\n    return out","js":"function combinationSum(candidates,target){\n  const a=[...new Set(candidates)].sort((a,b)=>a-b),out=[],path=[];\n  function dfs(start,left){\n    if(left===0){out.push([...path]);return;}\n    for(let i=start;i<a.length;i++){\n      if(a[i]>left)break;\n      \n      path.push(a[i]);dfs(i,left-a[i]);path.pop();\n    }\n  }dfs(0,target);return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<vector<int>> combinationSum(vector<int> a,int target){\n  sort(a.begin(),a.end());a.erase(unique(a.begin(),a.end()),a.end());\n  vector<vector<int>> out;vector<int> path;\n  function<void(int,int)> dfs=[&](int start,int left){\n    if(left==0){out.push_back(path);return;}\n    for(int i=start;i<a.size()&&a[i]<=left;i++){\n      \n      path.push_back(a[i]);dfs(i,left-a[i]);path.pop_back();\n    }\n  };dfs(0,target);return out;\n}","statement":"Return unique combinations of positive candidate values summing to target; values may be reused.","example":"candidates = [2,3,6,7], target = 7 → [[2,2,3],[7]]"},"Combination Sum - II":{"idea":"Sort the positive candidates and grow a nondecreasing path. Advance past the chosen index and skip duplicates at the same depth. Stop a branch when its remaining target becomes negative, and record it when the target reaches zero","steps":["Sort the positive candidates and grow a nondecreasing path.","Advance past the chosen index and skip duplicates at the same depth.","Stop a branch when its remaining target becomes negative, and record it when the target reaches zero."],"time":"O(n 2^n)","space":"O(n) auxiliary plus output","python":"def combinationSum(candidates,target):\n    a=sorted(set(candidates)) if False else sorted(candidates)\n    out=[]; path=[]\n    def dfs(start,left):\n        if left==0: out.append(path[:]); return\n        for i in range(start,len(a)):\n            if a[i]>left: break\n            if not False and i>start and a[i]==a[i-1]: continue\n            path.append(a[i]); dfs(i+1,left-a[i]); path.pop()\n    dfs(0,target)\n    return out","js":"function combinationSum(candidates,target){\n  const a=[...candidates].sort((a,b)=>a-b),out=[],path=[];\n  function dfs(start,left){\n    if(left===0){out.push([...path]);return;}\n    for(let i=start;i<a.length;i++){\n      if(a[i]>left)break;\n      if(i>start&&a[i]===a[i-1])continue;\n      path.push(a[i]);dfs(i+1,left-a[i]);path.pop();\n    }\n  }dfs(0,target);return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<vector<int>> combinationSum(vector<int> a,int target){\n  sort(a.begin(),a.end());\n  vector<vector<int>> out;vector<int> path;\n  function<void(int,int)> dfs=[&](int start,int left){\n    if(left==0){out.push_back(path);return;}\n    for(int i=start;i<a.size()&&a[i]<=left;i++){\n      if(i>start&&a[i]==a[i-1])continue;\n      path.push_back(a[i]);dfs(i+1,left-a[i]);path.pop_back();\n    }\n  };dfs(0,target);return out;\n}","statement":"Return unique combinations summing to target; each input position may be used once.","example":"candidates = [10,1,2,7,6,1,5], target = 8 → [[1,1,6],[1,2,5],[1,7],[2,6]]"},"Combination Sum - III":{"idea":"Choose increasing distinct digits from 1 through 9. Track both the remaining sum and the number of chosen digits. Record a path only when both requirements are exactly satisfied","steps":["Choose increasing distinct digits from 1 through 9.","Track both the remaining sum and the number of chosen digits.","Record a path only when both requirements are exactly satisfied."],"time":"O(2^9 k)","space":"O(k) auxiliary plus output","python":"def combinationSum3(k,n):\n    out=[]; path=[]\n    def dfs(start,left):\n        if len(path)==k:\n            if left==0: out.append(path[:])\n            return\n        for x in range(start,10):\n            if x>left: break\n            path.append(x); dfs(x+1,left-x); path.pop()\n    dfs(1,n)\n    return out","js":"function combinationSum3(k,n){\n  const out=[],path=[];\n  function dfs(start,left){\n    if(path.length===k){if(left===0)out.push([...path]);return;}\n    for(let x=start;x<=9&&x<=left;x++){path.push(x);dfs(x+1,left-x);path.pop();}\n  }dfs(1,n);return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<vector<int>> combinationSum3(int k,int n){\n  vector<vector<int>> out;vector<int> path;\n  function<void(int,int)> dfs=[&](int start,int left){\n    if(path.size()==k){if(left==0)out.push_back(path);return;}\n    for(int x=start;x<=9&&x<=left;x++){path.push_back(x);dfs(x+1,left-x);path.pop_back();}\n  };dfs(1,n);return out;\n}","statement":"Choose k distinct digits from 1 to 9 whose sum is n.","example":"k = 3, n = 7 → [[1,2,4]]"},"Letter Combinations of a Phone Number":{"idea":"Map each digit from 2 to 9 to its letters. Extend every partial string with each letter of the next digit. Empty input returns no combinations","steps":["Map each digit from 2 to 9 to its letters.","Extend every partial string with each letter of the next digit.","Empty input returns no combinations."],"time":"O(n 4^n)","space":"O(n 4^n) output","python":"def letterCombinations(digits):\n    if not digits: return []\n    keys={'2':'abc','3':'def','4':'ghi','5':'jkl','6':'mno','7':'pqrs','8':'tuv','9':'wxyz'}\n    out=['']\n    for d in digits: out=[p+c for p in out for c in keys[d]]\n    return out","js":"function letterCombinations(digits){\n  if(!digits)return [];\n  const keys={2:'abc',3:'def',4:'ghi',5:'jkl',6:'mno',7:'pqrs',8:'tuv',9:'wxyz'};\n  let out=[''];for(const d of digits)out=out.flatMap(p=>[...keys[d]].map(c=>p+c));return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<string> letterCombinations(string digits){\n  if(digits.empty())return {};\n  vector<string> keys={\"\",\"\",\"abc\",\"def\",\"ghi\",\"jkl\",\"mno\",\"pqrs\",\"tuv\",\"wxyz\"},out={\"\"};\n  for(char d:digits){vector<string> next;for(auto p:out)for(char c:keys[d-'0'])next.push_back(p+c);out=move(next);}\n  return out;\n}","statement":"Return the possible letter strings represented by phone-keypad digits 2 through 9.","example":"digits = \"23\" → [\"ad\",\"ae\",\"af\",\"bd\",\"be\",\"bf\",\"cd\",\"ce\",\"cf\"]"},"Permutations - II":{"idea":"Sort equal values next to each other. Choose unused positions, but skip an equal value if its previous equal position is still unused. This fixes a unique order for equal choices and prevents duplicate permutations","steps":["Sort equal values next to each other.","Choose unused positions, but skip an equal value if its previous equal position is still unused.","This fixes a unique order for equal choices and prevents duplicate permutations."],"time":"O(n n!)","space":"O(n) auxiliary plus output","python":"def permute(nums):\n    nums=sorted(nums)\n    out=[]; path=[]; used=[False]*len(nums)\n    def dfs():\n        if len(path)==len(nums): out.append(path[:]); return\n        for i,x in enumerate(nums):\n            if used[i] or (i>0 and nums[i]==nums[i-1] and not used[i-1]): continue\n            used[i]=True; path.append(x); dfs(); path.pop(); used[i]=False\n    dfs()\n    return out","js":"function permute(nums){\n  nums=[...nums].sort((a,b)=>a-b);\n  const out=[],path=[],used=Array(nums.length).fill(false);\n  function dfs(){\n    if(path.length===nums.length){out.push([...path]);return;}\n    nums.forEach((x,i)=>{if(!used[i]&&!(i>0&&nums[i]===nums[i-1]&&!used[i-1])){used[i]=true;path.push(x);dfs();path.pop();used[i]=false;}});\n  }\n  dfs();return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<vector<int>> permute(vector<int>& nums){\n  sort(nums.begin(),nums.end());\n  vector<vector<int>> out;vector<int> path;vector<bool> used(nums.size());\n  function<void()> dfs=[&](){\n    if(path.size()==nums.size()){out.push_back(path);return;}\n    for(int i=0;i<nums.size();i++)if(!used[i]&&!(i>0&&nums[i]==nums[i-1]&&!used[i-1])){used[i]=true;path.push_back(nums[i]);dfs();path.pop_back();used[i]=false;}\n  };dfs();return out;\n}","statement":"Return all distinct orderings of values that may contain duplicates.","example":"nums = [1,1,2] → [[1,1,2],[1,2,1],[2,1,1]]"},"Palindrome Partitioning":{"idea":"Try every possible next substring starting at the current position. Recurse only when that substring reads the same forwards and backwards. Record a partition after consuming the whole string","steps":["Try every possible next substring starting at the current position.","Recurse only when that substring reads the same forwards and backwards.","Record a partition after consuming the whole string."],"time":"O(n^2 2^n)","space":"O(n) auxiliary plus output","python":"def partition(s):\n    out=[]; path=[]\n    def dfs(start):\n        if start==len(s): out.append(path[:]); return\n        for end in range(start+1,len(s)+1):\n            part=s[start:end]\n            if part==part[::-1]:\n                path.append(part); dfs(end); path.pop()\n    dfs(0)\n    return out","js":"function partition(s){\n  const out=[],path=[];\n  function dfs(start){\n    if(start===s.length){out.push([...path]);return;}\n    for(let end=start+1;end<=s.length;end++){\n      const p=s.slice(start,end);if(p===[...p].reverse().join('')){path.push(p);dfs(end);path.pop();}\n    }\n  }dfs(0);return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<vector<string>> partition(string s){\n  vector<vector<string>> out;vector<string> path;\n  function<void(int)> dfs=[&](int start){\n    if(start==s.size()){out.push_back(path);return;}\n    for(int end=start+1;end<=s.size();end++){\n      string p=s.substr(start,end-start),r=p;reverse(r.begin(),r.end());\n      if(p==r){path.push_back(p);dfs(end);path.pop_back();}\n    }\n  };dfs(0);return out;\n}","statement":"Split a string into every possible list of palindromic substrings.","example":"s = \"aab\" → [[\"a\",\"a\",\"b\"],[\"aa\",\"b\"]]"},"Word Search":{"idea":"Start a search at each cell matching the first character. Mark cells used in the current path so they cannot be reused. Explore four neighbors and restore the mark when backtracking","steps":["Start a search at each cell matching the first character.","Mark cells used in the current path so they cannot be reused.","Explore four neighbors and restore the mark when backtracking."],"time":"O(rows cols 3^L)","space":"O(L)","python":"def exist(board,word):\n    if not word: return True\n    if not board or not board[0]: return False\n    m,n=len(board),len(board[0]); seen=set()\n    def dfs(r,c,i):\n        if i==len(word): return True\n        if not (0<=r<m and 0<=c<n) or (r,c) in seen or board[r][c]!=word[i]: return False\n        seen.add((r,c))\n        ok=any(dfs(r+dr,c+dc,i+1) for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))\n        seen.remove((r,c))\n        return ok\n    return any(dfs(r,c,0) for r in range(m) for c in range(n))","js":"function exist(board,word){\n  if(!word)return true;if(!board.length||!board[0].length)return false;\n  const m=board.length,n=board[0].length,seen=new Set();\n  function dfs(r,c,i){\n    if(i===word.length)return true;\n    const key=r*n+c;if(r<0||r>=m||c<0||c>=n||seen.has(key)||board[r][c]!==word[i])return false;\n    seen.add(key);const ok=[[1,0],[-1,0],[0,1],[0,-1]].some(([a,b])=>dfs(r+a,c+b,i+1));seen.delete(key);return ok;\n  }\n  for(let r=0;r<m;r++)for(let c=0;c<n;c++)if(dfs(r,c,0))return true;return false;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nbool exist(vector<vector<char>>& b,string w){\n  if(w.empty())return true;if(b.empty()||b[0].empty())return false;\n  int m=b.size(),n=b[0].size();vector<vector<bool>> used(m,vector<bool>(n));\n  function<bool(int,int,int)> dfs=[&](int r,int c,int i){\n    if(i==w.size())return true;\n    if(r<0||r>=m||c<0||c>=n||used[r][c]||b[r][c]!=w[i])return false;\n    used[r][c]=true;bool ok=dfs(r+1,c,i+1)||dfs(r-1,c,i+1)||dfs(r,c+1,i+1)||dfs(r,c-1,i+1);used[r][c]=false;return ok;\n  };\n  for(int r=0;r<m;r++)for(int c=0;c<n;c++)if(dfs(r,c,0))return true;return false;\n}","statement":"Check whether a word can be traced through four-directionally adjacent grid cells without reusing a cell.","example":"board = [[\"A\",\"B\"],[\"C\",\"D\"]], word = \"ABD\" → true"},"N Queens":{"idea":"Place exactly one queen in each row. Track occupied columns and both diagonal identifiers, row minus column and row plus column. Undo each placement before trying another column","steps":["Place exactly one queen in each row.","Track occupied columns and both diagonal identifiers, row minus column and row plus column.","Undo each placement before trying another column."],"time":"O(n! n) upper bound","space":"O(n^2) board plus output","python":"def solveNQueens(n):\n    out=[]; cols=set(); d1=set(); d2=set(); board=[['.']*n for _ in range(n)]\n    def dfs(r):\n        if r==n: out.append([''.join(row) for row in board]); return\n        for c in range(n):\n            if c in cols or r-c in d1 or r+c in d2: continue\n            cols.add(c); d1.add(r-c); d2.add(r+c); board[r][c]='Q'\n            dfs(r+1)\n            cols.remove(c); d1.remove(r-c); d2.remove(r+c); board[r][c]='.'\n    dfs(0)\n    return out","js":"function solveNQueens(n){\n  const out=[],cols=new Set(),d1=new Set(),d2=new Set(),b=Array.from({length:n},()=>Array(n).fill('.'));\n  function dfs(r){\n    if(r===n){out.push(b.map(row=>row.join('')));return;}\n    for(let c=0;c<n;c++){\n      if(cols.has(c)||d1.has(r-c)||d2.has(r+c))continue;\n      cols.add(c);d1.add(r-c);d2.add(r+c);b[r][c]='Q';dfs(r+1);\n      cols.delete(c);d1.delete(r-c);d2.delete(r+c);b[r][c]='.';\n    }\n  }dfs(0);return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<vector<string>> solveNQueens(int n){\n  vector<vector<string>> out;vector<string> b(n,string(n,'.'));set<int> cols,d1,d2;\n  function<void(int)> dfs=[&](int r){\n    if(r==n){out.push_back(b);return;}\n    for(int c=0;c<n;c++){\n      if(cols.count(c)||d1.count(r-c)||d2.count(r+c))continue;\n      cols.insert(c);d1.insert(r-c);d2.insert(r+c);b[r][c]='Q';dfs(r+1);\n      cols.erase(c);d1.erase(r-c);d2.erase(r+c);b[r][c]='.';\n    }\n  };dfs(0);return out;\n}","statement":"Place n queens on an n by n board so no two share a row, column, or diagonal. Return every board.","example":"n = 4 → 2 boards, including [\".Q..\",\"...Q\",\"Q...\",\"..Q.\"]"},"Two City Scheduling":{"idea":"Send everyone to city B as a baseline. Sort by the extra cost of choosing A instead of B. Assign the cheapest half of those differences to A; exactly 2n people are given","steps":["Send everyone to city B as a baseline.","Sort by the extra cost of choosing A instead of B.","Assign the cheapest half of those differences to A; exactly 2n people are given."],"time":"O(n log n)","space":"O(n) copy","python":"def twoCitySchedCost(costs):\n    a=sorted(costs,key=lambda p:p[0]-p[1]); n=len(a)//2\n    return sum(p[0] if i<n else p[1] for i,p in enumerate(a))","js":"function twoCitySchedCost(costs){\n  const a=[...costs].sort((p,q)=>(p[0]-p[1])-(q[0]-q[1])),n=a.length/2;\n  return a.reduce((sum,p,i)=>sum+p[i<n?0:1],0);\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint twoCitySchedCost(vector<vector<int>> costs){\n  sort(costs.begin(),costs.end(),[](auto& a,auto& b){return a[0]-a[1]<b[0]-b[1];});\n  int out=0,n=costs.size()/2;for(int i=0;i<costs.size();i++)out+=costs[i][i<n?0:1];return out;\n}","statement":"Send exactly half of 2n people to each city while minimizing total travel cost.","example":"costs = [[10,20],[30,200],[400,50],[30,20]] → 110"},"Assign Cookies":{"idea":"Sort children by greed and cookies by size. Give the smallest suitable cookie to the least demanding unsatisfied child. A smaller cookie cannot satisfy that child or any later child","steps":["Sort children by greed and cookies by size.","Give the smallest suitable cookie to the least demanding unsatisfied child.","A smaller cookie cannot satisfy that child or any later child."],"time":"O(g log g+s log s)","space":"O(g+s) copy","python":"def findContentChildren(g,s):\n    g=sorted(g); s=sorted(s); i=0\n    for x in s:\n        if i<len(g) and x>=g[i]: i+=1\n    return i","js":"function findContentChildren(g,s){\n  g=[...g].sort((a,b)=>a-b);s=[...s].sort((a,b)=>a-b);let i=0;\n  for(const x of s)if(i<g.length&&x>=g[i])i++;return i;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint findContentChildren(vector<int> g,vector<int> s){\n  sort(g.begin(),g.end());sort(s.begin(),s.end());int i=0;\n  for(int x:s)if(i<g.size()&&x>=g[i])i++;return i;\n}","statement":"Each child needs a minimum cookie size. Assign at most one cookie per child to maximize satisfied children.","example":"greed = [1,2,3], cookies = [1,1] → 1"},"Lemonade Change":{"idea":"Track counts of five-dollar and ten-dollar bills. For a twenty-dollar payment, prefer giving one ten and one five as change. Preserve five-dollar bills for future ten-dollar customers","steps":["Track counts of five-dollar and ten-dollar bills.","For a twenty-dollar payment, prefer giving one ten and one five as change.","Preserve five-dollar bills for future ten-dollar customers."],"time":"O(n)","space":"O(1)","python":"def lemonadeChange(bills):\n    five=ten=0\n    for b in bills:\n        if b==5: five+=1\n        elif b==10: five-=1; ten+=1\n        elif ten and five: ten-=1; five-=1\n        else: five-=3\n        if five<0: return False\n    return True","js":"function lemonadeChange(bills){\n  let five=0,ten=0;\n  for(const b of bills){\n    if(b===5)five++;else if(b===10){five--;ten++;}\n    else if(ten&&five){ten--;five--;}else five-=3;\n    if(five<0)return false;\n  }return true;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nbool lemonadeChange(vector<int>& bills){\n  int five=0,ten=0;for(int b:bills){\n    if(b==5)five++;else if(b==10){five--;ten++;}\n    else if(ten&&five){ten--;five--;}else five-=3;\n    if(five<0)return false;\n  }return true;\n}","statement":"Lemonade costs $5. Determine whether every $5, $10, or $20 payment can receive exact change in order.","example":"bills = [5,5,5,10,20] → true"},"Best Time to Buy and Sell Stock - II":{"idea":"Unlimited transactions let every positive day-to-day increase contribute to profit. Add each upward price difference. Consecutive upward differences telescope to the same profit as one longer trade","steps":["Unlimited transactions let every positive day-to-day increase contribute to profit.","Add each upward price difference.","Consecutive upward differences telescope to the same profit as one longer trade."],"time":"O(n)","space":"O(1)","python":"def maxProfit(prices):\n    return sum(max(0,prices[i]-prices[i-1]) for i in range(1,len(prices)))","js":"function maxProfit(prices){\n  let out=0;for(let i=1;i<prices.length;i++)out+=Math.max(0,prices[i]-prices[i-1]);return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint maxProfit(vector<int>& prices){\n  int out=0;for(int i=1;i<prices.size();i++)out+=max(0,prices[i]-prices[i-1]);return out;\n}","statement":"Maximize profit using unlimited stock transactions while holding at most one share at a time.","example":"prices = [7,1,5,3,6,4] → 7"},"Insert Interval":{"idea":"Given sorted nonoverlapping intervals, first copy intervals entirely before the new one. Merge every overlapping interval into its expanding endpoints. Append the merged interval and all remaining intervals","steps":["Given sorted nonoverlapping intervals, first copy intervals entirely before the new one.","Merge every overlapping interval into its expanding endpoints.","Append the merged interval and all remaining intervals."],"time":"O(n)","space":"O(n) output","python":"def insert(intervals,newInterval):\n    out=[]; i=0; lo,hi=newInterval\n    while i<len(intervals) and intervals[i][1]<lo: out.append(intervals[i][:]); i+=1\n    while i<len(intervals) and intervals[i][0]<=hi:\n        lo=min(lo,intervals[i][0]); hi=max(hi,intervals[i][1]); i+=1\n    return out+[[lo,hi]]+[p[:] for p in intervals[i:]]","js":"function insert(intervals,newInterval){\n  const out=[];let i=0,[lo,hi]=newInterval;\n  while(i<intervals.length&&intervals[i][1]<lo)out.push([...intervals[i++]]);\n  while(i<intervals.length&&intervals[i][0]<=hi){lo=Math.min(lo,intervals[i][0]);hi=Math.max(hi,intervals[i++][1]);}\n  return out.concat([[lo,hi]],intervals.slice(i).map(p=>[...p]));\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<vector<int>> insert(vector<vector<int>>& a,vector<int>& v){\n  vector<vector<int>> out;int i=0,lo=v[0],hi=v[1];\n  while(i<a.size()&&a[i][1]<lo)out.push_back(a[i++]);\n  while(i<a.size()&&a[i][0]<=hi){lo=min(lo,a[i][0]);hi=max(hi,a[i++][1]);}\n  out.push_back({lo,hi});while(i<a.size())out.push_back(a[i++]);return out;\n}","statement":"Insert an interval into a sorted nonoverlapping interval list, merging any overlaps.","example":"intervals = [[1,3],[6,9]], new = [2,5] → [[1,5],[6,9]]"},"Merge Intervals":{"idea":"Sort intervals by start. If the next start is at most the current merged end, extend that end. Otherwise begin a new merged interval","steps":["Sort intervals by start.","If the next start is at most the current merged end, extend that end.","Otherwise begin a new merged interval."],"time":"O(n log n)","space":"O(n)","python":"def merge(intervals):\n    out=[]\n    for lo,hi in sorted(intervals):\n        if out and lo<=out[-1][1]: out[-1][1]=max(out[-1][1],hi)\n        else: out.append([lo,hi])\n    return out","js":"function merge(intervals){\n  const a=intervals.map(p=>[...p]).sort((a,b)=>a[0]-b[0]),out=[];\n  for(const [lo,hi] of a){if(out.length&&lo<=out.at(-1)[1])out.at(-1)[1]=Math.max(out.at(-1)[1],hi);else out.push([lo,hi]);}\n  return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<vector<int>> merge(vector<vector<int>> a){\n  sort(a.begin(),a.end());vector<vector<int>> out;\n  for(auto p:a){if(!out.empty()&&p[0]<=out.back()[1])out.back()[1]=max(out.back()[1],p[1]);else out.push_back(p);}\n  return out;\n}","statement":"Merge all overlapping closed intervals.","example":"intervals = [[1,3],[2,6],[8,10],[15,18]] → [[1,6],[8,10],[15,18]]"},"Partition Labels":{"idea":"Record the last position of each character. Expand the current partition end to cover every character encountered. Close the partition when the scan reaches that end","steps":["Record the last position of each character.","Expand the current partition end to cover every character encountered.","Close the partition when the scan reaches that end."],"time":"O(n)","space":"O(alphabet)","python":"def partitionLabels(s):\n    last={c:i for i,c in enumerate(s)}; start=end=0; out=[]\n    for i,c in enumerate(s):\n        end=max(end,last[c])\n        if i==end: out.append(i-start+1); start=i+1\n    return out","js":"function partitionLabels(s){\n  const last=new Map(),out=[];for(let i=0;i<s.length;i++)last.set(s[i],i);\n  let start=0,end=0;for(let i=0;i<s.length;i++){end=Math.max(end,last.get(s[i]));if(i===end){out.push(i-start+1);start=i+1;}}\n  return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<int> partitionLabels(string s){\n  unordered_map<char,int> last;for(int i=0;i<s.size();i++)last[s[i]]=i;\n  vector<int> out;int start=0,end=0;for(int i=0;i<s.size();i++){end=max(end,last[s[i]]);if(i==end){out.push_back(i-start+1);start=i+1;}}\n  return out;\n}","statement":"Split a string into as many segments as possible so each character appears in only one segment. Return lengths.","example":"s = \"ababcbacadefegdehijhklij\" → [9,7,8]"},"Non Overlapping Intervals":{"idea":"Sort intervals by finishing time. Keep the earliest-ending compatible interval to leave maximum room for future choices. Count every interval whose start is before the last kept end as a removal","steps":["Sort intervals by finishing time.","Keep the earliest-ending compatible interval to leave maximum room for future choices.","Count every interval whose start is before the last kept end as a removal."],"time":"O(n log n)","space":"O(n) copy","python":"def eraseOverlapIntervals(intervals):\n    end=float('-inf'); removed=0\n    for lo,hi in sorted(intervals,key=lambda p:p[1]):\n        if lo<end: removed+=1\n        else: end=hi\n    return removed","js":"function eraseOverlapIntervals(intervals){\n  let end=-Infinity,removed=0;\n  for(const [lo,hi] of [...intervals].sort((a,b)=>a[1]-b[1])){if(lo<end)removed++;else end=hi;}\n  return removed;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint eraseOverlapIntervals(vector<vector<int>> a){\n  sort(a.begin(),a.end(),[](auto& x,auto& y){return x[1]<y[1];});\n  long long end=LLONG_MIN;int removed=0;for(auto p:a){if(p[0]<end)removed++;else end=p[1];}return removed;\n}","statement":"Remove the fewest intervals to leave a nonoverlapping set; touching endpoints are allowed.","example":"intervals = [[1,2],[2,3],[3,4],[1,3]] → 1"},"Task Scheduler":{"idea":"The most frequent tasks form the frame of any schedule. Separate their repeated occurrences by n cooldown slots. The answer is the larger of total task count and the frame length including ties for maximum frequency","steps":["The most frequent tasks form the frame of any schedule.","Separate their repeated occurrences by n cooldown slots.","The answer is the larger of total task count and the frame length including ties for maximum frequency."],"time":"O(tasks+alphabet)","space":"O(alphabet)","python":"from collections import Counter\ndef leastInterval(tasks,n):\n    if not tasks: return 0\n    counts=list(Counter(tasks).values()); f=max(counts); ties=counts.count(f)\n    return max(len(tasks),(f-1)*(n+1)+ties)","js":"function leastInterval(tasks,n){\n  if(!tasks.length)return 0;const c=new Map();for(const t of tasks)c.set(t,(c.get(t)||0)+1);\n  const values=[...c.values()],f=Math.max(...values),ties=values.filter(x=>x===f).length;\n  return Math.max(tasks.length,(f-1)*(n+1)+ties);\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint leastInterval(vector<char>& tasks,int n){\n  if(tasks.empty())return 0;unordered_map<char,int> c;for(char t:tasks)c[t]++;\n  int f=0,ties=0;for(auto entry:c)f=max(f,entry.second);for(auto entry:c)ties+=entry.second==f;\n  return max((int)tasks.size(),(f-1)*(n+1)+ties);\n}","statement":"Find the least CPU intervals needed when equal task labels must be separated by n idle or other-task intervals.","example":"tasks = [\"A\",\"A\",\"A\",\"B\",\"B\",\"B\"], n = 2 → 8"},"Gas Station":{"idea":"Accumulate total surplus to test whether a full circuit is possible. If the running tank becomes negative, no station in that failed segment can be a valid start. Restart immediately after it","steps":["Accumulate total surplus to test whether a full circuit is possible.","If the running tank becomes negative, no station in that failed segment can be a valid start.","Restart immediately after it."],"time":"O(n)","space":"O(1)","python":"def canCompleteCircuit(gas,cost):\n    total=tank=start=0\n    for i,(g,c) in enumerate(zip(gas,cost)):\n        total+=g-c; tank+=g-c\n        if tank<0: start=i+1; tank=0\n    return start if total>=0 and gas else -1","js":"function canCompleteCircuit(gas,cost){\n  let total=0,tank=0,start=0;\n  for(let i=0;i<gas.length;i++){const d=gas[i]-cost[i];total+=d;tank+=d;if(tank<0){start=i+1;tank=0;}}\n  return total>=0&&gas.length?start:-1;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint canCompleteCircuit(vector<int>& gas,vector<int>& cost){\n  long long total=0,tank=0;int start=0;for(int i=0;i<gas.size();i++){int d=gas[i]-cost[i];total+=d;tank+=d;if(tank<0){start=i+1;tank=0;}}\n  return total>=0&&!gas.empty()?start:-1;\n}","statement":"Find a starting station from which a car with an initially empty tank can complete the circular route, or -1.","example":"gas = [1,2,3,4,5], cost = [3,4,5,1,2] → 3"},"Car Pooling":{"idea":"Create positive passenger changes at pickups and negative changes at dropoffs. Combine changes at the same location so dropoffs free space before pickups there. Scan locations in order and reject any capacity overflow","steps":["Create positive passenger changes at pickups and negative changes at dropoffs.","Combine changes at the same location so dropoffs free space before pickups there.","Scan locations in order and reject any capacity overflow."],"time":"O(n log n)","space":"O(n)","python":"from collections import defaultdict\ndef carPooling(trips,capacity):\n    events=defaultdict(int)\n    for p,a,b in trips: events[a]+=p; events[b]-=p\n    load=0\n    for x in sorted(events):\n        load+=events[x]\n        if load>capacity: return False\n    return True","js":"function carPooling(trips,capacity){\n  const events=new Map();for(const [p,a,b] of trips){events.set(a,(events.get(a)||0)+p);events.set(b,(events.get(b)||0)-p);}\n  let load=0;for(const [x,d] of [...events].sort((a,b)=>a[0]-b[0])){load+=d;if(load>capacity)return false;}return true;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nbool carPooling(vector<vector<int>>& trips,int capacity){\n  map<int,int> events;for(auto t:trips){events[t[1]]+=t[0];events[t[2]]-=t[0];}\n  int load=0;for(auto entry:events){load+=entry.second;if(load>capacity)return false;}return true;\n}","statement":"Given passenger counts, pickup points, and dropoff points, determine whether a car ever exceeds capacity.","example":"trips = [[2,1,5],[3,3,7]], capacity = 4 → false"},"Candy":{"idea":"Give everyone one candy initially. Scan left-to-right to satisfy increasing ratings relative to the left neighbor. Scan right-to-left and take the maximum needed to also satisfy the right neighbor","steps":["Give everyone one candy initially.","Scan left-to-right to satisfy increasing ratings relative to the left neighbor.","Scan right-to-left and take the maximum needed to also satisfy the right neighbor."],"time":"O(n)","space":"O(n)","python":"def candy(ratings):\n    c=[1]*len(ratings)\n    for i in range(1,len(c)):\n        if ratings[i]>ratings[i-1]: c[i]=c[i-1]+1\n    for i in range(len(c)-2,-1,-1):\n        if ratings[i]>ratings[i+1]: c[i]=max(c[i],c[i+1]+1)\n    return sum(c)","js":"function candy(ratings){\n  const c=Array(ratings.length).fill(1);\n  for(let i=1;i<c.length;i++)if(ratings[i]>ratings[i-1])c[i]=c[i-1]+1;\n  for(let i=c.length-2;i>=0;i--)if(ratings[i]>ratings[i+1])c[i]=Math.max(c[i],c[i+1]+1);\n  return c.reduce((a,b)=>a+b,0);\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint candy(vector<int>& r){\n  vector<int> c(r.size(),1);for(int i=1;i<r.size();i++)if(r[i]>r[i-1])c[i]=c[i-1]+1;\n  for(int i=(int)r.size()-2;i>=0;i--)if(r[i]>r[i+1])c[i]=max(c[i],c[i+1]+1);\n  return accumulate(c.begin(),c.end(),0);\n}","statement":"Give each child at least one candy and every higher-rated neighbor more candies. Minimize the total.","example":"ratings = [1,0,2] → 5"},"Climbing Stairs":{"idea":"A route to step i ends with a jump from i minus one or i minus two. Add those two counts. Keep only the previous two values; the empty route gives one way to climb zero steps","steps":["A route to step i ends with a jump from i minus one or i minus two.","Add those two counts.","Keep only the previous two values; the empty route gives one way to climb zero steps."],"time":"O(n)","space":"O(1)","python":"def climbStairs(n):\n    a=b=1\n    for _ in range(n): a,b=b,a+b\n    return a","js":"function climbStairs(n){let a=1,b=1;for(let i=0;i<n;i++)[a,b]=[b,a+b];return a;}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint climbStairs(int n){long long a=1,b=1;while(n--){long long next=a+b;a=b;b=next;}return a;}","statement":"Count the distinct ways to climb n steps using jumps of one or two steps.","example":"n = 4 → 5"},"Minimum Cost Climbing Stairs":{"idea":"The top can be reached from either of the preceding two steps. Add the cost paid at each candidate predecessor and keep the cheaper route. Starting at step zero or one costs nothing before landing","steps":["The top can be reached from either of the preceding two steps.","Add the cost paid at each candidate predecessor and keep the cheaper route.","Starting at step zero or one costs nothing before landing."],"time":"O(n)","space":"O(1)","python":"def minCostClimbingStairs(cost):\n    a=b=0\n    for i in range(2,len(cost)+1): a,b=b,min(b+cost[i-1],a+cost[i-2])\n    return b","js":"function minCostClimbingStairs(cost){let a=0,b=0;for(let i=2;i<=cost.length;i++)[a,b]=[b,Math.min(b+cost[i-1],a+cost[i-2])];return b;}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint minCostClimbingStairs(vector<int>& cost){int a=0,b=0;for(int i=2;i<=cost.size();i++){int next=min(b+cost[i-1],a+cost[i-2]);a=b;b=next;}return b;}","statement":"Pay a step’s cost when leaving it; start at step 0 or 1 and minimize cost to reach the top.","example":"cost = [10,15,20] → 15"},"House Robber":{"idea":"At each house choose between skipping it and taking its value plus the best total from two houses earlier. Update the two previous optimum totals. Adjacent houses are never selected together","steps":["At each house choose between skipping it and taking its value plus the best total from two houses earlier.","Update the two previous optimum totals.","Adjacent houses are never selected together."],"time":"O(n)","space":"O(1)","python":"def rob(nums):\n    a=b=0\n    for x in nums: a,b=b,max(b,a+x)\n    return b","js":"function rob(nums){let a=0,b=0;for(const x of nums)[a,b]=[b,Math.max(b,a+x)];return b;}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint rob(vector<int>& nums){int a=0,b=0;for(int x:nums){int next=max(b,a+x);a=b;b=next;}return b;}","statement":"Choose nonadjacent houses in a line to maximize the total money robbed.","example":"nums = [2,7,9,3,1] → 12"},"House Robber II":{"idea":"The first and last houses are adjacent in a circle. Solve two linear cases, excluding the first house or excluding the last. Take the larger result and handle a single house separately","steps":["The first and last houses are adjacent in a circle.","Solve two linear cases, excluding the first house or excluding the last.","Take the larger result and handle a single house separately."],"time":"O(n)","space":"O(1)","python":"def rob(nums):\n    if len(nums)==1: return nums[0]\n    def linear(lo,hi):\n        a=b=0\n        for i in range(lo,hi): a,b=b,max(b,a+nums[i])\n        return b\n    return max(linear(0,len(nums)-1),linear(1,len(nums)))","js":"function rob(nums){\n  if(nums.length===1)return nums[0];\n  function linear(lo,hi){let a=0,b=0;for(let i=lo;i<hi;i++)[a,b]=[b,Math.max(b,a+nums[i])];return b;}\n  return Math.max(linear(0,nums.length-1),linear(1,nums.length));\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint rob(vector<int>& nums){\n  if(nums.size()==1)return nums[0];\n  auto linear=[&](int lo,int hi){int a=0,b=0;for(int i=lo;i<hi;i++){int next=max(b,a+nums[i]);a=b;b=next;}return b;};\n  return max(linear(0,(int)nums.size()-1),linear(1,nums.size()));\n}","statement":"Choose nonadjacent houses arranged in a circle to maximize money; first and last are neighbors.","example":"nums = [2,3,2] → 3"},"Coin Change":{"idea":"Let dp[x] be the fewest coins making amount x. For every positive coin not exceeding x, try adding it to the best solution for x minus that coin. An unreachable target returns minus one","steps":["Let dp[x] be the fewest coins making amount x.","For every positive coin not exceeding x, try adding it to the best solution for x minus that coin.","An unreachable target returns minus one."],"time":"O(amount coins)","space":"O(amount)","python":"def coinChange(coins,amount):\n    dp=[amount+1]*(amount+1); dp[0]=0\n    for x in range(1,amount+1):\n        for c in coins:\n            if 0<c<=x: dp[x]=min(dp[x],dp[x-c]+1)\n    return dp[amount] if dp[amount]<=amount else -1","js":"function coinChange(coins,amount){\n  const dp=Array(amount+1).fill(amount+1);dp[0]=0;\n  for(let x=1;x<=amount;x++)for(const c of coins)if(c>0&&c<=x)dp[x]=Math.min(dp[x],dp[x-c]+1);\n  return dp[amount]<=amount?dp[amount]:-1;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint coinChange(vector<int>& coins,int amount){\n  vector<int> dp(amount+1,amount+1);dp[0]=0;\n  for(int x=1;x<=amount;x++)for(int c:coins)if(c>0&&c<=x)dp[x]=min(dp[x],dp[x-c]+1);\n  return dp[amount]<=amount?dp[amount]:-1;\n}","statement":"Return the fewest positive-denomination coins making the amount, allowing unlimited reuse; return -1 if impossible.","example":"coins = [1,2,5], amount = 11 → 3"},"Palindromic Substrings":{"idea":"Every palindrome has either one center character or a gap between two center characters. Expand from each of these centers while characters match. Count each successful expansion as one palindromic substring","steps":["Every palindrome has either one center character or a gap between two center characters.","Expand from each of these centers while characters match.","Count each successful expansion as one palindromic substring."],"time":"O(n^2)","space":"O(1)","python":"def countSubstrings(s):\n    count=0\n    for center in range(2*len(s)-1):\n        l=center//2; r=l+center%2\n        while l>=0 and r<len(s) and s[l]==s[r]: count+=1; l-=1; r+=1\n    return count","js":"function countSubstrings(s){\n  let count=0;for(let c=0;c<2*s.length-1;c++){let l=Math.floor(c/2),r=l+c%2;while(l>=0&&r<s.length&&s[l]===s[r]){count++;l--;r++;}}return count;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint countSubstrings(string s){\n  int count=0;for(int c=0;c<2*(int)s.size()-1;c++){int l=c/2,r=l+c%2;while(l>=0&&r<s.size()&&s[l]==s[r]){count++;l--;r++;}}return count;\n}","statement":"Count palindromic substring occurrences, including repeated equal substrings at different positions.","example":"s = \"aaa\" → 6"},"Longest Palindromic Substring":{"idea":"Expand around each character and each gap between characters. Track the longest successful expansion rather than counting them. Return the corresponding substring after all centers have been tried","steps":["Expand around each character and each gap between characters.","Track the longest successful expansion rather than counting them.","Return the corresponding substring after all centers have been tried."],"time":"O(n^2)","space":"O(1) auxiliary","python":"def longestPalindrome(s):\n    start=length=0\n    for c in range(2*len(s)-1):\n        l=c//2; r=l+c%2\n        while l>=0 and r<len(s) and s[l]==s[r]:\n            if r-l+1>length: start,length=l,r-l+1\n            l-=1; r+=1\n    return s[start:start+length]","js":"function longestPalindrome(s){\n  let start=0,len=0;for(let c=0;c<2*s.length-1;c++){let l=Math.floor(c/2),r=l+c%2;\n    while(l>=0&&r<s.length&&s[l]===s[r]){if(r-l+1>len){start=l;len=r-l+1;}l--;r++;}}\n  return s.slice(start,start+len);\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nstring longestPalindrome(string s){\n  int start=0,len=0;for(int c=0;c<2*(int)s.size()-1;c++){int l=c/2,r=l+c%2;\n    while(l>=0&&r<s.size()&&s[l]==s[r]){if(r-l+1>len){start=l;len=r-l+1;}l--;r++;}}\n  return s.substr(start,len);\n}","statement":"Return any longest contiguous palindromic substring.","example":"s = \"babad\" → \"bab\" (\"aba\" is also valid)"},"Decode Ways":{"idea":"A nonzero final digit may be decoded on its own. A final pair between 10 and 26 may be decoded together. Sum the valid predecessor counts and reject leading or isolated zeros","steps":["A nonzero final digit may be decoded on its own.","A final pair between 10 and 26 may be decoded together.","Sum the valid predecessor counts and reject leading or isolated zeros."],"time":"O(n)","space":"O(1)","python":"def numDecodings(s):\n    if not s: return 0\n    a,b=1,int(s[0]!='0')\n    for i in range(1,len(s)):\n        c=(b if s[i]!='0' else 0)+(a if 10<=int(s[i-1:i+1])<=26 else 0)\n        a,b=b,c\n    return b","js":"function numDecodings(s){\n  if(!s)return 0;let a=1,b=Number(s[0]!=='0');\n  for(let i=1;i<s.length;i++){const pair=Number(s.slice(i-1,i+1)),c=(s[i]!=='0'?b:0)+(pair>=10&&pair<=26?a:0);a=b;b=c;}\n  return b;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint numDecodings(string s){\n  if(s.empty())return 0;long long a=1,b=s[0]!='0';\n  for(int i=1;i<s.size();i++){int pair=(s[i-1]-'0')*10+s[i]-'0';long long c=(s[i]!='0'?b:0)+(pair>=10&&pair<=26?a:0);a=b;b=c;}return b;\n}","statement":"Count ways to decode a digit string using 1=A through 26=Z; leading zeros cannot form a letter.","example":"s = \"226\" → 3"},"Maximum Subarray":{"idea":"Track the best subarray ending at the current position. Either extend the previous subarray or start fresh at the current value. Update a global best, initialized to the first value for all-negative input","steps":["Track the best subarray ending at the current position.","Either extend the previous subarray or start fresh at the current value.","Update a global best, initialized to the first value for all-negative input."],"time":"O(n)","space":"O(1)","python":"def maxSubArray(nums):\n    best=current=nums[0]\n    for x in nums[1:]: current=max(x,current+x); best=max(best,current)\n    return best","js":"function maxSubArray(nums){let best=nums[0],current=nums[0];for(let i=1;i<nums.length;i++){current=Math.max(nums[i],current+nums[i]);best=Math.max(best,current);}return best;}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint maxSubArray(vector<int>& nums){int best=nums[0],current=nums[0];for(int i=1;i<nums.size();i++){current=max(nums[i],current+nums[i]);best=max(best,current);}return best;}","statement":"Return the largest sum of any nonempty contiguous subarray.","example":"nums = [-2,1,-3,4,-1,2,1,-5,4] → 6"},"Maximum Product Subarray":{"idea":"A negative value can turn the smallest product into the largest. Track both maximum and minimum products ending at each position. Consider starting fresh, extending the maximum, and extending the minimum","steps":["A negative value can turn the smallest product into the largest.","Track both maximum and minimum products ending at each position.","Consider starting fresh, extending the maximum, and extending the minimum."],"time":"O(n)","space":"O(1)","python":"def maxProduct(nums):\n    hi=lo=best=nums[0]\n    for x in nums[1:]:\n        hi,lo=max(x,x*hi,x*lo),min(x,x*hi,x*lo)\n        best=max(best,hi)\n    return best","js":"function maxProduct(nums){let hi=nums[0],lo=nums[0],best=nums[0];for(let i=1;i<nums.length;i++){const x=nums[i];[hi,lo]=[Math.max(x,x*hi,x*lo),Math.min(x,x*hi,x*lo)];best=Math.max(best,hi);}return best;}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint maxProduct(vector<int>& nums){long long hi=nums[0],lo=nums[0],best=nums[0];for(int i=1;i<nums.size();i++){long long x=nums[i],a=max({x,x*hi,x*lo}),b=min({x,x*hi,x*lo});hi=a;lo=b;best=max(best,hi);}return best;}","statement":"Return the largest product of any nonempty contiguous subarray.","example":"nums = [2,3,-2,4] → 6"},"Word Break":{"idea":"Let dp[i] mean the prefix ending before i can be segmented. For each ending position, try a dictionary word that fits there and has a reachable predecessor. The empty prefix is reachable","steps":["Let dp[i] mean the prefix ending before i can be segmented.","For each ending position, try a dictionary word that fits there and has a reachable predecessor.","The empty prefix is reachable."],"time":"O(n words maxWordLength)","space":"O(n+dictionary)","python":"def wordBreak(s,wordDict):\n    words=set(wordDict); dp=[False]*(len(s)+1); dp[0]=True\n    for i in range(1,len(s)+1):\n        dp[i]=any(len(w)<=i and dp[i-len(w)] and s[i-len(w):i]==w for w in words)\n    return dp[-1]","js":"function wordBreak(s,wordDict){\n  const words=[...new Set(wordDict)],dp=Array(s.length+1).fill(false);dp[0]=true;\n  for(let i=1;i<=s.length;i++)dp[i]=words.some(w=>w.length<=i&&dp[i-w.length]&&s.slice(i-w.length,i)===w);\n  return dp[s.length];\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nbool wordBreak(string s,vector<string>& words){\n  vector<bool> dp(s.size()+1);dp[0]=true;\n  for(int i=1;i<=s.size();i++)for(auto& w:words)if(w.size()<=i&&dp[i-w.size()]&&s.compare(i-w.size(),w.size(),w)==0){dp[i]=true;break;}\n  return dp[s.size()];\n}","statement":"Determine whether a string can be segmented into dictionary words, allowing word reuse.","example":"s = \"leetcode\", words = [\"leet\",\"code\"] → true"},"Longest Increasing Subsequence":{"idea":"Maintain the smallest possible ending value for each subsequence length. Replace the first tail greater than or equal to the current value using binary search. The number of tails is the longest strictly increasing subsequence length","steps":["Maintain the smallest possible ending value for each subsequence length.","Replace the first tail greater than or equal to the current value using binary search.","The number of tails is the longest strictly increasing subsequence length."],"time":"O(n log n)","space":"O(n)","python":"from bisect import bisect_left\ndef lengthOfLIS(nums):\n    tails=[]\n    for x in nums:\n        i=bisect_left(tails,x)\n        if i==len(tails): tails.append(x)\n        else: tails[i]=x\n    return len(tails)","js":"function lengthOfLIS(nums){\n  const tails=[];for(const x of nums){let l=0,r=tails.length;while(l<r){const m=(l+r)>>1;if(tails[m]<x)l=m+1;else r=m;}tails[l]=x;}return tails.length;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint lengthOfLIS(vector<int>& nums){\n  vector<int> tails;for(int x:nums){auto it=lower_bound(tails.begin(),tails.end(),x);if(it==tails.end())tails.push_back(x);else *it=x;}return tails.size();\n}","statement":"Return the length of the longest strictly increasing subsequence; chosen positions need not be adjacent.","example":"nums = [10,9,2,5,3,7,101,18] → 4"},"Partition Equal Subset Sum":{"idea":"Equal partitions require an even total. Solve a subset-sum problem for half that total. Iterate sums downward for each nonnegative number so each input position is used at most once","steps":["Equal partitions require an even total.","Solve a subset-sum problem for half that total.","Iterate sums downward for each nonnegative number so each input position is used at most once."],"time":"O(n total)","space":"O(total)","python":"def canPartition(nums):\n    total=sum(nums)\n    if total%2: return False\n    target=total//2; dp=[False]*(target+1); dp[0]=True\n    for x in nums:\n        for s in range(target,x-1,-1): dp[s]=dp[s] or dp[s-x]\n    return dp[target]","js":"function canPartition(nums){\n  const total=nums.reduce((a,b)=>a+b,0);if(total%2)return false;\n  const target=total/2,dp=Array(target+1).fill(false);dp[0]=true;\n  for(const x of nums)for(let s=target;s>=x;s--)dp[s]=dp[s]||dp[s-x];return dp[target];\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nbool canPartition(vector<int>& nums){\n  int total=accumulate(nums.begin(),nums.end(),0);if(total%2)return false;\n  int target=total/2;vector<bool> dp(target+1);dp[0]=true;\n  for(int x:nums)for(int s=target;s>=x;s--)dp[s]=dp[s]||dp[s-x];return dp[target];\n}","statement":"Determine whether nonnegative values can be partitioned into two groups of equal sum.","example":"nums = [1,5,11,5] → true"},"Coin Change II":{"idea":"Let dp[x] count unordered combinations making x. Process one coin denomination at a time, scanning amounts upward to permit reuse. Keeping coins outside the amount loop avoids counting different orders separately","steps":["Let dp[x] count unordered combinations making x.","Process one coin denomination at a time, scanning amounts upward to permit reuse.","Keeping coins outside the amount loop avoids counting different orders separately."],"time":"O(amount coins)","space":"O(amount)","python":"def change(amount,coins):\n    dp=[0]*(amount+1); dp[0]=1\n    for c in sorted(set(coins)):\n        for x in range(c,amount+1): dp[x]+=dp[x-c]\n    return dp[amount]","js":"function change(amount,coins){\n  const dp=Array(amount+1).fill(0);dp[0]=1;\n  for(const c of new Set(coins))for(let x=c;x<=amount;x++)dp[x]+=dp[x-c];return dp[amount];\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint change(int amount,vector<int> coins){\n  sort(coins.begin(),coins.end());coins.erase(unique(coins.begin(),coins.end()),coins.end());\n  vector<unsigned long long> dp(amount+1);dp[0]=1;for(int c:coins)for(int x=c;x<=amount;x++)dp[x]+=dp[x-c];return dp[amount];\n}","statement":"Count unordered combinations of positive coin denominations totaling amount, with unlimited reuse.","example":"amount = 5, coins = [1,2,5] → 4"},"Unique Paths":{"idea":"A cell is reached either from above or from its left. Store one row of counts and update left-to-right for each later row. The top row and left column each have one path","steps":["A cell is reached either from above or from its left.","Store one row of counts and update left-to-right for each later row.","The top row and left column each have one path."],"time":"O(mn)","space":"O(n)","python":"def uniquePaths(m,n):\n    if m<=0 or n<=0: return 0\n    dp=[1]*n\n    for _ in range(1,m):\n        for c in range(1,n): dp[c]+=dp[c-1]\n    return dp[-1]","js":"function uniquePaths(m,n){if(m<=0||n<=0)return 0;const dp=Array(n).fill(1);for(let r=1;r<m;r++)for(let c=1;c<n;c++)dp[c]+=dp[c-1];return dp[n-1];}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint uniquePaths(int m,int n){if(m<=0||n<=0)return 0;vector<long long> dp(n,1);for(int r=1;r<m;r++)for(int c=1;c<n;c++)dp[c]+=dp[c-1];return dp.back();}","statement":"Count routes from the top-left to bottom-right of an m by n grid, moving only right or down.","example":"m = 3, n = 7 → 28"},"Jump Game":{"idea":"Maintain the furthest reachable index. If the scan reaches an index beyond that frontier, no route can reach it. Otherwise extend the frontier with the current jump length","steps":["Maintain the furthest reachable index.","If the scan reaches an index beyond that frontier, no route can reach it.","Otherwise extend the frontier with the current jump length."],"time":"O(n)","space":"O(1)","python":"def canJump(nums):\n    reach=0\n    for i,x in enumerate(nums):\n        if i>reach: return False\n        reach=max(reach,i+x)\n    return True","js":"function canJump(nums){let reach=0;for(let i=0;i<nums.length;i++){if(i>reach)return false;reach=Math.max(reach,i+nums[i]);}return true;}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nbool canJump(vector<int>& nums){int reach=0;for(int i=0;i<nums.size();i++){if(i>reach)return false;reach=max(reach,i+nums[i]);}return true;}","statement":"Each nonnegative value is the maximum jump length at its position. Check whether the last index is reachable from index 0.","example":"nums = [2,3,1,1,4] → true"},"Jump Game II":{"idea":"Treat all indices reachable with the same number of jumps as a breadth-first layer. Scan the current layer to find the next furthest frontier. Increase the jump count at each layer boundary; return minus one when no progress is possible","steps":["Treat all indices reachable with the same number of jumps as a breadth-first layer.","Scan the current layer to find the next furthest frontier.","Increase the jump count at each layer boundary; return minus one when no progress is possible."],"time":"O(n)","space":"O(1)","python":"def jump(nums):\n    end=far=jumps=0\n    for i in range(len(nums)-1):\n        far=max(far,i+nums[i])\n        if i==end:\n            if far==end: return -1\n            jumps+=1; end=far\n    return jumps","js":"function jump(nums){let end=0,far=0,jumps=0;for(let i=0;i<nums.length-1;i++){far=Math.max(far,i+nums[i]);if(i===end){if(far===end)return -1;jumps++;end=far;}}return jumps;}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint jump(vector<int>& nums){int end=0,far=0,jumps=0;for(int i=0;i<(int)nums.size()-1;i++){far=max(far,i+nums[i]);if(i==end){if(far==end)return -1;jumps++;end=far;}}return jumps;}","statement":"Return the minimum jumps from the first index to the last; return -1 if unreachable.","example":"nums = [2,3,1,1,4] → 2"},"Minimum Cost to Cut a Stick":{"idea":"Sort cut positions and include both stick endpoints. For each interval choose its first cut, paying the interval length plus the two remaining subproblems. Fill smaller intervals before larger ones","steps":["Sort cut positions and include both stick endpoints.","For each interval choose its first cut, paying the interval length plus the two remaining subproblems.","Fill smaller intervals before larger ones."],"time":"O(c^3)","space":"O(c^2)","python":"def minCost(n,cuts):\n    a=[0]+sorted(cuts)+[n]; m=len(a); dp=[[0]*m for _ in range(m)]\n    for gap in range(2,m):\n        for l in range(m-gap):\n            r=l+gap\n            dp[l][r]=a[r]-a[l]+min(dp[l][k]+dp[k][r] for k in range(l+1,r))\n    return dp[0][-1]","js":"function minCost(n,cuts){\n  const a=[0,...[...cuts].sort((a,b)=>a-b),n],m=a.length,dp=Array.from({length:m},()=>Array(m).fill(0));\n  for(let gap=2;gap<m;gap++)for(let l=0;l+gap<m;l++){const r=l+gap;dp[l][r]=Infinity;for(let k=l+1;k<r;k++)dp[l][r]=Math.min(dp[l][r],a[r]-a[l]+dp[l][k]+dp[k][r]);}\n  return dp[0][m-1];\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint minCost(int n,vector<int> cuts){\n  sort(cuts.begin(),cuts.end());cuts.insert(cuts.begin(),0);cuts.push_back(n);int m=cuts.size();vector<vector<int>> dp(m,vector<int>(m));\n  for(int gap=2;gap<m;gap++)for(int l=0;l+gap<m;l++){int r=l+gap;dp[l][r]=INT_MAX;for(int k=l+1;k<r;k++)dp[l][r]=min(dp[l][r],cuts[r]-cuts[l]+dp[l][k]+dp[k][r]);}return dp[0][m-1];\n}","statement":"Cut a stick at every required position. Each cut costs the length of its current piece; minimize total cost.","example":"n = 7, cuts = [1,3,4,5] → 16"},"Super Egg Drop":{"idea":"Invert the question: count floors distinguishable with a fixed number of moves and eggs. A drop covers the broken-egg region, the surviving-egg region, and the tested floor. Increase moves until the coverage reaches n","steps":["Invert the question: count floors distinguishable with a fixed number of moves and eggs.","A drop covers the broken-egg region, the surviving-egg region, and the tested floor.","Increase moves until the coverage reaches n."],"time":"O(k moves)","space":"O(k)","python":"def superEggDrop(k,n):\n    if n==0: return 0\n    if k<=0: return -1\n    dp=[0]*(k+1); moves=0\n    while dp[k]<n:\n        moves+=1\n        for e in range(k,0,-1): dp[e]=min(n,dp[e]+dp[e-1]+1)\n    return moves","js":"function superEggDrop(k,n){if(!n)return 0;if(k<=0)return -1;const dp=Array(k+1).fill(0);let moves=0;while(dp[k]<n){moves++;for(let e=k;e>0;e--)dp[e]=Math.min(n,dp[e]+dp[e-1]+1);}return moves;}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint superEggDrop(int k,int n){if(n==0)return 0;if(k<=0)return -1;vector<long long> dp(k+1);int moves=0;while(dp[k]<n){moves++;for(int e=k;e>0;e--)dp[e]=min((long long)n,dp[e]+dp[e-1]+1);}return moves;}","statement":"Find the fewest worst-case drops to identify the highest safe floor among n floors using k reusable-until-broken eggs.","example":"k = 2, n = 6 → 3"},"Clone Graph":{"idea":"Map each original node identity to its clone. Create the clone before exploring neighbors so cycles terminate. Recursively copy every edge using the mapped clones; Node supplies val and neighbors","steps":["Map each original node identity to its clone.","Create the clone before exploring neighbors so cycles terminate.","Recursively copy every edge using the mapped clones; Node supplies val and neighbors."],"time":"O(V+E)","space":"O(V)","python":"def cloneGraph(node):\n    clones={}\n    def clone(n):\n        if n is None: return None\n        if n in clones: return clones[n]\n        copy=Node(n.val); clones[n]=copy\n        copy.neighbors=[clone(v) for v in n.neighbors]\n        return copy\n    return clone(node)","js":"function cloneGraph(node){\n  const clones=new Map();\n  function clone(n){\n    if(!n)return null;if(clones.has(n))return clones.get(n);\n    const copy=new Node(n.val);clones.set(n,copy);copy.neighbors=n.neighbors.map(clone);return copy;\n  }\n  return clone(node);\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nNode* cloneGraph(Node* node){\n  unordered_map<Node*,Node*> copies;\n  function<Node*(Node*)> clone=[&](Node* n)->Node*{\n    if(!n)return nullptr;if(copies.count(n))return copies[n];\n    Node* copy=new Node(n->val);copies[n]=copy;\n    for(Node* v:n->neighbors)copy->neighbors.push_back(clone(v));return copy;\n  };return clone(node);\n}","statement":"Deep-copy an undirected graph reachable from the given node, preserving values and neighbor relationships.","example":"adjacency = [[2,4],[1,3],[2,4],[1,3]] → same adjacency with all new node identities"},"Find if Path Exists in Graph":{"idea":"Build an undirected adjacency list. Traverse from the source while marking each vertex once. The destination is reachable exactly when it is visited","steps":["Build an undirected adjacency list.","Traverse from the source while marking each vertex once.","The destination is reachable exactly when it is visited."],"time":"O(V+E)","space":"O(V+E)","python":"def validPath(n,edges,source,destination):\n    adj=[[] for _ in range(n)]\n    for a,b in edges: adj[a].append(b); adj[b].append(a)\n    seen={source}; stack=[source]\n    while stack:\n        u=stack.pop()\n        if u==destination: return True\n        for v in adj[u]:\n            if v not in seen: seen.add(v); stack.append(v)\n    return False","js":"function validPath(n,edges,source,destination){\n  const adj=Array.from({length:n},()=>[]);for(const [a,b] of edges){adj[a].push(b);adj[b].push(a);}\n  const seen=new Set([source]),stack=[source];while(stack.length){const u=stack.pop();if(u===destination)return true;\n    for(const v of adj[u])if(!seen.has(v)){seen.add(v);stack.push(v);}}\n  return false;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nbool validPath(int n,vector<vector<int>>& edges,int source,int destination){\n  vector<vector<int>> adj(n);for(auto e:edges){adj[e[0]].push_back(e[1]);adj[e[1]].push_back(e[0]);}\n  vector<bool> seen(n);seen[source]=true;stack<int> st;st.push(source);\n  while(!st.empty()){int u=st.top();st.pop();if(u==destination)return true;for(int v:adj[u])if(!seen[v]){seen[v]=true;st.push(v);}}\n  return false;\n}","statement":"Determine whether source and destination are connected in an undirected graph with vertices 0 through n-1.","example":"n = 3, edges = [[0,1],[1,2]], source = 0, destination = 2 → true"},"All Paths From Source to Target":{"idea":"The input is a directed acyclic graph. Extend the current path along every outgoing edge. Copy the path whenever vertex n minus one is reached; undo each choice before exploring the next edge","steps":["The input is a directed acyclic graph.","Extend the current path along every outgoing edge.","Copy the path whenever vertex n minus one is reached; undo each choice before exploring the next edge."],"time":"O(number of paths times V)","space":"O(V) auxiliary plus output","python":"def allPathsSourceTarget(graph):\n    if not graph: return []\n    out=[]; path=[0]\n    def dfs(u):\n        if u==len(graph)-1: out.append(path[:]); return\n        for v in graph[u]: path.append(v); dfs(v); path.pop()\n    dfs(0)\n    return out","js":"function allPathsSourceTarget(graph){\n  if(!graph.length)return [];const out=[],path=[0];\n  function dfs(u){if(u===graph.length-1){out.push([...path]);return;}for(const v of graph[u]){path.push(v);dfs(v);path.pop();}}\n  dfs(0);return out;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<vector<int>> allPathsSourceTarget(vector<vector<int>>& graph){\n  if(graph.empty())return {};vector<vector<int>> out;vector<int> path={0};\n  function<void(int)> dfs=[&](int u){if(u==graph.size()-1){out.push_back(path);return;}for(int v:graph[u]){path.push_back(v);dfs(v);path.pop_back();}};\n  dfs(0);return out;\n}","statement":"Return every directed path from vertex 0 to vertex n-1 in a DAG represented by adjacency lists.","example":"graph = [[1,2],[3],[3],[]] → [[0,1,3],[0,2,3]]"},"Reconstruct Itinerary":{"idea":"Use Hierholzer traversal to consume every ticket exactly once, starting at JFK. Always take the lexicographically smallest available destination. Add airports when no outgoing ticket remains, then reverse the resulting postorder; assumes a valid itinerary exists","steps":["Use Hierholzer traversal to consume every ticket exactly once, starting at JFK.","Always take the lexicographically smallest available destination.","Add airports when no outgoing ticket remains, then reverse the resulting postorder; assumes a valid itinerary exists."],"time":"O(E log E)","space":"O(V+E)","python":"from collections import defaultdict\ndef findItinerary(tickets):\n    adj=defaultdict(list)\n    for a,b in sorted(tickets,reverse=True): adj[a].append(b)\n    stack=['JFK']; route=[]\n    while stack:\n        if adj[stack[-1]]: stack.append(adj[stack[-1]].pop())\n        else: route.append(stack.pop())\n    return route[::-1]","js":"function findItinerary(tickets){\n  const adj=new Map();for(const [a,b] of tickets){if(!adj.has(a))adj.set(a,[]);adj.get(a).push(b);}\n  for(const a of adj.values())a.sort().reverse();const stack=['JFK'],route=[];\n  while(stack.length){const a=adj.get(stack.at(-1));if(a?.length)stack.push(a.pop());else route.push(stack.pop());}\n  return route.reverse();\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<string> findItinerary(vector<vector<string>>& tickets){\n  unordered_map<string,priority_queue<string,vector<string>,greater<string>>> adj;\n  for(auto& t:tickets)adj[t[0]].push(t[1]);vector<string> st={\"JFK\"},route;\n  while(!st.empty()){auto& q=adj[st.back()];if(!q.empty()){string v=q.top();q.pop();st.push_back(v);}else{route.push_back(st.back());st.pop_back();}}\n  reverse(route.begin(),route.end());return route;\n}","statement":"Use every airline ticket exactly once starting at JFK; return the lexicographically smallest valid itinerary.","example":"tickets = [[\"JFK\",\"SFO\"],[\"SFO\",\"ATL\"]] → [\"JFK\",\"SFO\",\"ATL\"]"},"Detect Cycle in Undirected Connected Graph":{"idea":"Traverse the undirected graph with the edge used to enter each vertex. An edge to an already visited vertex forms a cycle unless it is exactly that entering edge. Edge identifiers also handle parallel edges correctly","steps":["Traverse the undirected graph with the edge used to enter each vertex.","An edge to an already visited vertex forms a cycle unless it is exactly that entering edge.","Edge identifiers also handle parallel edges correctly."],"time":"O(V+E)","space":"O(V+E)","python":"def hasCycle(n,edges):\n    adj=[[] for _ in range(n)]\n    for i,(a,b) in enumerate(edges): adj[a].append((b,i)); adj[b].append((a,i))\n    seen=set()\n    for root in range(n):\n        if root in seen: continue\n        stack=[(root,-1)]; seen.add(root)\n        while stack:\n            u,parentEdge=stack.pop()\n            for v,e in adj[u]:\n                if e==parentEdge: continue\n                if v in seen: return True\n                seen.add(v); stack.append((v,e))\n    return False","js":"function hasCycle(n,edges){\n  const adj=Array.from({length:n},()=>[]);edges.forEach(([a,b],i)=>{adj[a].push([b,i]);adj[b].push([a,i]);});\n  const seen=new Set();for(let root=0;root<n;root++)if(!seen.has(root)){\n    const stack=[[root,-1]];seen.add(root);while(stack.length){const [u,parentEdge]=stack.pop();for(const [v,e] of adj[u]){\n      if(e===parentEdge)continue;if(seen.has(v))return true;seen.add(v);stack.push([v,e]);}}\n  }return false;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nbool hasCycle(int n,vector<vector<int>>& edges){\n  vector<vector<pair<int,int>>> adj(n);for(int i=0;i<edges.size();i++){int a=edges[i][0],b=edges[i][1];adj[a].push_back({b,i});adj[b].push_back({a,i});}\n  vector<bool> seen(n);for(int root=0;root<n;root++)if(!seen[root]){\n    stack<pair<int,int>> st;st.push({root,-1});seen[root]=true;\n    while(!st.empty()){auto item=st.top();int u=item.first,parentEdge=item.second;st.pop();for(auto edge:adj[u]){int v=edge.first,e=edge.second;\n      if(e==parentEdge)continue;if(seen[v])return true;seen[v]=true;st.push({v,e});}}\n  }return false;\n}","statement":"Determine whether an undirected graph contains a cycle; edges are given as endpoint pairs.","example":"n = 3, edges = [[0,1],[1,2],[2,0]] → true"},"Topological Sort (DFS)":{"idea":"Use three vertex states: unseen, active, and finished. An edge to an active vertex reveals a directed cycle. Append each vertex after all its descendants finish, then reverse that order; return an empty list for cyclic input","steps":["Use three vertex states: unseen, active, and finished.","An edge to an active vertex reveals a directed cycle.","Append each vertex after all its descendants finish, then reverse that order; return an empty list for cyclic input."],"time":"O(V+E)","space":"O(V)","python":"def topologicalSort(adj):\n    state=[0]*len(adj); order=[]\n    def dfs(u):\n        if state[u]==1: return False\n        if state[u]==2: return True\n        state[u]=1\n        for v in adj[u]:\n            if not dfs(v): return False\n        state[u]=2; order.append(u)\n        return True\n    for u in range(len(adj)):\n        if not dfs(u): return []\n    return order[::-1]","js":"function topologicalSort(adj){\n  const state=Array(adj.length).fill(0),order=[];\n  function dfs(u){if(state[u]===1)return false;if(state[u]===2)return true;state[u]=1;\n    for(const v of adj[u])if(!dfs(v))return false;state[u]=2;order.push(u);return true;}\n  for(let u=0;u<adj.length;u++)if(!dfs(u))return [];return order.reverse();\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nvector<int> topologicalSort(vector<vector<int>>& adj){\n  vector<int> state(adj.size()),order;\n  function<bool(int)> dfs=[&](int u){if(state[u]==1)return false;if(state[u]==2)return true;state[u]=1;\n    for(int v:adj[u])if(!dfs(v))return false;state[u]=2;order.push_back(u);return true;};\n  for(int u=0;u<adj.size();u++)if(!dfs(u))return {};reverse(order.begin(),order.end());return order;\n}","statement":"Return a vertex ordering placing each directed edge’s source before its destination, or [] if cyclic.","example":"adjacency = [[1,2],[3],[3],[]] → [0,2,1,3]"},"Number of Operations to Make Network Connected":{"idea":"A connected network needs at least n minus one cables. If enough cables exist, use disjoint-set union to count connected components. Reconnect redundant cables between components; exactly components minus one moves are needed","steps":["A connected network needs at least n minus one cables.","If enough cables exist, use disjoint-set union to count connected components.","Reconnect redundant cables between components; exactly components minus one moves are needed."],"time":"O((V+E) alpha(V))","space":"O(V)","python":"def makeConnected(n,connections):\n    if len(connections)<n-1: return -1\n    parent=list(range(n)); size=[1]*n; count=n\n    def find(x):\n        while x!=parent[x]: parent[x]=parent[parent[x]]; x=parent[x]\n        return x\n    for a,b in connections:\n        a,b=find(a),find(b)\n        if a!=b:\n            if size[a]<size[b]: a,b=b,a\n            parent[b]=a; size[a]+=size[b]; count-=1\n    return max(0,count-1)","js":"function makeConnected(n,connections){\n  if(connections.length<n-1)return -1;const p=Array.from({length:n},(_,i)=>i),size=Array(n).fill(1);let count=n;\n  function find(x){while(x!==p[x]){p[x]=p[p[x]];x=p[x];}return x;}\n  for(let [a,b] of connections){a=find(a);b=find(b);if(a!==b){if(size[a]<size[b])[a,b]=[b,a];p[b]=a;size[a]+=size[b];count--;}}\n  return Math.max(0,count-1);\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint makeConnected(int n,vector<vector<int>>& connections){\n  if((int)connections.size()<n-1)return -1;vector<int> p(n),size(n,1);iota(p.begin(),p.end(),0);int count=n;\n  function<int(int)> find=[&](int x){return p[x]==x?x:p[x]=find(p[x]);};\n  for(auto e:connections){int a=find(e[0]),b=find(e[1]);if(a!=b){if(size[a]<size[b])swap(a,b);p[b]=a;size[a]+=size[b];count--;}}\n  return max(0,count-1);\n}","statement":"Move existing network cables to connect all n computers using the fewest moves, or return -1 if impossible.","example":"n = 4, connections = [[0,1],[0,2],[1,2]] → 1"},"Cheapest Flights Within K Stops":{"idea":"At most k stops permits at most k plus one edges. Run that many Bellman-Ford relaxation rounds. Read from the previous round and write into a copy so one round cannot accidentally use multiple new edges","steps":["At most k stops permits at most k plus one edges.","Run that many Bellman-Ford relaxation rounds.","Read from the previous round and write into a copy so one round cannot accidentally use multiple new edges."],"time":"O((k+1) E)","space":"O(V)","python":"def findCheapestPrice(n,flights,src,dst,k):\n    dist=[float('inf')]*n; dist[src]=0\n    for _ in range(k+1):\n        nxt=dist[:]\n        for a,b,w in flights: nxt[b]=min(nxt[b],dist[a]+w)\n        dist=nxt\n    return -1 if dist[dst]==float('inf') else dist[dst]","js":"function findCheapestPrice(n,flights,src,dst,k){\n  let dist=Array(n).fill(Infinity);dist[src]=0;\n  for(let i=0;i<=k;i++){const next=[...dist];for(const [a,b,w] of flights)next[b]=Math.min(next[b],dist[a]+w);dist=next;}\n  return dist[dst]===Infinity?-1:dist[dst];\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint findCheapestPrice(int n,vector<vector<int>>& flights,int src,int dst,int k){\n  const long long INF=LLONG_MAX/4;vector<long long> dist(n,INF);dist[src]=0;\n  for(int i=0;i<=k;i++){auto next=dist;for(auto e:flights)next[e[1]]=min(next[e[1]],dist[e[0]]+e[2]);dist=move(next);}\n  return dist[dst]==INF?-1:dist[dst];\n}","statement":"Find the cheapest directed flight route from src to dst using at most k intermediate stops, or -1.","example":"n = 3, flights = [[0,1,100],[1,2,100],[0,2,500]], src = 0, dst = 2, k = 1 → 200"},"Number of Ways to Arrive at Destination":{"idea":"Use Dijkstra because road times are positive. A shorter route replaces both the best distance and its route count; an equal route adds its count. Return the destination count modulo one billion plus seven","steps":["Use Dijkstra because road times are positive.","A shorter route replaces both the best distance and its route count; an equal route adds its count.","Return the destination count modulo one billion plus seven."],"time":"O((V+E) log V)","space":"O(V+E)","python":"import heapq\ndef countPaths(n,roads):\n    MOD=10**9+7; adj=[[] for _ in range(n)]\n    for a,b,w in roads: adj[a].append((b,w)); adj[b].append((a,w))\n    dist=[float('inf')]*n; ways=[0]*n; dist[0]=0; ways[0]=1; heap=[(0,0)]\n    while heap:\n        d,u=heapq.heappop(heap)\n        if d!=dist[u]: continue\n        for v,w in adj[u]:\n            nd=d+w\n            if nd<dist[v]: dist[v]=nd; ways[v]=ways[u]; heapq.heappush(heap,(nd,v))\n            elif nd==dist[v]: ways[v]=(ways[v]+ways[u])%MOD\n    return ways[-1]","js":"// Min-heap; pass (a,b)=>b-a for a max-heap.\nclass Heap {\n  constructor(cmp=(a,b)=>a-b){this.a=[];this.cmp=cmp;}\n  get size(){return this.a.length;}\n  peek(){return this.a[0];}\n  push(x){const a=this.a;a.push(x);let i=a.length-1;\n    while(i){let p=(i-1)>>1;if(this.cmp(a[p],a[i])<=0)break;[a[p],a[i]]=[a[i],a[p]];i=p;}}\n  pop(){const a=this.a;if(!a.length)return undefined;const out=a[0],x=a.pop();\n    if(a.length){a[0]=x;let i=0;while(true){let j=2*i+1;if(j>=a.length)break;\n      if(j+1<a.length&&this.cmp(a[j+1],a[j])<0)j++;\n      if(this.cmp(a[i],a[j])<=0)break;[a[i],a[j]]=[a[j],a[i]];i=j;}}\n    return out;}\n}\nfunction countPaths(n,roads){\n  const MOD=1000000007,adj=Array.from({length:n},()=>[]);for(const [a,b,w] of roads){adj[a].push([b,w]);adj[b].push([a,w]);}\n  const dist=Array(n).fill(Infinity),ways=Array(n).fill(0),h=new Heap((a,b)=>a[0]-b[0]);dist[0]=0;ways[0]=1;h.push([0,0]);\n  while(h.size){const [d,u]=h.pop();if(d!==dist[u])continue;for(const [v,w] of adj[u]){const nd=d+w;\n    if(nd<dist[v]){dist[v]=nd;ways[v]=ways[u];h.push([nd,v]);}else if(nd===dist[v])ways[v]=(ways[v]+ways[u])%MOD;\n  }}return ways[n-1];\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint countPaths(int n,vector<vector<int>>& roads){\n  const int MOD=1000000007;vector<vector<pair<int,int>>> adj(n);for(auto e:roads){adj[e[0]].push_back({e[1],e[2]});adj[e[1]].push_back({e[0],e[2]});}\n  using P=pair<long long,int>;priority_queue<P,vector<P>,greater<P>> h;vector<long long> dist(n,LLONG_MAX),ways(n);dist[0]=0;ways[0]=1;h.push({0,0});\n  while(!h.empty()){auto item=h.top();long long d=item.first;int u=item.second;h.pop();if(d!=dist[u])continue;for(auto edge:adj[u]){int v=edge.first,w=edge.second;long long nd=d+w;\n    if(nd<dist[v]){dist[v]=nd;ways[v]=ways[u];h.push({nd,v});}else if(nd==dist[v])ways[v]=(ways[v]+ways[u])%MOD;\n  }}return ways[n-1];\n}","statement":"Count shortest routes from vertex 0 to n-1 in a positive-weight undirected road network, modulo 1,000,000,007.","example":"n = 4, roads = [[0,1,1],[1,3,1],[0,2,1],[2,3,1]] → 2"},"Min Cost to Connect All Points":{"idea":"Use Prim to grow a minimum spanning tree of the complete Manhattan-distance graph. Track each unused point’s cheapest connection to the current tree. Add the cheapest available point, then update all remaining connection costs","steps":["Use Prim to grow a minimum spanning tree of the complete Manhattan-distance graph.","Track each unused point’s cheapest connection to the current tree.","Add the cheapest available point, then update all remaining connection costs."],"time":"O(n^2)","space":"O(n)","python":"def minCostConnectPoints(points):\n    n=len(points)\n    if n==0: return 0\n    best=[float('inf')]*n; used=[False]*n; best[0]=0; total=0\n    for _ in range(n):\n        u=min((i for i in range(n) if not used[i]),key=lambda i:best[i])\n        total+=best[u]; used[u]=True\n        for v in range(n):\n            if not used[v]: best[v]=min(best[v],abs(points[u][0]-points[v][0])+abs(points[u][1]-points[v][1]))\n    return total","js":"function minCostConnectPoints(points){\n  const n=points.length;if(!n)return 0;const best=Array(n).fill(Infinity),used=Array(n).fill(false);best[0]=0;let total=0;\n  for(let step=0;step<n;step++){\n    let u=-1;for(let i=0;i<n;i++)if(!used[i]&&(u<0||best[i]<best[u]))u=i;\n    total+=best[u];used[u]=true;for(let v=0;v<n;v++)if(!used[v])best[v]=Math.min(best[v],Math.abs(points[u][0]-points[v][0])+Math.abs(points[u][1]-points[v][1]));\n  }return total;\n}","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n// TreeNode / Node are supplied by the problem when needed.\n\nint minCostConnectPoints(vector<vector<int>>& points){\n  int n=points.size();if(!n)return 0;vector<int> best(n,INT_MAX);vector<bool> used(n);best[0]=0;int total=0;\n  for(int step=0;step<n;step++){\n    int u=-1;for(int i=0;i<n;i++)if(!used[i]&&(u<0||best[i]<best[u]))u=i;\n    total+=best[u];used[u]=true;for(int v=0;v<n;v++)if(!used[v])best[v]=min(best[v],abs(points[u][0]-points[v][0])+abs(points[u][1]-points[v][1]));\n  }return total;\n}","statement":"Connect every 2D point with minimum total edge cost, where each edge costs the Manhattan distance.","example":"points = [[0,0],[2,2],[3,10],[5,2],[7,0]] → 20"}};
